// Real, full geographic data for the signup Country/State dropdowns — every
// live country, with real state/province/region subdivisions where we have
// them. City stays free text (see the input in the signup form) rather
// than trying to enumerate every city on earth.
const FALLBACK_GEO = {
  countries: ['United States', 'Nigeria', 'Ghana', 'Liberia'],
  statesByCountry: {
    'United States': ['Georgia', 'New York', 'California', 'Texas', 'Florida'],
    'Nigeria': ['Lagos', 'Federal Capital Territory', 'Kano', 'Rivers'],
    'Ghana': ['Greater Accra', 'Ashanti', 'Western'],
    'Liberia': ['Montserrado', 'Bong', 'Nimba'],
  },
  noPostalCodeCountries: ['Ghana'],
  dialCodeByCountry: { 'United States': '+1', 'Nigeria': '+234', 'Ghana': '+233', 'Liberia': '+231' },
};
let GEO_DATA = FALLBACK_GEO;

// Animates a number counting up from 0 to its real value — purely a
// presentation effect on top of already-real data (see loadPlatformStats
// below), not a fake "live ticking counter." Respects prefers-reduced-motion
// by just jumping straight to the final value for anyone who's asked their
// OS/browser to minimize motion.
function animateCountUp(el, target, { suffix = '', decimals = 0, duration = 1200 } = {}) {
  if (!el) return;
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion || !isFinite(target)) { el.textContent = target.toLocaleString(undefined, { maximumFractionDigits: decimals }) + suffix; return; }
  const start = performance.now();
  const from = 0;
  function tick(now) {
    const progress = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic — decelerates near the end, reads as more natural than linear
    const value = from + (target - from) * eased;
    el.textContent = value.toLocaleString(undefined, { maximumFractionDigits: decimals }) + suffix;
    if (progress < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

async function loadPlatformStats() {
  const els = {
    pros: document.getElementById('hero-stat-pros'),
    rating: document.getElementById('hero-stat-rating'),
    jobs: document.getElementById('hero-stat-jobs'),
  };
  if (!els.pros) return;
  if (!BACKEND_AVAILABLE) {
    els.pros.textContent = '—'; els.rating.textContent = '—'; els.jobs.textContent = '—';
    return;
  }
  try {
    const stats = await apiFetch('GET', '/platform-stats');
    const run = () => {
      animateCountUp(els.pros, stats.verifiedProsCount);
      if (stats.averageRating) animateCountUp(els.rating, Number(stats.averageRating), { suffix: '★', decimals: 1 });
      else els.rating.textContent = 'New';
      animateCountUp(els.jobs, stats.jobsCompletedCount);
    };
    const band = document.querySelector('.stats-strip');
    if (band && band.dataset.waiting) band._pending = run; else run();
  } catch (e) {
    console.warn('Could not load platform stats', e);
  }
}

async function loadGeoData() {
  if (BACKEND_AVAILABLE) {
    try {
      const data = await apiFetch('GET', '/geo');
      if (data.countries && data.countries.length) GEO_DATA = data;
    } catch (e) { console.warn('Could not load geo data from API, using demo data.', e); }
  }
  const select = document.getElementById('auth-country');
  if (select) {
    const current = select.value;
    select.innerHTML = GEO_DATA.countries.map(c => `<option value="${escapeHtml(c)}">${c}</option>`).join('');
    // Default to United States if nothing was already chosen, since it's
    // the most common case — but preserve whatever was already selected if
    // this is a refresh rather than a first load.
    select.value = GEO_DATA.countries.includes(current) ? current : (GEO_DATA.countries.includes('United States') ? 'United States' : GEO_DATA.countries[0]);
    populateAuthStates();
  }
}

function populateAuthStates() {
  const country = document.getElementById('auth-country').value;
  const states = (GEO_DATA.statesByCountry && GEO_DATA.statesByCountry[country]) || ['Nationwide'];
  const stateSelect = document.getElementById('auth-state');
  if (stateSelect) {
    stateSelect.innerHTML = `<option value="" disabled selected>Select a state / region</option>` + states.map(s => `<option value="${escapeHtml(s)}">${s}</option>`).join('');
  }
  // Some countries genuinely have no formal postal code system — for
  // those, the field becomes optional rather than pretending a format
  // exists that doesn't.
  const noPostalCode = (GEO_DATA.noPostalCodeCountries || []).includes(country);
  const zipLabel = document.getElementById('auth-zip-label');
  const zipHint = document.getElementById('auth-zip-hint');
  if (zipLabel) zipLabel.textContent = noPostalCode ? 'Zip / Postal Code (optional)' : 'Zip / Postal Code';
  if (zipHint) zipHint.style.display = noPostalCode ? 'block' : 'none';

  // Real country calling code, shown as a fixed prefix so nobody has to
  // remember or type their own country's dial code — they just type the
  // rest of their number after it.
  const dialCodeBadge = document.getElementById('auth-phone-dialcode');
  if (dialCodeBadge) {
    dialCodeBadge.textContent = (GEO_DATA.dialCodeByCountry && GEO_DATA.dialCodeByCountry[country]) || '+1';
  }
}

// Populates the Country dropdown in Settings (customer or provider) with
// the real, current list of live countries, pre-selecting whatever the
// account's real current country is — then cascades into the matching
// State dropdown. `prefix` is 'cust' or 'prov'.
function populateSettingsCountry(prefix) {
  const select = document.getElementById(`set-${prefix}-country`);
  if (!select) return;
  const countries = (GEO_DATA.countries && GEO_DATA.countries.length) ? GEO_DATA.countries : FALLBACK_GEO.countries;
  const current = (AUTH.user && AUTH.user.country) || 'United States';
  select.innerHTML = countries.map(c => `<option value="${escapeHtml(c)}" ${c === current ? 'selected' : ''}>${c}</option>`).join('');
  populateSettingsStates(prefix);
}

function populateSettingsStates(prefix) {
  const countrySelect = document.getElementById(`set-${prefix}-country`);
  const stateSelect = document.getElementById(`set-${prefix}-state`);
  if (!countrySelect || !stateSelect) return;
  const country = countrySelect.value;
  const states = (GEO_DATA.statesByCountry && GEO_DATA.statesByCountry[country]) || ['Nationwide'];
  const current = (AUTH.user && AUTH.user.state) || '';
  stateSelect.innerHTML = states.map(s => `<option value="${escapeHtml(s)}" ${s === current ? 'selected' : ''}>${s}</option>`).join('');
}

