// Populates the Settings category dropdown with the real, current list of
// active categories, pre-selecting whatever the provider's account
// currently has — falling back to "Other" if their current category isn't
// (or is no longer) a real listed one.
function populateSettingsCategory() {
  const select = document.getElementById('set-prov-category');
  if (!select) return;
  const current = (AUTH.user && AUTH.user.category) || '';
  const catNames = (CATEGORIES && CATEGORIES.length) ? CATEGORIES.map(c => c.name) : [];
  const isListed = catNames.includes(current);
  select.innerHTML = catNames.map(c => `<option value="${escapeHtml(c)}" ${c === current ? 'selected' : ''}>${c}</option>`).join('')
    + `<option value="__other__" ${!isListed ? 'selected' : ''}>Other (not listed — describe below)</option>`;
  const customGroup = document.getElementById('set-prov-custom-category-group');
  const customInput = document.getElementById('set-prov-custom-category');
  if (!isListed && current) {
    customGroup.style.display = 'block';
    customInput.value = current;
  }
}

// A real status indicator — expired, expiring soon (within 30 days), or
// valid — computed from the actual date on file, not decorative. No date
// on file shows neutrally rather than implying a problem, since this
// isn't a required field.
function licenseInsuranceStatusHTML(dateStr, label) {
  if (!dateStr) return `<div style="font-size:13px;color:var(--muted);margin-bottom:6px;">No ${label.toLowerCase()} expiry date on file yet.</div>`;
  // Matches the real enforcement in hasValidLicense() exactly: the
  // stated expiry date is the first invalid day, not the day after —
  // "no grace period" per the Provider Agreement. This display must
  // agree with that cutoff, or a provider could see "still valid" while
  // simultaneously being blocked from accepting a job.
  const expiry = new Date(dateStr + 'T00:00:00.000Z');
  const daysLeft = Math.ceil((expiry - new Date()) / (1000 * 60 * 60 * 24));
  if (daysLeft <= 0) return `<div style="font-size:13px;color:#C0392B;font-weight:600;margin-bottom:6px;">⚠ ${label} expired${daysLeft < 0 ? ` ${Math.abs(daysLeft)} day${Math.abs(daysLeft) === 1 ? '' : 's'} ago` : ' today'}</div>`;
  if (daysLeft <= 30) return `<div style="font-size:13px;color:var(--gold);font-weight:600;margin-bottom:6px;">⚠ ${label} expires in ${daysLeft} day${daysLeft === 1 ? '' : 's'}</div>`;
  return `<div style="font-size:13px;color:#2E8C6F;font-weight:600;margin-bottom:6px;">✓ ${label} valid until ${expiry.toLocaleDateString()}</div>`;
}

async function saveLicenseInsurance() {
  const licenseExpiryDate = document.getElementById('set-prov-license-expiry').value || null;
  const insuranceExpiryDate = document.getElementById('set-prov-insurance-expiry').value || null;
  if (!BACKEND_AVAILABLE) return showToast('Requires a live backend connection');
  try {
    await apiFetch('PATCH', '/auth/me', { licenseExpiryDate, insuranceExpiryDate });
    AUTH.user.licenseExpiryDate = licenseExpiryDate;
    AUTH.user.insuranceExpiryDate = insuranceExpiryDate;
    showToast('License & insurance info saved');
    selectProviderSection('settings');
  } catch (e) { showToast(e.message || 'Could not save this'); }
}

async function saveProviderCategory() {
  const select = document.getElementById('set-prov-category').value;
  const category = select === '__other__'
    ? document.getElementById('set-prov-custom-category').value.trim().replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    : select;
  if (!category || category.length < 2) return showToast('Enter or select a category');
  if (!BACKEND_AVAILABLE) return showToast('Category updated (demo mode)');
  try {
    const { user } = await apiFetch('PATCH', '/auth/me', { category });
    AUTH.user = user;
    showToast(user.categoryApprovalStatus === 'pending'
      ? `Category saved — "${category}" is pending a quick admin review (within 24 hours). You can keep using your account normally.`
      : `Category updated to "${user.category}"`);
    selectProviderSection('settings');
  } catch (e) { showToast(e.message || 'Could not update category'); }
}

// A plain directory index (name, dotted leader, number of pros) rather
// than a wall of emoji tiles: easier to scan with 60 categories.
function categoryCardsHTML(list) {
  return list.map(c => {
    const n = typeof c.proCount === 'number' ? c.proCount : null;
    const count = n === null ? '' : n === 0 ? t('cat_none') : `${n} ${n === 1 ? t('pro_one') : t('pro_many')}`;
    return `<button type="button" class="cat-row" data-catname="${escapeHtml(c.name)}" onclick="goDirectory(this.dataset.catname)"><span class="cat-name">${escapeHtml(translateCategoryName(c.name))}</span><span class="cat-leader" aria-hidden="true"></span><span class="cat-n">${count}</span></button>`;
  }).join('');
}

// A curated homepage FAQ — the answers are pulled live from the exact
// same lookup the support chat itself uses (answerSupportQuestion), not a
// separate copy of the text. If the chat's real answer ever changes,
// this section changes with it automatically; there's no second place
// to remember to update.
const HOMEPAGE_FAQ_ITEMS = [
  { question: 'How does escrow actually protect me?', lookup: 'escrow' },
  { question: 'How are pros verified?', lookup: 'verification' },
  { question: 'What if something goes wrong with a job?', lookup: 'dispute' },
  { question: 'How does matching work?', lookup: 'how does matching work' },
  { question: 'What are the pricing plans?', lookup: 'pricing plan' },
  { question: 'How do I become a pro on Trothen?', lookup: 'become a pro' },
];

function renderHomepageFAQ() {
  const list = document.getElementById('homepage-faq-list');
  if (!list) return;
  list.innerHTML = HOMEPAGE_FAQ_ITEMS.map((item, i) => `
    <div class="faq-item" id="faq-item-${i}">
      <div class="faq-question" onclick="toggleFAQItem(${i})">
        <span>${escapeHtml(t('faq_q' + (i + 1)))}</span>
        <span class="faq-chevron">▾</span>
      </div>
      <div class="faq-answer"><div class="faq-answer-inner">${faqAnswerHTML(item, i)}</div></div>
    </div>`).join('');
}

// v74: the super admin can write a homepage-only answer (Admin → Settings →
// Front page wording). Left blank, the answer is the support chat's own.
function faqAnswerHTML(item, i) {
  const own = (CURRENT_LANG === 'en' && typeof CONTENT_OVERRIDES !== 'undefined' && CONTENT_OVERRIDES['faq_a' + (i + 1)]) || '';
  return own ? escapeHtml(own) : answerSupportQuestion(item.lookup);
}

function toggleFAQItem(i) {
  const el = document.getElementById(`faq-item-${i}`);
  if (el) el.classList.toggle('open');
}

function renderHomeCategories() {
  document.getElementById('categories-grid').innerHTML = categoryCardsHTML(CATEGORIES);
  document.getElementById('categories-sub').textContent = `${CATEGORIES.length} ${t(CATEGORIES.length === 1 ? 'cats_count_one' : 'cats_count_many')}`;
}

function goCategoriesPage() {
  showScreen('screen-categories');
  renderNavbar('navbar-categories', 'home');
  document.getElementById('categories-page-sub').textContent = `${CATEGORIES.length} service type${CATEGORIES.length === 1 ? '' : 's'} available — tap any to see its providers`;
  document.getElementById('categories-page-grid').innerHTML = categoryCardsHTML(CATEGORIES);
  window.scrollTo(0, 0);
}

/* ══════════════════════ PROVIDER DIRECTORY (full "View all" page) ══════════════════════ */
let directoryCategoryFilter = 'All';

function goDirectory(category) {
  directoryCategoryFilter = category || 'All';
  showScreen('screen-directory');
  renderNavbar('navbar-directory', 'home');
  document.getElementById('directory-search').value = '';
  const chips = ['All', ...CATEGORIES.map(c => c.name)];
  document.getElementById('directory-chips').innerHTML = chips.map(c =>
    `<button class="directory-chip ${c === directoryCategoryFilter ? 'active' : ''}" onclick="setDirectoryCategory(${jsArg(c)})">${escapeHtml(c === 'All' ? t('directory_all') : translateCategoryName(c))}</button>`
  ).join('');
  renderDirectory();
  window.scrollTo(0, 0);
}

function setDirectoryCategory(category) {
  directoryCategoryFilter = category;
  document.querySelectorAll('.directory-chip').forEach(el => el.classList.toggle('active', el.textContent === category));
  renderDirectory();
}

function renderDirectory() {
  const q = document.getElementById('directory-search').value.trim().toLowerCase();
  const sortBy = document.getElementById('directory-sort') ? document.getElementById('directory-sort').value : 'best';
  let list = PROVIDERS.slice();
  if (directoryCategoryFilter && directoryCategoryFilter !== 'All') list = list.filter(p => proHasSkill(p, directoryCategoryFilter));
  if (q) {
    const synonymCategories = categoriesForSearchTerm(q);
    list = list.filter(p =>
      p.name.toLowerCase().includes(q) ||
      p.role.toLowerCase().includes(q) ||
      (p.tags || []).some(t => t.toLowerCase().includes(q)) ||
      synonymCategories.includes(p.cat) || (p.skills || []).some(sk => sk.toLowerCase().includes(needle) || synonymCategories.includes(sk))
    );
  }
  // "Best Match" leaves the server's own ordering alone (already
  // real, distance/relevance-aware — see GET /providers). The other
  // options are a genuine, real sort a person actually asked for and
  // that didn't exist before this.
  if (sortBy === 'score') list.sort((a, b) => (b.trustScore ?? -1) - (a.trustScore ?? -1));
  else if (sortBy === 'rating') list.sort((a, b) => (b.rating || 0) - (a.rating || 0));
  else if (sortBy === 'jobs') list.sort((a, b) => (b.jobs || 0) - (a.jobs || 0));
  else if (sortBy === 'distance') list.sort((a, b) => (a.distanceMiles ?? Infinity) - (b.distanceMiles ?? Infinity));
  document.getElementById('directory-sub').textContent = `${list.length} verified provider${list.length === 1 ? '' : 's'}${directoryCategoryFilter !== 'All' ? ' in ' + directoryCategoryFilter : ''}`;
  document.getElementById('directory-grid').innerHTML = providerCardsHTML(list);
}


