// Looks up the real category's display name in the current language,
// falling back to its actual (English) name when no translation exists
// yet — a category an admin adds later, for instance. The real English
// name is always what's still sent to the backend for filtering/search;
// this only ever changes what's shown on screen.
function translateCategoryName(name) {
  const table = CATEGORY_TRANSLATIONS[CURRENT_LANG];
  return (table && table[name]) || name;
}

