const PLAN_LABELS = { starter: 'Starter', pro: 'Pro', superpro: 'Super Pro' };

async function selectPlan(plan) {
  // Only the Starter button calls this now — Pro and Super-Pro are
  // reached automatically (Pro) or by real admin review (Super-Pro), not
  // by clicking a button, which was the actual bug this replaced.
  if (AUTH.token && AUTH.user && AUTH.user.role === 'provider') {
    return showToast(AUTH.user.plan === 'starter' ? "You're already on the Starter plan" : `You're on the ${PLAN_LABELS[AUTH.user.plan] || 'Starter'} plan — check your dashboard to see your progress toward the next tier.`);
  }
  // Not signed in as a provider yet — get them signed up first, and
  // remember which plan they picked so we can apply it right after.
  pendingPlanSelection = plan;
  setAuthRolePreselect('provider');
  showToast(`Sign up as a provider to start on the ${PLAN_LABELS[plan]} plan`);
}
let pendingPlanSelection = null;

function renderNavbar(slotId, active) {
  const el = document.getElementById(slotId);
  if (el) {
    el.innerHTML = navbarHTML(active);
    // Recorded so setLanguage() can find and correctly re-render every
    // navbar instance currently in the page — each screen's navbar is
    // rendered into its own separate slot and only ever updated when
    // that specific screen is (re)entered, so without this, switching
    // languages would leave every OTHER already-rendered navbar (behind
    // whichever screen is currently hidden) still showing the old
    // language's button text until something else happened to
    // re-render it.
    el.dataset.navActive = active;
  }
}

function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  window.scrollTo(0, 0);
}

async function goToCustomerDashboard(sectionKey) {
  showScreen('screen-customer');
  await refreshNotifications();
  renderNavbar('navbar-customer', 'customer');
  await initCustomerDash();
  selectCustomerSection(sectionKey || 'overview');
}

function goHome() {
  showScreen('screen-home');
  // A logged-in customer still gets their real navbar (bell + account
  // menu) on the homepage — only an actual signed-out visitor, or a
  // logged-in provider/admin who's navigated here, sees the plain
  // signed-out version.
  const navbarActive = AUTH.user ? (AUTH.user.role === 'admin' ? (AUTH.user.isSuperAdmin ? 'superadmin' : 'admin') : AUTH.user.role) : 'home';
  renderNavbar('navbar-home', navbarActive);
  const welcomeBanner = document.getElementById('customer-welcome-banner');
  if (welcomeBanner) {
    if (AUTH.user && AUTH.user.role === 'customer') {
      welcomeBanner.style.display = 'block';
      welcomeBanner.innerHTML = `
        <div class="customer-welcome-banner">
          <div>
            <div class="customer-welcome-text">Welcome back, ${escapeHtml(AUTH.user.name.split(' ')[0])} 👋</div>
            <div class="customer-welcome-sub" id="welcome-banner-stats">${AUTH.user.verified ? '✓ Verified account' : '⏳ Verification pending'} — showing pros in ${escapeHtml(AUTH.user.country || 'your area')}</div>
          </div>
          <div class="customer-welcome-actions">
            <button class="btn-sm btn-sm-outline" onclick="goToCustomerDashboard('bookings')">My Bookings</button>
            <button class="nav-btn nav-cta" onclick="openPostJobModal()">+ Post a Job</button>
          </div>
        </div>`;
      // A real, live count — not a placeholder — of this customer's
      // actual active bookings, added to the subtitle once it's loaded.
      if (BACKEND_AVAILABLE) {
        loadCustomerData().then(() => {
          const statsEl = document.getElementById('welcome-banner-stats');
          if (!statsEl) return; // navigated away before this resolved
          const active = customerData.bookings.filter(b => b.status === 'confirmed' || b.status === 'active').length;
          const bookingText = active > 0 ? ` · ${active} active booking${active === 1 ? '' : 's'}` : '';
          statsEl.textContent = `${AUTH.user.verified ? '✓ Verified account' : '⏳ Verification pending'} — showing pros in ${AUTH.user.country || 'your area'}${bookingText}`;
        }).catch(() => {});
      }
    } else {
      welcomeBanner.style.display = 'none';
      welcomeBanner.innerHTML = '';
    }
  }
  loadFeaturedCarousel();
  loadPlatformStats();
  const locInput = document.getElementById('search-location-input');
  if (locInput && AUTH.user && AUTH.user.city) {
    locInput.value = AUTH.user.state ? `${AUTH.user.city}, ${AUTH.user.state}` : AUTH.user.city;
  }
  // Re-fetch the main provider grid too — otherwise a customer who signs
  // in and comes back to Explore would still see the stale, unscoped mix
  // of every country that loaded before we knew who they were.
  if (BACKEND_AVAILABLE) loadProviders().then(() => renderProviders(PROVIDERS));
}

// Distinct from goHome(): this actually ends the session (clears the token
// and user in memory) before navigating home. goHome() alone is also used
// for ordinary navigation (e.g. clicking the logo while still logged in),
// so it must NOT clear auth state itself — only an explicit "Sign Out"
// action should do that.
async function logout() {
  try { stopLiveTrip(); closeTripTracking(); } catch (e) { /* v93: never leave location sharing running after sign-out */ }
  stopIdleTimer();
  stopMessagePolling();
  // Real server-side sign-out (see POST /auth/logout) — best-effort: if
  // this fails (offline, server hiccup), the person should still be able
  // to sign out of THIS device/tab, which the local clearing below always
  // does regardless.
  if (BACKEND_AVAILABLE && AUTH.token) {
    try { await apiFetch('POST', '/auth/logout', {}); } catch (e) { /* local sign-out still proceeds below */ }
  }
  AUTH.token = null;
  AUTH.user = null;
  clearAuthSession();
  showToast('Signed out');
  goHome();
}

// Plays a short, soft two-tone chime using the Web Audio API — no external
// audio file needed. Only ever called when the person has opted in via
// their notification preferences (default off), so it never surprises
// anyone who didn't ask for it.
function playMessageSound() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const now = ctx.currentTime;
    // Three rings, evenly spaced, each ring being the same two-tone chime
    // the old single beep used — a real short ringtone cadence instead of
    // one blip that's easy to miss if you're not looking right at the
    // screen the instant it happens.
    const ringSpacing = 0.55;
    for (let ring = 0; ring < 3; ring++) {
      const ringStart = ring * ringSpacing;
      [[880, 0], [1108, 0.1]].forEach(([freq, delay]) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0, now + ringStart + delay);
        gain.gain.linearRampToValueAtTime(0.15, now + ringStart + delay + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, now + ringStart + delay + 0.35);
        osc.connect(gain).connect(ctx.destination);
        osc.start(now + ringStart + delay);
        osc.stop(now + ringStart + delay + 0.4);
      });
    }
  } catch (e) { /* Web Audio unavailable — fail silently, never break the app over a sound */ }
}

// Lightweight polling — the app has no real-time push channel, so this is
// what actually makes "play a sound for a new message" true rather than a
// setting that does nothing. Checks notifications every 5s while signed
// in, and only sounds the alert for a notification whose id genuinely
// wasn't seen on the previous check (never replays on first load or on a
// page the person just opened themselves).
let messagePollInterval = null;
let seenNotificationIds = null;
// Items 1 & 2 / the "provider not receiving texts with tone" report: sound
// used to only fire for chat messages — a customer's "provider arrived"
// alert and a provider's "new job match"/"you were selected" alert never
// made a sound at all, which is exactly backwards for the two most
// time-sensitive notifications this app has. Both already use these two
// real linkTo.section values (see on-my-way/arrived and job-match/select-
// provider in the backend), so this is the real, minimal fix rather than
// adding new plumbing: sound (and vibration, where supported) now fires
// for messages, bookings, and matches alike.
const SOUND_WORTHY_SECTIONS = ['messages', 'bookings', 'matches'];
async function startMessagePolling() {
  stopMessagePolling();
  if (!BACKEND_AVAILABLE || !AUTH.token) return;
  try {
    const { notifications } = await apiFetch('GET', '/notifications/mine');
    CURRENT_NOTIFICATIONS = notifications;
    seenNotificationIds = new Set(notifications.map(n => n.id));
  } catch (e) { seenNotificationIds = new Set(); }
  messagePollInterval = setInterval(async () => {
    if (!AUTH.token) return stopMessagePolling();
    const soundOn = AUTH.user && AUTH.user.notifPrefs && AUTH.user.notifPrefs.messageSound;
    try {
      const { notifications } = await apiFetch('GET', '/notifications/mine');
      const newOnes = notifications.filter(n => !seenNotificationIds.has(n.id));
      seenNotificationIds = new Set(notifications.map(n => n.id));
      if (!newOnes.length) return; // nothing changed — don't touch the DOM for no reason
      CURRENT_NOTIFICATIONS = notifications;
      if (soundOn && newOnes.some(n => n.linkTo && SOUND_WORTHY_SECTIONS.includes(n.linkTo.section))) {
        playMessageSound();
        // Vibration where the device/browser actually supports it (mostly
        // mobile Chrome/Android) — silently does nothing everywhere else,
        // including iOS Safari, which has no vibrate() API at all.
        if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      }
      // Show the unread dot on whichever bell is actually in the DOM right
      // now, without re-rendering the whole navbar (which would be
      // disruptive if a dropdown happens to be open at that moment) — same
      // lightweight direct-DOM-update approach dismissNotification and
      // clearAllNotifications already use for this exact dot.
      document.querySelectorAll('.notif-bell').forEach(bell => {
        if (!bell.querySelector('.notif-dot')) bell.insertAdjacentHTML('beforeend', '<span class="notif-dot"></span>');
      });
      // If the panel happens to already be open when a new one arrives,
      // update its contents live rather than making the person close and
      // reopen it to see what just came in.
      document.querySelectorAll('.notif-panel.open').forEach(p => { p.innerHTML = notifPanelInnerHTML(); });
    } catch (e) { /* a failed poll just tries again next interval */ }
  }, 5000);
}
function stopMessagePolling() {
  if (messagePollInterval) clearInterval(messagePollInterval);
  messagePollInterval = null;
  seenNotificationIds = null;
}

/* ══════════════════════ AUTH ══════════════════════ */
const authState = { mode: 'login', role: 'customer', isGoogleFlow: false, googleIdToken: null };

function showAuth(mode) {
  showScreen('screen-auth');
  renderNavbar('navbar-auth', 'auth');
  setAuthMode(mode);
  loadGeoData();
  loadAuthBrandStats();
}

// The brand panel's stats are the exact same real, live numbers already
// shown in the homepage hero — fetched fresh each time this screen opens
// rather than duplicated/hardcoded, so they're never stale or fabricated.
async function loadAuthBrandStats() {
  const els = {
    pros: document.getElementById('auth-brand-stat-pros'),
    jobs: document.getElementById('auth-brand-stat-jobs'),
    rating: document.getElementById('auth-brand-stat-rating'),
  };
  if (!els.pros) return;
  if (!BACKEND_AVAILABLE) { els.pros.textContent = '—'; els.jobs.textContent = '—'; els.rating.textContent = '—'; return; }
  try {
    const stats = await apiFetch('GET', '/platform-stats');
    els.pros.textContent = stats.verifiedProsCount.toLocaleString();
    els.jobs.textContent = stats.jobsCompletedCount.toLocaleString();
    els.rating.textContent = stats.averageRating ? `${Number(stats.averageRating).toFixed(1)}★` : 'New';
  } catch (e) { console.warn('Could not load auth screen stats', e); }
}

// Standard show/hide toggle — typing a password blind is the single
// biggest cause of failed signup attempts (a typo nobody can see until
// the next screen rejects it).
function togglePasswordVisibility() {
  const input = document.getElementById('auth-password');
  const icon = document.getElementById('password-toggle-icon');
  const showing = input.type === 'text';
  input.type = showing ? 'password' : 'text';
  icon.textContent = showing ? '👁️' : '🙈';
}

// Reflects the EXACT rule the server actually enforces (8-72 characters,
// no forced digit/letter/symbol composition — NIST 800-63B-aligned) —
// scored by length, not a generic "weak/medium/strong" guess disconnected
// from what will actually be accepted at submit time. Only shown during
// signup; login doesn't need or want this.
function updatePasswordStrength(value) {
  const meter = document.getElementById('password-strength-meter');
  if (!meter) return;
  if (authState.mode !== 'signup' || !value) { meter.style.display = 'none'; return; }
  meter.style.display = 'block';

  const len = value.length;
  // 4 segments, scaled by length past the 8-char floor: <8 not valid yet,
  // 8-11 weak, 12-15 fair, 16-19 good, 20+ strong.
  let metCount;
  if (len < 8) metCount = 0;
  else if (len < 12) metCount = 1;
  else if (len < 16) metCount = 2;
  else if (len < 20) metCount = 3;
  else metCount = 4;

  const colors = ['#C0392B', '#C0392B', '#B08A3E', '#2E8C6F']; // 1-2 met: red, 3 met: gold, 4 met: green
  const color = metCount === 0 ? 'var(--border)' : colors[metCount - 1];
  for (let i = 0; i < 4; i++) {
    document.getElementById(`strength-seg-${i}`).style.background = i < metCount ? color : 'var(--border)';
  }
  const label = document.getElementById('password-strength-label');
  label.textContent = len < 8
    ? '8-72 characters — longer is stronger'
    : (metCount === 4 ? '✓ Strong — great length' : `${len} characters — a longer passphrase is stronger than a short, complex one`);
  label.style.color = metCount === 4 ? '#2E8C6F' : 'var(--slate)';
}

// A real loading state on submit — disables the button and shows a
// spinner for the duration of the actual network call, rather than
// leaving it clickable while a request is in flight (which is exactly
// how a double-submission happens on a slow connection). This wraps
// mockAuth() without changing a single line of its own logic — every
// existing validation, error, and success path inside it runs exactly as
// before; this just brackets the whole call with a visible busy state.
async function handleAuthSubmit() {
  const btn = document.getElementById('auth-submit-btn');
  const originalText = btn.textContent;
  btn.disabled = true;
  btn.innerHTML = `<span class="btn-spinner"></span>${authState.mode === 'login' ? 'Signing in…' : 'Creating account…'}`;
  try {
    await mockAuth();
  } finally {
    btn.disabled = false;
    btn.textContent = originalText;
  }
}

let inviteCheckTimeout = null;
function checkInviteCode(code) {
  clearTimeout(inviteCheckTimeout);
  const statusEl = document.getElementById('auth-invite-status');
  const trimmed = (code || '').trim();
  if (!trimmed) { statusEl.textContent = ''; return; }
  statusEl.style.color = 'var(--slate)';
  statusEl.textContent = 'Checking…';
  inviteCheckTimeout = setTimeout(async () => {
    if (!BACKEND_AVAILABLE) { statusEl.textContent = ''; return; }
    try {
      const result = await apiFetch('GET', `/org-invites/${encodeURIComponent(trimmed.toUpperCase())}`);
      statusEl.style.color = 'var(--success, #1E7A4C)';
      statusEl.textContent = `✓ You'll join ${result.organizationName}`;
    } catch (e) {
      statusEl.style.color = 'var(--danger, #B23A3A)';
      statusEl.textContent = e.message || 'Invalid invite code';
    }
  }, 500);
}

/* ══════════════════════ FORGOT / RESET PASSWORD ══════════════════════ */
let lastTestResetToken = null;

function showForgotPassword() {
  showScreen('screen-forgot');
  renderNavbar('navbar-forgot', 'auth');
  document.getElementById('forgot-request-view').style.display = 'block';
  document.getElementById('forgot-reset-view').style.display = 'none';
  document.getElementById('forgot-test-mode-panel').style.display = 'none';
  document.getElementById('forgot-email').value = '';
  lastTestResetToken = null;
}

async function submitForgotPassword() {
  const email = document.getElementById('forgot-email').value.trim();
  if (!isValidEmailClient(email)) return showToast('Enter a valid email address');

  if (!BACKEND_AVAILABLE) {
    showToast('Reset link sent (demo mode — no backend detected)');
    return;
  }
  try {
    const data = await apiFetch('POST', '/auth/forgot-password', { email });
    showToast(data.message);
    // v81: on the live site a reset token is never sent back to this page.
    if (data.emailUnavailable) { document.getElementById('forgot-test-mode-panel').style.display = 'none'; return; }
    if (data.testMode && data.resetToken) {
      lastTestResetToken = data.resetToken;
      document.getElementById('forgot-test-mode-panel').style.display = 'block';
    } else {
      document.getElementById('forgot-test-mode-panel').style.display = 'none';
    }
  } catch (e) {
    showToast(e.message || 'Could not send reset link');
  }
}

function useTestResetToken() {
  if (!lastTestResetToken) return;
  showResetPasswordForm(lastTestResetToken);
}

function showResetPasswordForm(token) {
  pendingResetToken = token;
  showScreen('screen-forgot');
  renderNavbar('navbar-forgot', 'auth');
  document.getElementById('forgot-request-view').style.display = 'none';
  document.getElementById('forgot-reset-view').style.display = 'block';
  document.getElementById('reset-new-password').value = '';
  document.getElementById('reset-confirm-password').value = '';
}

let pendingResetToken = null;

async function submitResetPassword() {
  const newPassword = document.getElementById('reset-new-password').value;
  const confirm = document.getElementById('reset-confirm-password').value;
  if (!pendingResetToken) return showToast('Missing reset token — request a new link');
  if (newPassword.length < 8 || newPassword.length > 72) return showToast('New password must be 8-72 characters');
  if (newPassword !== confirm) return showToast("Passwords don't match");

  if (!BACKEND_AVAILABLE) {
    showToast('Password reset (demo mode — no backend detected)');
    showAuth('login');
    return;
  }
  try {
    const data = await apiFetch('POST', '/auth/reset-password', { token: pendingResetToken, newPassword });
    showToast(data.message);
    pendingResetToken = null;
    showAuth('login');
  } catch (e) {
    showToast(e.message || 'Could not reset password');
  }
}

function setAuthMode(mode) {
  authState.mode = mode;
  document.getElementById('tab-login').classList.toggle('active', mode === 'login');
  document.getElementById('tab-signup').classList.toggle('active', mode === 'signup');
  document.getElementById('auth-role-picker').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-name-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-phone-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-country-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-state-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-city-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-address-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-zip-group').style.display = mode === 'signup' ? 'block' : 'none';
  document.getElementById('auth-provider-fields-group').style.display = (mode === 'signup' && authState.role === 'provider') ? 'block' : 'none';
  document.getElementById('auth-forgot-link').style.display = mode === 'signup' ? 'none' : 'block';
  document.getElementById('auth-submit-btn').textContent = mode === 'login' ? 'Sign In' : 'Create Account';
  document.getElementById('auth-sub').textContent = mode === 'login' ? 'Verified pros. Protected payments. Zero guesswork.' : 'Join as a customer, provider, or admin to get started.';
  document.getElementById('auth-foot').innerHTML = mode === 'login'
    ? `New to Trothen? <a onclick="exitGoogleFlow();setAuthMode('signup')">Create an account</a>`
    : `Already have an account? <a onclick="exitGoogleFlow();setAuthMode('login')">Sign in</a>`;
  document.getElementById('auth-password').setAttribute('autocomplete', mode === 'login' ? 'current-password' : 'new-password');
  updatePasswordStrength(document.getElementById('auth-password').value);
  initGoogleSignIn();
}

function setAuthRole(role) {
  authState.role = role;
  document.querySelectorAll('.auth-role-opt').forEach(el => el.classList.toggle('active', el.dataset.role === role));
  document.getElementById('auth-provider-fields-group').style.display = (authState.mode === 'signup' && role === 'provider') ? 'block' : 'none';
  if (role === 'provider') {
    // Pull from the live category list (same source as the homepage and job
    // posting) so a category an admin just added is immediately selectable
    // here too, instead of a hardcoded list going stale.
    const select = document.getElementById('auth-category');
    if (select && CATEGORIES.length) {
      select.innerHTML = CATEGORIES.map(c => `<option>${escapeHtml(c.name)}</option>`).join('') + `<option value="__other__">Other (not listed — describe below)</option>`;
    }
  }
}

async function mockAuth() {
  if (authState.isGoogleFlow) return submitGoogleSignup();
  const email = document.getElementById('auth-email').value.trim();
  const password = document.getElementById('auth-password').value;
  const name = document.getElementById('auth-name').value.trim();
  const city = document.getElementById('auth-city').value.trim();
  const country = document.getElementById('auth-country').value;
  const state = document.getElementById('auth-state').value;
  const phoneDialCode = document.getElementById('auth-phone-dialcode') ? document.getElementById('auth-phone-dialcode').textContent : '';
  const phoneLocal = document.getElementById('auth-phone').value.trim();
  const phone = phoneLocal ? `${phoneDialCode}${phoneLocal.replace(/^0+/, '')}` : '';
  const address = document.getElementById('auth-address').value.trim();
  const zipCode = document.getElementById('auth-zip').value.trim();
  const categorySelect = document.getElementById('auth-category').value;
  const customCategoryRaw = document.getElementById('auth-custom-category').value.trim();
  const category = categorySelect === '__other__'
    ? customCategoryRaw.replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    : categorySelect;
  const skills = document.getElementById('auth-skills').value.trim();

  if (!BACKEND_AVAILABLE) {
    showToast(authState.mode === 'login' ? 'Signed in (demo mode — no backend detected)' : 'Account created (demo mode — no backend detected)');
    return goDashboard(authState.role);
  }
  if (authState.mode === 'login') {
    if (!email || !password) return showToast('Please fill in all fields');
  } else {
    const zipRequired = !(GEO_DATA.noPostalCodeCountries || []).includes(country);
    if (!email || !password || !name || !phone || !address || !city || !state || (zipRequired && !zipCode)) return showToast('Please fill in all fields');
    if (authState.role === 'provider' && !skills) return showToast('List at least one skill or specialty');
    if (authState.role === 'provider' && categorySelect === '__other__' && category.length < 2) return showToast('Tell us what service you offer');
  }
  if (!isValidEmailClient(email)) {
    return showToast('Enter a valid email address');
  }
  if (authState.mode === 'signup') {
    if (name.length < 2) return showToast('Full name must be at least 2 characters');
    if (password.length < 8 || password.length > 72) return showToast('Password must be 8-72 characters');
    const phoneDigits = phone.replace(/[^0-9]/g, '');
    if (phoneDigits.length < 7) return showToast('Enter a valid phone number');
    if (zipCode && zipCode.length < 3 && !(GEO_DATA.noPostalCodeCountries || []).includes(country)) return showToast('Enter a valid zip/postal code');
    if (city.length < 2) return showToast('Enter your city');
  }
  try {
    if (authState.mode === 'login') {
      const result = await loginAs(email, password);
      if (result && result.requires2FA) {
        pendingLoginId = result.pendingLoginId;
        document.getElementById('auth-main-form').style.display = 'none';
        document.getElementById('login-2fa-view').style.display = 'block';
        describeLoginCodeDestination(result);
        if (result.testMode) {
          document.getElementById('login-2fa-test-banner').style.display = 'block';
          document.getElementById('login-2fa-code-display').textContent = result.code;
        }
        return;
      }
      const user = result;
      showToast(`Welcome back, ${user.name.split(' ')[0]}!`);
      rememberLastLoginEmail(email, user.role);
      await completeAuthAndResumeIntent(user.role);
    } else {
      const data = await apiFetch('POST', '/auth/signup/start', {
        name, email, password, role: authState.role, city, country, state, phone, address, zipCode,
        ...(pendingReferralCode ? { referralCode: pendingReferralCode } : {}),
        ...(authState.role === 'provider' ? { category, skills, inviteCode: document.getElementById('auth-invite-code').value.trim() } : {}),
      });
      pendingSignupId = data.pendingId;
      document.getElementById('auth-main-form').style.display = 'none';
      document.getElementById('signup-verify-view').style.display = 'block';
      if (data.testMode) {
        document.getElementById('signup-verify-test-banner').style.display = 'block';
        document.getElementById('signup-verify-email-code-display').textContent = data.emailCode !== undefined ? data.emailCode : 'Sent to your email';
      }
      showToast('Enter the code sent to your email to finish creating your account');
    }
  } catch (e) {
    showToast(e.message || 'Something went wrong');
  }
}

let pendingSignupId = null;
// Item: Walter's explicit request — the system should actively prompt
// for identity verification right at the moment someone actually
// becomes a customer or provider, not just wait for the 24-hour
// reminder (src/document-upload-reminder-scheduler.js) to eventually
// catch them. Set true only at the exact moment a brand-new signup
// completes (never on a regular login, which would make this an
// annoying repeat nag instead of a real one-time part of onboarding),
// consumed once right after the terms gate closes.
let JUST_COMPLETED_SIGNUP = false;
let pendingLoginId = null;
let pendingReferralCode = null;

async function submitSignupVerification() {
  const emailCode = document.getElementById('signup-verify-email-code').value.trim();
  if (!emailCode) return showToast('Enter the code sent to your email');
  if (!pendingSignupId) return showToast('Something went wrong — please start signing up again');
  try {
    const data = await apiFetch('POST', '/auth/signup/verify', { pendingId: pendingSignupId, emailCode });
    AUTH.token = data.token; AUTH.user = data.user;
    saveAuthSession(data.token);
    pendingSignupId = null;
    pendingReferralCode = null;
    JUST_COMPLETED_SIGNUP = true; // consumed once, right after the terms gate closes below — see submitTermsAgreement()
    document.getElementById('signup-verify-view').style.display = 'none';
    document.getElementById('auth-main-form').style.display = 'block';
    if (pendingPlanSelection && data.user.role === 'provider') {
      // Every provider starts on Starter by default already — this used
      // to PATCH the account to whatever plan was clicked before signing
      // up, which was itself the actual bug (letting anyone skip
      // straight to Pro or Super-Pro). Only the Starter button sets this
      // now, and Starter is already the default, so there's genuinely
      // nothing left to do here except clear it.
      showToast('Account created — welcome to Trothen!');
      pendingPlanSelection = null;
    } else if (data.categoryApprovalStatus === 'pending') {
      showToast(`Account created! Your category "${data.user.category}" is pending a quick admin review (within 24 hours) — you can use your account right away in the meantime.`);
    } else if (data.joinedOrganizationName) {
      showToast(`Account created — you've joined ${data.joinedOrganizationName}!`);
    } else {
      showToast('Account created — welcome to Trothen!');
    }
    rememberLastLoginEmail(data.user.email, data.user.role);
    await completeAuthAndResumeIntent(data.user.role);
  } catch (e) {
    showToast(e.message || 'Could not verify — check the code and try again');
  }
}

async function resendSignupCodes() {
  if (!pendingSignupId) return showToast('Nothing to resend — please start signing up again');
  try {
    const data = await apiFetch('POST', '/auth/signup/resend', { pendingId: pendingSignupId });
    if (data.testMode) {
      document.getElementById('signup-verify-test-banner').style.display = 'block';
      document.getElementById('signup-verify-email-code-display').textContent = data.emailCode !== undefined ? data.emailCode : 'Sent to your email';
    }
    showToast('New code sent');
  } catch (e) { showToast(e.message || 'Could not resend code'); }
}

function cancelSignupVerification() {
  pendingSignupId = null;
  document.getElementById('signup-verify-view').style.display = 'none';
  document.getElementById('auth-main-form').style.display = 'block';
  document.getElementById('signup-verify-email-code').value = '';
}

// v89: tells the person which inbox or phone their sign-in code went to.
function describeLoginCodeDestination(result) {
  const el = document.getElementById('login-2fa-sub');
  if (!el || !result) return;
  if (result.testMode) el.textContent = 'Your password was correct. To finish signing in, type the 6-digit code shown below.';
  else if (result.sentTo) el.textContent = `Your password was correct. We sent a 6-digit code by ${result.sentVia === 'text' ? 'text message' : 'email'} to ${result.sentTo}. ${result.sentVia === 'text' ? '' : 'If you don\'t see it in a minute, check your spam or junk folder. '}Type it here to finish signing in.`;
}

async function submitLogin2FA() {
  const code = document.getElementById('login-2fa-code').value.trim();
  if (code.length !== 6) return showToast('Enter the 6-digit code');
  try {
    const data = await apiFetch('POST', '/auth/login/verify-2fa', { pendingLoginId, code });
    AUTH.token = data.token;
    AUTH.user = data.user;
    saveAuthSession(data.token);
    pendingLoginId = null;
    showToast(`Welcome back, ${data.user.name.split(' ')[0]}!`);
    rememberLastLoginEmail(data.user.email, data.user.role);
    await completeAuthAndResumeIntent(data.user.role);
  } catch (e) { showToast(e.message || 'Incorrect code'); }
}

function cancelLogin2FA() {
  pendingLoginId = null;
  document.getElementById('login-2fa-view').style.display = 'none';
  document.getElementById('auth-main-form').style.display = 'block';
  document.getElementById('login-2fa-code').value = '';
}

// Shows the dashboard matching the CURRENT signed-in account — it never
// creates a session on its own. The only ways to actually get signed in are
// the real Sign In / Sign Up forms; this function just refuses to navigate
// to a dashboard that doesn't match who's actually authenticated, sending
// the visitor to sign in instead. That's what keeps every dashboard a real,
// private, per-account view rather than a shared demo the whole world can
// wander into.
async function goDashboard(role) {
  // Both regular admins and the super admin are stored with role: 'admin' in
  // the database — isSuperAdmin is a separate flag, not a different role
  // value. So "admin" here must match either one; the admin dashboard
  // itself already branches on isSuperAdmin internally for the extra
  // super-admin-only features (see getAdminNavItems()).
  const alreadyCorrect = AUTH.user && (
    (role === 'admin' && AUTH.user.role === 'admin') ||
    (role === AUTH.user.role && role !== 'admin')
  );
  if (BACKEND_AVAILABLE && !alreadyCorrect) {
    showAuth('login');
    showToast(role === 'customer' ? 'Sign in as a customer to continue' : role === 'provider' ? 'Sign in as a provider to continue' : 'Sign in with an admin account to continue');
    return;
  }
  if (role === 'customer') {
    // A customer's post-login landing page is the homepage itself, not a
    // separate dashboard — matching how Airbnb or Amazon keep you on the
    // main browsing experience once you're signed in, rather than
    // routing you away from it. My Bookings, Messages, Payments,
    // Verification, and Settings all stay real, dedicated pages — just
    // reachable from the account menu, not forced on login.
    await refreshNotifications();
    startMessagePolling();
    checkTermsGate('customer');
    goHome();
  }
  else if (role === 'provider') { showScreen('screen-provider'); await refreshNotifications(); renderNavbar('navbar-provider', 'provider'); await initProviderDash(); startMessagePolling(); checkTermsGate('provider'); }
  else { showScreen('screen-admin'); updateAdminSidebar(); await refreshNotifications(); renderNavbar('navbar-admin', role); await initAdminDash(); startMessagePolling(); }
}

// Current version of the customer/provider agreement — must match
// CURRENT_TERMS_VERSION in src/routes/auth.routes.js exactly, or the
// backend will reject the acceptance. Bumping this (after the actual
// terms change) makes every existing user see the gate again on their
// next visit, rather than silently staying agreed to terms they never
// saw.
const CURRENT_TERMS_VERSION = 'v2-2026'; // v76: new tick-box agreement, and customers now need a reviewed ID

// A real, deliberate consent gate — not a pre-checked box, not something
// implied by using the app. Shown once per version, to every customer and
// provider whose stored agreement doesn't match the current version
// (which covers both brand-new signups and every existing account from
// before this existed — nobody is grandfathered into terms they never
// actually saw). Blocking: no way to close it or click through to the
// dashboard underneath without actually agreeing.
// Tracks whether the full Terms of Service has actually been opened
// during this specific agreement flow — reset every time the gate opens.
// The Agree button checks this directly; there is no way to reach it
// without this having been set to true first.
let TERMS_GATE_VIEWED = false;

function checkTermsGate(role) {
  if (!BACKEND_AVAILABLE || !AUTH.user) return;
  if (AUTH.user.termsVersion === CURRENT_TERMS_VERSION) { maybePromptVerification(); return; } // already agreed — v75: remind about ID if it's still missing
  if (document.getElementById('terms-gate-overlay')) return;
  TERMS_GATE_VIEWED = false;

  // v76: one tick box per promise, then one for the full terms. Nothing is
  // locked or hidden: the button itself says how many boxes are left.
  // The wording matches what the system really does (ID check, written
  // agreement, payment held until the job is marked complete).
  const isProvider = role === 'provider';
  const banner = document.getElementById('test-mode-banner');
  const testMode = !!(banner && banner.style.display !== 'none' && /simulated|real card|test mode/i.test(banner.textContent || ''));
  const title = isProvider ? 'Before you start taking jobs' : 'Before you book';
  const intro = isProvider
    ? 'Here is what we ask of every pro on Trothen, and what you can expect from us. Check each box to agree.'
    : 'Here is what we ask of every customer on Trothen, and what you can expect from us. Check each box to agree.';
  const promises = isProvider ? [
    ['I am who I say I am', 'I\'m 18 or older and the name on my account is my own. A person on the Trothen team reviews my government ID before I appear in search. I won\'t let anyone else work under my account.'],
    ['I\'ll be honest about my work', 'I\'ll describe my skills and any license truthfully. If a job turns out bigger than described, or needs a licensed trade I don\'t hold, I\'ll stop and tell the customer. Cancelling for that reason never counts against me.'],
    ['I\'ll keep my word', 'Each booking comes with a short written agreement: what\'s being done, when, and for how much. I\'ll show up for the time I accepted, or say so early if I can\'t.'],
    ['I\'ll treat everyone with respect and work safely', 'No harassment and no discrimination, whatever someone\'s race, religion, gender, age, disability or background. I won\'t go into any space I wasn\'t invited into, and I\'ll stop and report a job that becomes unsafe.'],
    ['I\'ll keep bookings and payment on Trothen', 'The customer pays me through Trothen. The payment is held in escrow and released to me when they mark the job complete, less the commission shown on my dashboard. If there\'s a disagreement, a person on the Trothen team reviews it. Work arranged off Trothen has none of this.' + (testMode ? ' Trothen is in early access: payments are in test mode right now and no real money moves yet.' : '')],
    ['I work for myself', 'I\'m an independent contractor, not an employee of Trothen. I choose which jobs to take and how to do them, and my taxes, insurance and business costs are my own.'],
  ] : [
    ['I am who I say I am', 'I\'m 18 or older and the name on my account is my own. A person on the Trothen team reviews my government ID before my first booking.'],
    ['I\'ll be honest about the job', 'I\'ll describe the work accurately, including anything difficult or risky about it (pets, wiring, chemicals, damage), and I\'ll leave reviews based on what really happened.'],
    ['I\'ll keep my word', 'Each booking comes with a short written agreement: what\'s being done, when, and for how much. I\'ll be there at the time I booked, or say so early if plans change.'],
    ['I\'ll treat everyone with respect', 'No harassment and no discrimination, whatever someone\'s race, religion, gender, age, disability or background. Pros run their own businesses; they aren\'t my staff, and I won\'t ask for work outside what we agreed.'],
    ['I\'ll keep bookings and payment on Trothen', 'I pay my pro through Trothen. The payment is held in escrow until I mark the job complete. If something goes wrong, I won\'t mark it complete; I\'ll raise it and a person on the Trothen team will review it. Work arranged off Trothen has none of this.' + (testMode ? ' Trothen is in early access: payments are in test mode right now and no real money moves yet.' : '')],
  ];
  const finePrint = isProvider
    ? 'Trothen is a marketplace. It connects customers with independent pros; it doesn\'t employ you and isn\'t a party to the work itself.'
    : 'Trothen is a marketplace. It connects you with independent pros; it doesn\'t do the work itself and doesn\'t employ the people who do.';
  const row = (i, label, detail) => `
            <label class="tg-row" for="tg-box-${i}">
              <input type="checkbox" class="tg-box" id="tg-box-${i}" onchange="updateTermsAgreeButton()"/>
              <span><strong>${escapeHtml(tr(label))}</strong><span class="tg-detail">${escapeHtml(trDetail(detail))}</span></span>
            </label>`;

  const modalHtml = `
    <div class="modal-overlay open" id="terms-gate-overlay" style="z-index:5000;">
      <style>
        #terms-gate-overlay .tg-row { display:flex; gap:12px; align-items:flex-start; padding:12px; margin-bottom:8px; border:1.5px solid var(--border); border-radius:10px; cursor:pointer; background:var(--white, #fff); transition:border-color .15s ease, background .15s ease; }
        #terms-gate-overlay .tg-row:hover { border-color:var(--navy); }
        #terms-gate-overlay .tg-row.is-ticked { border-color:#2E8C6F; background:rgba(46,140,111,.08); }
        #terms-gate-overlay .tg-box { width:20px; height:20px; margin:1px 0 0; flex-shrink:0; accent-color:#256B54; cursor:pointer; }
        #terms-gate-overlay .tg-row strong { display:block; font-size:14.5px; color:var(--navy); }
        #terms-gate-overlay .tg-detail { display:block; font-size:13.5px; line-height:1.5; color:var(--text); margin-top:3px; }
        #terms-gate-overlay .tg-link { background:none; border:none; padding:0; color:var(--teal); font-weight:600; font-size:13.5px; text-decoration:underline; cursor:pointer; }
        #terms-gate-overlay .tg-fine { font-size:13px; color:var(--slate); line-height:1.55; margin:14px 2px 0; }
        #terms-gate-overlay .tg-left { font-size:13px; color:var(--slate); margin-right:auto; align-self:center; }
        #terms-gate-overlay .modal { display:flex; flex-direction:column; max-height:calc(100vh - 32px); max-height:calc(100dvh - 32px); overflow:hidden; }
        #terms-gate-overlay .modal-header { flex-shrink:0; }
        #terms-gate-overlay .modal-body { overflow-y:auto; flex:1 1 auto; min-height:0; }
        #terms-gate-overlay .modal-footer { flex-shrink:0; position:static; padding-top:14px; border-top:1px solid var(--border); align-items:center; }
        html.dark #terms-gate-overlay .modal-footer { background:transparent; }
        html.dark #terms-gate-overlay .tg-row { background:transparent; }
        html.dark #terms-gate-overlay .tg-row strong { color:#fff; }
      </style>
      <div class="modal" style="max-width:560px;" onclick="event.stopPropagation()" role="dialog" aria-modal="true" aria-labelledby="terms-gate-title">
        <div class="modal-header">
          <h3 id="terms-gate-title">${escapeHtml(tr(title))}</h3>
          <p>${escapeHtml(tr(intro))}</p>
        </div>
        <div class="modal-body" id="terms-gate-summary-view">
          ${promises.map(([label, detail], i) => row(i, label, detail)).join('')}
          <label class="tg-row" for="terms-gate-checkbox">
            <input type="checkbox" class="tg-box" id="terms-gate-checkbox" onchange="updateTermsAgreeButton()"/>
            <span><strong>${escapeHtml(tr('I agree to the Trothen Terms of Service'))}</strong><span class="tg-detail">${escapeHtml(tr("The full terms cover fees, cancellations, what can't be booked on Trothen, and how accounts can be suspended."))} <button type="button" class="tg-link" onclick="event.preventDefault();openFullTermsInGate('${role}')">${escapeHtml(tr('Read the full terms'))}</button> ${escapeHtml(tr('Our'))} <button type="button" class="tg-link" onclick="event.preventDefault();showPrivacyPolicy()">${escapeHtml(tr('Privacy Policy'))}</button> ${escapeHtml(tr('explains how we use your information, including your ID and your location.'))}</span></span>
          </label>
          <div class="tg-fine">${escapeHtml(tr(finePrint))}</div>
        </div>
        <div class="modal-body" id="terms-gate-full-view" style="display:none;">
          <button onclick="closeFullTermsInGate()" style="background:none;border:none;color:var(--teal);font-weight:600;font-size:14px;cursor:pointer;padding:0;margin-bottom:14px;">← ${escapeHtml(tr('Back to the checkboxes'))}</button>
          <div id="terms-gate-full-content" style="font-size:14px;color:var(--text);">Loading…</div>
        </div>
        <div class="modal-footer" style="display:flex;gap:12px;flex-wrap:wrap;">
          <span class="tg-left" id="terms-gate-left" aria-live="polite"></span>
          <button class="confirm-btn" id="terms-gate-agree-btn" disabled onclick="submitTermsAgreement()">${escapeHtml(tr('Agree and continue'))}</button>
        </div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  updateTermsAgreeButton();
}

async function openFullTermsInGate(role) {
  TERMS_GATE_VIEWED = true;
  document.getElementById('terms-gate-summary-view').style.display = 'none';
  document.getElementById('terms-gate-full-view').style.display = 'block';
  const footer = document.querySelector('#terms-gate-overlay .modal-footer');
  if (footer) footer.style.display = 'none';
  const contentEl = document.getElementById('terms-gate-full-content');
  try {
    const { content } = await apiFetch('GET', `/terms-of-service-${role}-content`);
    contentEl.innerHTML = renderFormattedContent(content);
  } catch (e) { contentEl.innerHTML = '<p>The Terms of Service couldn\'t load. Please go back and try again.</p>'; }
}

function closeFullTermsInGate() {
  document.getElementById('terms-gate-full-view').style.display = 'none';
  document.getElementById('terms-gate-summary-view').style.display = 'block';
  const footer = document.querySelector('#terms-gate-overlay .modal-footer');
  if (footer) footer.style.display = 'flex';
  updateTermsAgreeButton();
}

// v76: the button is live only when every box is ticked, and until then
// the line beside it says how many are left. The server checks again.
function termsGateAllTicked() {
  const boxes = [...document.querySelectorAll('#terms-gate-overlay .tg-box')];
  return boxes.length > 0 && boxes.every(b => b.checked);
}
function updateTermsAgreeButton() {
  const boxes = [...document.querySelectorAll('#terms-gate-overlay .tg-box')];
  const btn = document.getElementById('terms-gate-agree-btn');
  const leftEl = document.getElementById('terms-gate-left');
  if (!btn) return;
  boxes.forEach(b => { const r = b.closest('.tg-row'); if (r) r.classList.toggle('is-ticked', b.checked); });
  const left = boxes.filter(b => !b.checked).length;
  btn.disabled = left > 0;
  if (leftEl) leftEl.textContent = left === 0 ? tr('All checked. You can continue.') : left === boxes.length ? tr('Check all {n} boxes to continue').replace('{n}', boxes.length) : tr(left === 1 ? '{n} box left to check' : '{n} boxes left to check').replace('{n}', left);
}

async function submitTermsAgreement() {
  const btn = document.getElementById('terms-gate-agree-btn');
  btn.disabled = true;
  btn.innerHTML = '<span class="btn-spinner" style="border-top-color:#fff;"></span>Saving…';
  try {
    if (!termsGateAllTicked()) { updateTermsAgreeButton(); btn.textContent = 'Agree and continue'; return showToast('Please check every box first'); }
    await apiFetch('POST', '/auth/accept-terms', { version: CURRENT_TERMS_VERSION, acknowledgedAll: true, viewedFullTerms: TERMS_GATE_VIEWED });
    AUTH.user.termsVersion = CURRENT_TERMS_VERSION;
    const overlay = document.getElementById('terms-gate-overlay');
    if (overlay) overlay.remove();
    showToast('Thanks, you\'re all set.');
    JUST_COMPLETED_SIGNUP = false;
    maybePromptVerification(); // v75: asks on every sign-in until an ID is submitted, not only once at signup
  } catch (e) {
    showToast(e.message || 'Your agreement couldn\'t be saved. Please try again.');
    btn.disabled = false;
    btn.textContent = 'Agree and continue';
  }
}

// Item: the real, active version of "the system asks you to verify" —
// shown exactly once, right at the true moment of finishing signup, not
// a passive screen someone has to go discover on their own. Dismissible
// on purpose, not a hard gate like the terms agreement — someone who
// isn't ready right this second still has a real account and can still
// browse; the 24-hour reminder scheduler is the real safety net for
// anyone who dismisses this and doesn't come back to it themselves.
// v75: the prompt used to appear exactly once, at signup. Anyone who
// closed it (or signed up with Google, or was approved by an admin without
// an ID) was never asked again. Now it appears once per browser session at
// sign-in for any customer or provider who isn't verified and has no ID
// waiting for review.
async function maybePromptVerification() {
  const u = AUTH.user;
  if (!BACKEND_AVAILABLE || !u || u.verified || (u.role !== 'customer' && u.role !== 'provider')) return;
  try { if (sessionStorage.getItem('trothen_verify_prompted') === u.id) return; } catch (e) { /* private mode: just ask */ }
  try {
    const { verifications } = await apiFetch('GET', '/verification/mine');
    if (verifications.some(v => v.status === 'pending' || v.status === 'review_required')) return; // already submitted, waiting on us
  } catch (e) { return; }
  if (!AUTH.user || AUTH.user.id !== u.id || document.getElementById('verification-onboarding-prompt') || document.getElementById('terms-gate-overlay')) return;
  try { sessionStorage.setItem('trothen_verify_prompted', u.id); } catch (e) { /* fine */ }
  showVerificationOnboardingPrompt();
}

function showVerificationOnboardingPrompt() {
  const role = AUTH.user.role;
  const isProvider = role === 'provider';
  const title = isProvider ? 'One last step to become a Pro' : 'Verify your identity';
  const body = isProvider
    ? `You're almost there — customers only ever book verified pros. Upload a government ID now and you'll typically be approved within a day, sometimes sooner.`
    : `You'll need this before you can post a job or book a pro. It takes a couple of minutes: upload a government ID and a person on our team reviews it. Your document stays private.`;
  const modalHtml = `
    <div class="modal-overlay open" id="verification-onboarding-prompt" style="z-index:4500;">
      <div class="modal" style="max-width:440px;" onclick="event.stopPropagation()">
        <div class="modal-body" style="padding-top:28px;text-align:center;">
          <div style="font-size:32px;margin-bottom:10px;">🪪</div>
          <div style="font-size:16px;color:var(--navy);font-weight:700;margin-bottom:8px;">${title}</div>
          <div style="font-size:13.5px;color:var(--slate);line-height:1.6;">${body}</div>
        </div>
        <div class="modal-footer" style="display:flex;flex-direction:column;gap:8px;padding:0 24px 24px;">
          <button class="confirm-btn" style="width:100%;" onclick="startVerificationFromPrompt('${role}')">Verify Now</button>
          <button class="btn-sm btn-sm-outline" style="width:100%;" onclick="document.getElementById('verification-onboarding-prompt').remove()">Maybe Later</button>
        </div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function startVerificationFromPrompt(role) {
  document.getElementById('verification-onboarding-prompt').remove();
  if (role === 'provider') selectProviderSection('verification');
  else goToCustomerDashboard('verification'); // v75: customers sit on the homepage after sign-in, so open their dashboard first
}

/* ══════════════════════ SHARED DASHBOARD HELPERS ══════════════════════ */
// A section's render function (CUSTOMER_SECTIONS[key](), etc.) is a plain
// JS function building a big HTML string — if it throws partway through
// (a bad assumption about some piece of data), the assignment to
// .innerHTML never happens and whatever was already on screen just sits
// there unchanged, or the page can end up looking blank/broken depending
// on what ran right before. Either way, to someone who isn't looking at
// the browser console, that's indistinguishable from "the app just
// logged me out" — nothing about it is actually a real sign-out, but it
// looks exactly like one. This wraps every section render so a real
// error shows a real, readable message in that same spot instead, and
// logs the actual error and which section caused it to the console —
// turning "it logs me out and I don't know why" into something we can
// actually point at and fix. This never touches AUTH.token or AUTH.user.
function renderSectionSafely(containerId, sectionKey, renderFn) {
  const container = document.getElementById(containerId);
  if (!container) return;
  try {
    container.innerHTML = renderFn();
  } catch (err) {
    console.error(`[renderSectionSafely] "${sectionKey}" failed to render:`, err);
    container.innerHTML = `
      <div class="panel" style="text-align:center;padding:40px;">
        <div style="font-size:32px;margin-bottom:12px;">⚠️</div>
        <div style="font-weight:700;color:var(--navy);font-size:15px;margin-bottom:8px;">This section hit a problem loading</div>
        <div style="font-size:13.5px;color:var(--slate);margin-bottom:16px;">You're still signed in — this is a display problem, not a sign-out. Try another tab, or come back to this one in a moment.</div>
        <div style="font-size:12.5px;color:var(--muted);font-family:monospace;background:var(--offwhite);padding:8px 12px;border-radius:6px;display:inline-block;max-width:100%;overflow-wrap:break-word;">${escapeHtml(err && err.message || String(err))}</div>
      </div>`;
  }
}

function renderDashNav(containerId, items, activeKey, fnName) {
  document.getElementById(containerId).innerHTML = items.map(it =>
    `<div class="dash-nav-item ${it.key === activeKey ? 'active' : ''}" onclick="${fnName}('${it.key}')"><span>${it.icon}</span>${it.label}${it.dot ? '<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:#2E8C6F;margin-left:6px;"></span>' : ''}</div>`
  ).join('');
}

function statusBadge(status) {
  const map = {
    confirmed: ['badge-pending', 'Confirmed'], completed: ['badge-success', 'Completed'],
    disputed: ['badge-danger', 'Disputed'], pending: ['badge-warn', 'Pending'],
    approved: ['badge-success', 'Approved'], rejected: ['badge-danger', 'Rejected'],
    open: ['badge-pending', 'Open'], 'in review': ['badge-warn', 'In Review'],
    resolved: ['badge-success', 'Resolved'], active: ['badge-success', 'Active'],
    pending_agreement: ['badge-warn', 'Awaiting Response'], declined: ['badge-danger', 'Declined'],
    pending_provider_confirmation: ['badge-warn', 'Awaiting Confirmation'], expired: ['badge-neutral', 'Expired — No Response'],
    cancelled: ['badge-neutral', 'Cancelled'], suspended: ['badge-danger', 'Suspended'],
    verified: ['badge-success', 'Verified'], unverified: ['badge-warn', 'Unverified'],
    reviewed: ['badge-success', 'Reviewed'], dismissed: ['badge-neutral', 'Dismissed'],
    processing: ['badge-warn', 'Processing'], paid: ['badge-success', 'Paid'],
  };
  const m = map[status] || ['badge-neutral', status];
  return `<span class="badge ${m[0]}">${m[1]}</span>`;
}

function verificationHTML(role, status) {
  // status: 'verified' | 'in review' | 'none'
  const verified = status === 'verified';
  const inReview = status === 'in review';
  return `
  <div class="dash-header"><div><div class="dash-title">Identity Verification</div><div class="dash-sub">Required for every ${role === 'provider' ? 'provider' : 'customer'} on Trothen — this is what makes the marketplace trustworthy</div></div></div>
  <div class="panel">
    <div class="stepper">
      <div class="step-dot done">✓</div><div class="step-line ${inReview || verified ? 'done' : ''}"></div>
      <div class="step-dot ${inReview ? 'current' : (verified ? 'done' : '')}">${verified ? '✓' : '2'}</div><div class="step-line ${verified ? 'done' : ''}"></div>
      <div class="step-dot ${verified ? 'done' : ''}">${verified ? '✓' : '3'}</div>
    </div>
    <div style="display:flex;justify-content:space-between;font-size:13px;color:var(--slate);margin-top:-18px;margin-bottom:20px;max-width:520px;">
      <span>${escapeHtml(tr("Submit Documents"))}</span><span>${escapeHtml(tr("Under Review"))}</span><span>${escapeHtml(tr("Verified"))}</span>
    </div>
    ${verified
      ? (VERIFIED_WITHOUT_ID
          ? `<div class="badge badge-warn" style="font-size:14px;padding:8px 16px;white-space:normal;text-align:left;">${escapeHtml(tr("Account approved by our team. No ID has been reviewed for this account yet."))}</div>`
          : `<div class="badge badge-success" style="font-size:14px;padding:8px 16px;">✓ Identity Verified — government ID confirmed</div>`)
      : inReview
        ? `<div class="badge badge-warn" style="font-size:14px;padding:8px 16px;">⏳ Submitted — awaiting review</div>`
        : `<div id="verification-action-area">
            <div class="form-group"><label class="form-label">${escapeHtml(tr("Document Type"))}</label>
              <select class="form-input" id="verification-doc-type-select"><option>Loading…</option></select>
            </div>
            <div class="form-group"><label class="form-label">${escapeHtml(tr("Full Legal Name (exactly as printed on the document)"))}</label>
              <input class="form-input" id="verification-legal-name-input" placeholder="e.g. Marcus T. Johnson"/>
            </div>
            <div class="form-group"><label class="form-label">${escapeHtml(tr("1. The front of your government-issued ID"))}</label>
              <input class="form-input" type="file" id="verification-doc-file-input" accept="image/*,application/pdf" onchange="showVerificationPick(this, 'ver-pick-front')"/>
              <div id="ver-pick-front"></div>
              <div class="ver-note" style="margin-top:6px;">${escapeHtml(tr("The whole document, flat, with all four corners showing, nothing covered, and no glare. A photo or a PDF. On a phone you can take the photo right here."))}</div>
            </div>
            <div class="form-group"><label class="form-label">${escapeHtml(tr("2. The back of your ID"))} <span style="font-weight:400;color:var(--slate);">${escapeHtml(tr("(if it has one)"))}</span></label>
              <input class="form-input" type="file" id="verification-back-file-input" accept="image/*,application/pdf" onchange="showVerificationPick(this, 'ver-pick-back')"/>
              <div id="ver-pick-back"></div>
              <div class="ver-note" style="margin-top:6px;">${escapeHtml(tr("For a driver's license or ID card, add the back as well. Skip this for a passport."))}</div>
            </div>
            <div class="form-group"><label class="form-label">${escapeHtml(tr("3. A photo of your face"))}</label>
              <input class="form-input" type="file" id="verification-selfie-file-input" accept="image/*" capture="user" onchange="showVerificationPick(this, 'ver-pick-selfie')"/>
              <div id="ver-pick-selfie"></div>
              <div class="ver-note" style="margin-top:6px;">${escapeHtml(tr("Take it now, in good light, looking at the camera, with no hat or sunglasses. A person on our team compares it with the photo on your ID."))}</div>
            </div>
            <div class="ver-note" style="margin:0 0 14px;">${escapeHtml(tr("These are stored privately and are never shown to other users. Only the Trothen staff who review identity checks can open them. Check each preview is sharp enough to read before you send."))}</div>
            <button class="btn-sm btn-sm-primary" id="verification-submit-btn" onclick="submitVerification('${role}')">${escapeHtml(tr("Submit for Review"))}</button>
          </div>`}
  </div>
  ${role === 'provider' ? `<div class="panel"><div class="panel-title">Additional Trust Checks</div>
    <div class="data-table-wrap"><table class="data-table"><thead><tr><th>Check</th><th>Status</th></tr></thead><tbody>
    <tr><td>Background Check</td><td>${guarantorBackgroundCheckStatusHTML()}</td></tr>
    <tr><td>Two-Factor Authentication</td><td>${twoFactorTrustCheckHTML()}</td></tr>
    <tr><td>Automated Fraud Screening</td><td>${AUTH.user && AUTH.user.hasOpenFraudFlags ? statusBadge('processing') : statusBadge('completed')}</td></tr>
    </tbody></table></div>
  </div>
  <div class="panel">
    <div class="panel-title">Guarantors <span style="font-weight:400;color:var(--slate);font-size:13px;">(optional)</span></div>
    <div style="font-size:13.5px;color:var(--slate);margin-bottom:14px;">Some regions don't have real background-check infrastructure available yet. Adding up to 3 guarantors — real people who can vouch for you, like a property owner or long-time client — gives our verification team a real way to check on you in the meantime. Our team will call each guarantor directly. Always optional, never required to work on Trothen.</div>
    <div id="guarantors-form-area">${guarantorFormHTML()}</div>
  </div>` : ''}`;
}

// Item: the "Two-Factor Authentication" row in Additional Trust Checks
// used to hardcode "completed" for every single provider, regardless of
// whether they'd actually turned it on — since 2FA was, until now, only
// ever auto-enabled for admin accounts, this was flatly false for every
// provider on the platform. The real login-time 2FA check
// (src/routes/auth.routes.js) already works for ANY user with
// twoFactorEnabled set, not just admins, and that field was already
// safe to self-update (see the allowed-fields list on the profile PATCH
// route) — so turning this into a real, working toggle needed no new
// backend work, just a real UI for something the backend already
// supported.
function twoFactorTrustCheckHTML() {
  const enabled = AUTH.user && AUTH.user.twoFactorEnabled;
  if (enabled) return statusBadge('completed');
  return `<span class="badge badge-neutral" style="margin-right:8px;">Not Yet Enabled</span><button class="btn-sm btn-sm-outline" onclick="enableProviderTwoFactor()">Turn On</button>`;
}

async function enableProviderTwoFactor() {
  if (!BACKEND_AVAILABLE) return showToast('Requires a live backend connection');
  try {
    const { user } = await apiFetch('PATCH', '/auth/me', { twoFactorEnabled: true });
    AUTH.user = user;
    showToast('Two-factor authentication turned on — you\'ll be asked for a code the next time you sign in');
    selectProviderSection('verification');
  } catch (e) { showToast(e.message || 'Could not turn on two-factor authentication'); }
}

function guarantorBackgroundCheckStatusHTML() {
  const guarantors = (AUTH.user && AUTH.user.guarantors) || [];
  const verifiedCount = guarantors.filter(g => g.status === 'verified').length;
  if (verifiedCount > 0) return `<span class="badge badge-success">✓ Guarantor-Verified (${verifiedCount})</span>`;
  if (guarantors.length > 0) return `<span class="badge badge-warn">⏳ Guarantors Submitted — Awaiting Contact</span>`;
  return `<span class="badge badge-neutral">Not Yet Completed</span>`;
}

function guarantorFormHTML() {
  const guarantors = (AUTH.user && AUTH.user.guarantors) || [];
  const rows = [0, 1, 2].map(i => {
    const g = guarantors[i] || {};
    const statusNote = g.status === 'verified' ? ' <span class="badge badge-success" style="margin-left:6px;">Verified</span>'
      : g.status === 'contacted' ? ' <span class="badge badge-warn" style="margin-left:6px;">Contacted</span>'
      : g.status === 'rejected' ? ' <span class="badge badge-danger" style="margin-left:6px;">Not accepted: name a different person, with their own phone number</span>'
      : (g.name ? ' <span class="badge badge-neutral" style="margin-left:6px;">Submitted</span>' : '');
    return `
    <div style="border:1px solid var(--border);border-radius:10px;padding:14px;margin-bottom:10px;">
      <div style="font-weight:600;color:var(--navy);margin-bottom:8px;">Guarantor ${i + 1}${statusNote}</div>
      <div class="form-group"><label class="form-label">Full Name</label><input class="form-input" id="guarantor-${i}-name" value="${escapeHtml(g.name || '')}" placeholder="Full name"/></div>
      <div class="form-group"><label class="form-label">Phone Number</label><input class="form-input" id="guarantor-${i}-phone" value="${escapeHtml(g.phone || '')}" placeholder="A real number our team can call"/></div>
      <div class="form-group"><label class="form-label">Relationship</label><input class="form-input" id="guarantor-${i}-relationship" value="${escapeHtml(g.relationship || '')}" placeholder="e.g. Property owner, long-time client"/></div>
    </div>`;
  }).join('');
  return `${rows}<button class="btn-sm btn-sm-primary" onclick="saveGuarantors()">Save Guarantors</button>`;
}

async function saveGuarantors() {
  const guarantors = [];
  for (let i = 0; i < 3; i++) {
    const name = document.getElementById(`guarantor-${i}-name`).value.trim();
    const phone = document.getElementById(`guarantor-${i}-phone`).value.trim();
    const relationship = document.getElementById(`guarantor-${i}-relationship`).value.trim();
    if (name || phone || relationship) {
      if (!name || !phone) { showToast(`Guarantor ${i + 1}: enter at least a name and phone number, or leave all three fields blank`); return; }
      guarantors.push({ name, phone, relationship: relationship || null });
    }
  }
  if (!BACKEND_AVAILABLE) return showToast('Guarantors saved (demo mode)');
  try {
    const { user } = await apiFetch('POST', '/provider/guarantors', { guarantors });
    AUTH.user = user;
    showToast('Guarantors saved');
    selectProviderSection('verification');
  } catch (e) { showToast(e.message || 'Could not save guarantors'); }
}

// Item: this was the actual, live-confirmed root cause of every real
// verification submission failing. The old version sent a plain JSON
// body with no file attached at all, a hardcoded docType that matched
// NONE of the backend's real accepted values for any country, and no
// legal-name field even though the backend requires one — confirmed by
// actually submitting exactly what this function used to send and
// getting a real 400 back. Now sends a real FormData request matching
// exactly what POST /verification/submit (src/routes/misc.routes.js)
// actually expects.
// v80: show what was picked, so a blurry or cut-off photo is caught
// before it's sent instead of two days later by a reviewer.
function showVerificationPick(input, slotId) {
  const slot = document.getElementById(slotId);
  if (!slot) return;
  const file = input.files && input.files[0];
  if (!file) { slot.innerHTML = ''; return; }
  const mb = (file.size / (1024 * 1024)).toFixed(1);
  const isPdf = file.type === 'application/pdf';
  const url = isPdf ? '' : URL.createObjectURL(file);
  slot.innerHTML = `<div style="display:flex;gap:10px;align-items:center;margin-top:8px;padding:8px;border:1px solid var(--border);border-radius:8px;">
    ${isPdf ? '<div style="width:64px;height:48px;display:flex;align-items:center;justify-content:center;background:var(--offwhite);border-radius:6px;font-size:12px;font-weight:700;">PDF</div>'
            : `<img src="${url}" alt="Preview of the photo you picked" style="width:96px;height:72px;object-fit:cover;border-radius:6px;background:var(--offwhite);" onerror="this.outerHTML='<div style=&quot;width:96px;font-size:12px;color:#8A2D25;&quot;>No preview. This format may not be accepted.</div>'"/>`}
    <div style="font-size:13px;line-height:1.4;min-width:0;"><div style="font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(file.name || 'Photo')}</div><div style="color:var(--slate);">${mb} MB${(!isPdf && file.size > 1.2 * 1024 * 1024) ? ' · it will be shrunk before sending' : ''}</div></div>
  </div>`;
}

async function submitVerification(role) {
  if (!BACKEND_AVAILABLE) {
    showToast('Submitted for review (demo mode — no backend detected)');
    return;
  }
  const docType = document.getElementById('verification-doc-type-select').value;
  const idLegalName = document.getElementById('verification-legal-name-input').value.trim();
  const fileInput = document.getElementById('verification-doc-file-input');
  if (!idLegalName) return showToast('Enter your full legal name exactly as printed on the document');
  if (!fileInput.files || !fileInput.files[0]) return showToast('Add a photo of your ID');
  const selfieInput = document.getElementById('verification-selfie-file-input');
  if (!selfieInput || !selfieInput.files || !selfieInput.files[0]) return showToast('Add a photo of your face as well');

  const backInput = document.getElementById('verification-back-file-input');
  const btn = document.getElementById('verification-submit-btn');
  if (btn && btn.disabled) return; // already sending
  const setBusy = (text) => { if (btn) { btn.disabled = !!text; btn.textContent = text || 'Submit for Review'; } };

  try {
    // v80: shrink the photos first, then send. The button says what's happening.
    setBusy('Preparing your photos…');
    const idFile = await prepareImageForUpload(fileInput.files[0], { maxSide: 2600, quality: 0.9 });
    const backFile = backInput && backInput.files && backInput.files[0] ? await prepareImageForUpload(backInput.files[0], { maxSide: 2600, quality: 0.9 }) : null;
    const selfieFile = await prepareImageForUpload(selfieInput.files[0], { maxSide: 1600, quality: 0.88 });
    const formData = new FormData();
    formData.append('docType', docType);
    formData.append('idLegalName', idLegalName);
    formData.append('document', idFile);
    if (backFile) formData.append('documentBack', backFile);
    formData.append('selfie', selfieFile);
    setBusy('Uploading…');
    const res = await fetch(`${API_BASE}/verification/submit`, {
      method: 'POST',
      headers: AUTH.token ? { Authorization: `Bearer ${AUTH.token}` } : {},
      body: formData,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || 'Could not submit for review');
    showToast('Submitted. A person on our team will review it, usually within 48 hours.');
    if (role === 'customer') { await loadCustomerData(); selectCustomerSection('verification'); }
    else { await loadProviderData(); selectProviderSection('verification'); }
  } catch (e) {
    setBusy('');
    showToast(e && e.message === 'Failed to fetch' ? 'The upload didn\'t go through. Check your connection and try again.' : (e.message || 'Could not submit for review'));
  }
}

// Checks whether real, live ID verification (Persona) is actually
// connected, and if so replaces the manual upload boxes with a real
// 'Verify Now' button that hands off to Persona's hosted flow — the
// person completes it on Persona's own page and the result comes back
// automatically via webhook (see misc.routes.js). If Persona isn't
// configured, this is a no-op and the manual submit flow above stays as
// the only option, same as before this existed.
// Item: this endpoint (GET /verification/doc-types) already existed on
// the backend — real, working, country-aware — with zero frontend
// caller anywhere before this. It's the honest source for this
// dropdown instead of a hardcoded guess: the real list of acceptable ID
// types actually differs by country (Driver's License/State ID/
// Passport in the US, different real document types elsewhere).
async function loadVerificationDocTypes() {
  const select = document.getElementById('verification-doc-type-select');
  if (!select) return;
  if (!BACKEND_AVAILABLE) { select.innerHTML = '<option>Government ID</option>'; return; }
  try {
    const { docTypes } = await apiFetch('GET', '/verification/doc-types');
    select.innerHTML = docTypes.map(t => `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('');
  } catch (e) { select.innerHTML = '<option>Government ID</option>'; }
}

async function loadVerificationOptions() {
  if (!BACKEND_AVAILABLE) return;
  const area = document.getElementById('verification-action-area');
  if (!area) return; // already verified or in review — nothing to swap in
  loadVerificationDocTypes(); // populate the real, country-aware document-type dropdown regardless of whether Persona ends up replacing this area below
  try {
    const data = await apiFetch('GET', '/verification/start');
    const target = document.getElementById('verification-action-area');
    if (!target || !data.configured) return; // navigated away, or Persona isn't connected — leave manual flow as-is
    target.innerHTML = `
      <div style="font-size:14px;color:var(--slate);margin-bottom:14px;">Verify your identity in about 2 minutes — takes a photo of your ID and a quick selfie, and confirms automatically.</div>
      <button class="btn-sm btn-sm-primary" onclick="window.location.href=${jsArg(data.hostedFlowUrl)}">🪪 Verify My Identity Now</button>
    `;
  } catch (e) { /* leave the manual flow in place — this is a nice-to-have upgrade, not a hard dependency */ }
}

let activeMessageContact = null; // { id, name }

function getRealContacts(role) {
  // Contacts are derived from real contracts, not an invented list — you can
  // only message someone you actually have a booking with.
  const source = role === 'provider' ? providerData.contracts : customerData.bookings;
  const seen = new Map();
  source.forEach(item => {
    const id = role === 'provider' ? item.customerId : item.providerId;
    const name = role === 'provider' ? item.customer : item.pro;
    if (id && !seen.has(id)) seen.set(id, { id, name });
  });
  return Array.from(seen.values());
}

function messagingHTML(role) {
  const contacts = getRealContacts(role);
  if (!BACKEND_AVAILABLE) {
    return `<div class="dash-header"><div><div class="dash-title">Messages</div><div class="dash-sub">Connect the backend to message your real contacts</div></div></div>
    <div class="panel" style="text-align:center;color:var(--slate);padding:40px;">Messaging requires the backend to be running (demo mode — no backend detected).</div>`;
  }
  if (!contacts.length) {
    return `<div class="dash-header"><div><div class="dash-title">Messages</div><div class="dash-sub">All conversations are tied to a real booking</div></div></div>
    <div class="panel" style="text-align:center;color:var(--slate);padding:40px;">No conversations yet — messaging unlocks once you have a booking with a ${role === 'provider' ? 'customer' : 'pro'}.</div>`;
  }
  if (!activeMessageContact || !contacts.some(c => c.id === activeMessageContact.id)) {
    activeMessageContact = contacts[0];
  }
  return `
  <div class="dash-header"><div><div class="dash-title">Messages</div><div class="dash-sub">Real conversations, tied to your actual bookings</div></div></div>
  <div class="msg-layout">
    <div class="msg-list" id="msg-contact-list">${contacts.map(c => `<div class="msg-item ${c.id === activeMessageContact.id ? 'active' : ''}" data-contact-id="${c.id}" onclick="selectMessageContact('${c.id}')"><div class="msg-item-name">${escapeHtml(c.name)}</div><div class="msg-item-preview">Tap to view conversation</div></div>`).join('')}</div>
    <div class="msg-thread">
      <div class="msg-thread-body" id="msg-thread-body"><div style="text-align:center;color:var(--slate);font-size:13.5px;padding:20px;">Loading…</div></div>
      <div class="msg-input-row"><input type="text" placeholder="Type a message..." id="msg-input" onkeypress="if(event.key==='Enter')sendRealMessage()"/><button onclick="sendRealMessage()">Send</button></div>
    </div>
  </div>`;
}

async function loadMessageThread() {
  const body = document.getElementById('msg-thread-body');
  if (!body || !activeMessageContact || !AUTH.user) return;
  try {
    const { messages } = await apiFetch('GET', `/messages/${activeMessageContact.id}`);
    body.innerHTML = messages.length
      ? messages.map(m => `<div class="msg-bubble ${m.fromId === AUTH.user.id ? 'me' : 'them'}">${escapeHtml(m.text)}</div>`).join('')
      : `<div style="text-align:center;color:var(--slate);font-size:13.5px;padding:20px;">No messages yet — say hello.</div>`;
    body.scrollTop = body.scrollHeight;
  } catch (e) {
    body.innerHTML = `<div style="text-align:center;color:var(--slate);font-size:13.5px;padding:20px;">Could not load messages.</div>`;
  }
}

function selectMessageContact(id) {
  if (!AUTH.user) return;
  const role = AUTH.user.role;
  const contacts = getRealContacts(role);
  activeMessageContact = contacts.find(c => c.id === id) || activeMessageContact;
  // Highlight by matching the id in the re-rendered list, rather than
  // relying on the implicit global `event` object — that only exists when
  // this is called directly as an inline onclick handler, and breaks
  // silently when called programmatically (e.g. the "Discuss this offer"
  // shortcut jumping here from the bookings tab).
  document.querySelectorAll('#msg-contact-list .msg-item').forEach(el => {
    el.classList.toggle('active', el.dataset.contactId === id);
  });
  loadMessageThread();
}

async function sendRealMessage() {
  const input = document.getElementById('msg-input');
  const text = input.value.trim();
  if (!text || !activeMessageContact) return;
  try {
    await apiFetch('POST', '/messages', { toId: activeMessageContact.id, text });
    input.value = '';
    await loadMessageThread();
  } catch (e) {
    showToast(e.message || 'Could not send message');
  }
}

// Buckets real payout history into ISO weeks for the earnings chart —
// replaces what used to be entirely made-up numbers ([410, 520, 295...])
// with whatever the provider's actual payouts add up to, week by week.
function weeklyEarningsChartData(payouts) {
  if (!payouts || !payouts.length) return [];
  const weekOf = (dateStr) => {
    const d = new Date(dateStr);
    if (isNaN(d)) return 'Unknown';
    const onejan = new Date(d.getFullYear(), 0, 1);
    const week = Math.ceil((((d - onejan) / 86400000) + onejan.getDay() + 1) / 7);
    return `Wk ${week}`;
  };
  const totals = {};
  payouts.forEach(p => {
    const key = weekOf(p.date);
    totals[key] = (totals[key] || 0) + (p.amount || 0);
  });
  return Object.entries(totals)
    .sort((a, b) => parseInt(a[0].replace('Wk ', '')) - parseInt(b[0].replace('Wk ', '')))
    .slice(-6)
    .map(([label, val]) => ({ label, val }));
}

function barChart(data, opts = {}) {
  const max = Math.max(...data.map(d => d.val), 1);
  return `<div class="bar-chart">${data.map((d, i) => `<div class="bar-col ${opts.clickable ? 'bar-col-clickable' : ''}" style="--bar-i:${i};" data-category="${escapeHtml(d.category || '')}" ${opts.clickable ? `onclick="filterReportsByCategory(${jsArg(d.category || '')}, this)"` : ''} onmouseenter="showBarTooltip(this, ${jsArg(d.fullLabel || d.label)})" onmouseleave="hideBarTooltip()"><div class="bar-fill" style="--bar-target-height:${Math.max(6, d.val / max * 100)}px"></div><div class="bar-label">${escapeHtml(d.label)}</div></div>`).join('')}</div>`;
}

// A real floating tooltip, not the browser's native title attribute (which
// is slow to appear, can't be styled, and gets clipped inside a scrolling
// panel). Positioned above whichever bar triggered it.
function showBarTooltip(el, text) {
  hideBarTooltip();
  const rect = el.getBoundingClientRect();
  const tip = document.createElement('div');
  tip.id = 'bar-tooltip';
  tip.className = 'bar-tooltip';
  tip.textContent = text;
  document.body.appendChild(tip);
  const tipRect = tip.getBoundingClientRect();
  tip.style.left = `${rect.left + rect.width / 2 - tipRect.width / 2}px`;
  tip.style.top = `${rect.top - tipRect.height - 8}px`;
  requestAnimationFrame(() => tip.classList.add('visible'));
}
function hideBarTooltip() {
  const tip = document.getElementById('bar-tooltip');
  if (tip) tip.remove();
}

// Clicking a Demand by Category bar filters the Category Performance and
// Top Providers tables below it down to just that category — a real
// drill-down, not just a static chart to look at. Click the same bar
// again (or "Clear Filter") to go back to seeing everything.
let reportsySelectedCategory = null;
function filterReportsByCategory(category, el) {
  const ra = adminData.reportsAnalytics;
  if (!ra) return;
  reportsySelectedCategory = (reportsySelectedCategory === category) ? null : category;
  document.querySelectorAll('.bar-col-clickable').forEach(b => b.classList.toggle('bar-col-selected', b.dataset.category === reportsySelectedCategory));

  const perfRows = reportsySelectedCategory ? ra.categoryPerformance.filter(c => c.category === reportsySelectedCategory) : ra.categoryPerformance;
  const perfWrap = document.getElementById('category-performance-table-wrap');
  if (perfWrap) perfWrap.innerHTML = categoryPerformanceTableHTML(perfRows);

  const provRows = reportsySelectedCategory ? ra.topProviders.filter(p => p.category === reportsySelectedCategory) : ra.topProviders;
  const provWrap = document.getElementById('top-providers-table-wrap');
  if (provWrap) provWrap.innerHTML = topProvidersTableHTML(provRows);

  const filterNote = document.getElementById('reports-filter-note');
  if (filterNote) filterNote.innerHTML = reportsySelectedCategory
    ? `Showing <strong>${escapeHtml(reportsySelectedCategory)}</strong> only — <a href="#" onclick="filterReportsByCategory(${jsArg(reportsySelectedCategory)});return false;" style="color:var(--teal);">Clear filter</a>`
    : '';
}

let LAST_REPORT_BUILDER_ROWS = [];

async function runReportBuilder() {
  const resultsEl = document.getElementById('report-builder-results');
  resultsEl.innerHTML = '<div style="color:var(--slate);font-size:14px;">Running report…</div>';
  if (!BACKEND_AVAILABLE) return showToast('Requires a live backend connection');
  const params = new URLSearchParams();
  const dateFrom = document.getElementById('rb-date-from').value;
  const dateTo = document.getElementById('rb-date-to').value;
  const category = document.getElementById('rb-category').value.trim();
  const city = document.getElementById('rb-city').value.trim();
  const status = document.getElementById('rb-status').value;
  const providerTier = document.getElementById('rb-tier').value;
  if (dateFrom) params.set('dateFrom', dateFrom);
  if (dateTo) params.set('dateTo', dateTo);
  if (category) params.set('category', category);
  if (city) params.set('city', city);
  if (status) params.set('status', status);
  if (providerTier) params.set('providerTier', providerTier);
  try {
    const { rows, total } = await apiFetch('GET', `/admin/report-builder?${params.toString()}`);
    LAST_REPORT_BUILDER_ROWS = rows;
    document.getElementById('rb-export-btn').style.display = rows.length ? 'inline-block' : 'none';
    if (!rows.length) {
      resultsEl.innerHTML = '<div style="color:var(--slate);font-size:14px;padding:12px 0;">No bookings match these filters.</div>';
      return;
    }
    resultsEl.innerHTML = `
      <div class="stat-cards" style="margin-bottom:16px;">
        <div class="stat-card"><div class="stat-card-label">Bookings Found</div><div class="stat-card-val">${total.count}</div></div>
        <div class="stat-card"><div class="stat-card-label">GMV</div><div class="stat-card-val">$${total.gmv.toLocaleString()}</div></div>
        <div class="stat-card"><div class="stat-card-label">Service Fee Revenue</div><div class="stat-card-val">$${total.serviceFeeRevenue.toLocaleString()}</div></div>
        <div class="stat-card"><div class="stat-card-label">Completed / Cancelled</div><div class="stat-card-val" style="font-size:20px;">${total.completed} / ${total.cancelled}</div></div>
      </div>
      <div class="data-table-wrap"><table class="data-table"><thead><tr><th>Booking #</th><th>Service</th><th>Status</th><th>Amount</th><th>Fee</th><th>Customer</th><th>Provider</th><th>Category</th><th>Tier</th><th>City</th><th>Date</th></tr></thead><tbody>
      ${rows.slice(0, 200).map(r => `<tr><td>${escapeHtml(r.bookingNumber || '—')}</td><td>${escapeHtml((r.service || '').slice(0, 40))}</td><td>${statusBadge(r.status)}</td><td>$${r.amount}</td><td>$${r.serviceFee}</td><td>${escapeHtml(r.customerName)}</td><td>${escapeHtml(r.providerName)}</td><td>${escapeHtml(r.providerCategory) || '—'}</td><td>${tierBadgeHTML(r.providerTier)}</td><td>${escapeHtml(r.city) || '—'}</td><td>${r.createdAt ? r.createdAt.slice(0,10) : '—'}</td></tr>`).join('')}
      </tbody></table></div>
      ${rows.length > 200 ? `<div style="font-size:13px;color:var(--slate);margin-top:8px;">Showing the first 200 of ${rows.length} — export to CSV for the complete set.</div>` : ''}
    `;
  } catch (e) { resultsEl.innerHTML = `<div style="color:var(--red);font-size:14px;">${escapeHtml(e.message || 'Could not run this report')}</div>`; }
}

function exportReportBuilderCSV() {
  if (!LAST_REPORT_BUILDER_ROWS.length) return showToast('Run a report first');
  const headers = ['Booking Number', 'Service', 'Status', 'Amount', 'Service Fee', 'Customer', 'Provider', 'Category', 'Tier', 'City', 'Country', 'Date'];
  const csvRows = LAST_REPORT_BUILDER_ROWS.map(r => [
    r.bookingNumber, r.service, r.status, r.amount, r.serviceFee, r.customerName, r.providerName, r.providerCategory, r.providerTier, r.city, r.country, r.createdAt ? r.createdAt.slice(0, 10) : '',
  ].map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(','));
  const csv = [headers.join(','), ...csvRows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `trothen-report-${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

