async function submitDispute(contractId) {
  const reason = document.getElementById('dispute-reason').value.trim();
  if (!reason || reason.length < 10) return showToast('Describe the issue in at least 10 characters');
  if (!BACKEND_AVAILABLE) { showToast('Dispute submitted (demo mode)'); document.getElementById('dispute-modal-overlay').remove(); return; }
  try {
    const { dispute } = await apiFetch('POST', '/disputes', { contractId, reason });
    showToast('Dispute submitted — our team will review it');
    // Real evidence upload — offered right after filing, since that's
    // the natural moment someone actually has a photo or screenshot
    // ready, rather than making them hunt for a separate screen later.
    // Skipping is fine; the dispute itself is already filed either way.
    document.getElementById('dispute-modal-overlay').innerHTML = `
      <div class="modal" onclick="event.stopPropagation()">
        <div class="modal-header">
          <button class="modal-close" onclick="document.getElementById('dispute-modal-overlay').remove()">✕</button>
          <h3>Add Evidence (optional)</h3>
          <p>A photo, screenshot, or receipt helps our team resolve this faster.</p>
        </div>
        <div class="modal-body">
          <input type="file" id="dispute-evidence-file" accept="image/*,application/pdf"/>
          <div id="dispute-evidence-list" style="margin-top:12px;font-size:13.5px;color:var(--slate);"></div>
        </div>
        <div class="modal-footer">
          <button class="btn-sm btn-sm-outline" onclick="uploadDisputeEvidence('${dispute.id}')">Upload</button>
          <button class="confirm-btn" onclick="document.getElementById('dispute-modal-overlay').remove()">Done</button>
        </div>
      </div>`;
    if (AUTH.user.role === 'customer') { await loadCustomerData(); selectCustomerSection('bookings'); }
    else { await loadProviderData(); selectProviderSection('contracts'); }
  } catch (e) { showToast(e.message || 'Could not submit dispute'); }
}

// v80: every photo is prepared in the browser before it's sent.
// A photo straight off a phone is often 5 to 15MB. That's slow on a mobile
// connection and used to be refused outright as "too large". This turns
// the photo the right way up, shrinks it so its longest side is at most
// `maxSide` pixels, and saves it as JPEG (usually well under 1.5MB), which
// is still easily sharp enough to read an ID. PDFs, videos and GIFs are
// sent as they are. A photo the browser can't open (HEIC on most
// browsers) gets a plain message saying what to do.
async function prepareImageForUpload(file, opts) {
  const { maxSide = 2400, quality = 0.88, skipUnder = 1.2 * 1024 * 1024 } = opts || {};
  if (!file) return file;
  const name = file.name || 'photo';
  const looksHeic = /heic|heif/i.test(file.type || '') || /\.hei[cf]$/i.test(name);
  const isImage = /^image\//.test(file.type || '') || looksHeic;
  if (!isImage || file.type === 'image/gif') return file;
  if (!looksHeic && file.size <= skipUnder && (file.type === 'image/jpeg' || file.type === 'image/png')) return file;
  const cantOpen = new Error(looksHeic
    ? 'That photo is in HEIC format, which this browser can\'t open. Take the photo again from this page, or save it as JPEG first.'
    : 'That photo couldn\'t be opened. Try taking it again.');
  let source = null, w = 0, h = 0;
  try {
    if (typeof createImageBitmap === 'function') {
      try { source = await createImageBitmap(file, { imageOrientation: 'from-image' }); } catch (e) { source = await createImageBitmap(file); }
      w = source.width; h = source.height;
    }
  } catch (e) { source = null; }
  if (!source) {
    const url = URL.createObjectURL(file);
    try {
      source = await new Promise((resolve, reject) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = reject; im.src = url; });
      w = source.naturalWidth; h = source.naturalHeight;
    } catch (e) { URL.revokeObjectURL(url); throw cantOpen; }
    URL.revokeObjectURL(url);
  }
  if (!w || !h) throw cantOpen;
  const scale = Math.min(1, maxSide / Math.max(w, h));
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(w * scale)); canvas.height = Math.max(1, Math.round(h * scale));
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height); // a see-through PNG would otherwise turn black as JPEG
  ctx.drawImage(source, 0, 0, canvas.width, canvas.height);
  if (source.close) source.close();
  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', quality));
  if (!blob) throw cantOpen;
  // Never send something bigger than what we were given.
  if (blob.size >= file.size && (file.type === 'image/jpeg' || file.type === 'image/png' || file.type === 'image/webp')) return file;
  return new File([blob], name.replace(/\.[^.]+$/, '') + '.jpg', { type: 'image/jpeg' });
}

async function uploadDisputeEvidence(disputeId) {
  const input = document.getElementById('dispute-evidence-file');
  if (!input.files || !input.files[0]) return showToast('Choose a file first');
  const formData = new FormData();
  try {
    formData.append('file', await prepareImageForUpload(input.files[0], { maxSide: 2600, quality: 0.9 }));
    const res = await fetch(`${API_BASE}/disputes/${disputeId}/evidence`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${AUTH.token}` },
      body: formData,
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Upload failed');
    showToast('Evidence uploaded');
    input.value = '';
    const listEl = document.getElementById('dispute-evidence-list');
    if (listEl) listEl.innerHTML += `<div>✓ ${escapeHtml(data.evidence.originalName)}</div>`;
  } catch (e) { showToast(e.message || 'Could not upload evidence'); }
}

