// Referral panel: the code itself is already on AUTH.user for anyone who
// signed up after this feature shipped, but the stats (how many people,
// who) need a real fetch — and any account created before this feature
// existed needs its code backfilled server-side too (see GET
// /api/referrals/mine). Rendered as a loading state first, then filled in
// via a targeted innerHTML update on #referral-panel-body rather than
// re-rendering the whole settings section — if the element's gone by the
// time the fetch resolves (person navigated away), this is a no-op.
function referralPanelHTML() {
  return `<div class="panel"><div class="panel-title">Your Referral Link</div>
    <div style="font-size:13.5px;color:var(--slate);margin-bottom:14px;">Invite people you trust to Trothen — share your personal link by text, WhatsApp, or on social media.</div>
    <div id="referral-panel-body" style="font-size:13.5px;color:var(--slate);">Loading your referral link…</div>
  </div>`;
}

// Loads the provider's real, live trust score into the overview panel —
// a targeted update on #provider-score-body, not a full section
// re-render, so it's a no-op if the person's navigated away before this
// resolves.
// Loads and renders any active promotions targeting this person (see
// GET /api/promotions/mine) into whichever banner container exists for
// their role. Dismissing a banner is stored in localStorage, per
// browser — reasonable for a promo banner (it's not sensitive account
// state that needs to follow someone across devices), and means a
// dismissed banner won't come back on next login in the same browser,
// but naturally reappears if they check from somewhere new.
async function loadPromotionsBanner(containerId) {
  if (!BACKEND_AVAILABLE) return;
  const container = document.getElementById(containerId);
  if (!container) return;
  try {
    const { promotions } = await apiFetch('GET', '/promotions/mine');
    const target = document.getElementById(containerId);
    if (!target) return;
    let dismissed = [];
    try { dismissed = JSON.parse(localStorage.getItem('dismissedPromotions') || '[]'); } catch (e) {}
    const visible = promotions.filter(p => !dismissed.includes(p.id));
    target.innerHTML = visible.map(p => `
      <div class="panel" style="background:var(--offwhite);border:1px solid var(--gold);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
        <div style="display:flex;align-items:center;gap:12px;flex:1;min-width:200px;">
          ${p.imageUrl ? `<img src="${escapeHtml(p.imageUrl)}" alt="" style="width:48px;height:48px;object-fit:cover;border-radius:8px;flex-shrink:0;"/>` : '<div style="font-size:22px;">📣</div>'}
          <div><div style="font-weight:700;color:var(--navy);font-size:13.5px;">${escapeHtml(p.title)}</div><div style="font-size:13.5px;color:var(--slate);margin-top:2px;">${escapeHtml(p.message)}</div></div>
        </div>
        <button class="btn-sm btn-sm-ghost" onclick="dismissPromotionBanner('${p.id}','${containerId}')">Dismiss</button>
      </div>`).join('');
  } catch (e) { /* a promo banner failing to load is never worth interrupting the dashboard over */ }
}

function dismissPromotionBanner(promoId, containerId) {
  let dismissed = [];
  try { dismissed = JSON.parse(localStorage.getItem('dismissedPromotions') || '[]'); } catch (e) {}
  if (!dismissed.includes(promoId)) dismissed.push(promoId);
  try { localStorage.setItem('dismissedPromotions', JSON.stringify(dismissed)); } catch (e) {}
  loadPromotionsBanner(containerId);
}

