async function handleHandbookUpload(event) {
  const file = event.target.files[0];
  event.target.value = '';
  if (!file) return;
  if (file.type !== 'application/pdf') return showToast('Must be a PDF file');
  if (file.size > 20 * 1024 * 1024) return showToast('File must be under 20MB');
  const status = document.getElementById('handbook-upload-status');
  if (status) status.textContent = 'Uploading…';
  if (!BACKEND_AVAILABLE) { if (status) status.textContent = file.name + ' (demo mode)'; return; }
  try {
    const formData = new FormData();
    formData.append('file', file);
    const res = await fetch(API_BASE + '/admin/platform-handbook', {
      method: 'POST',
      headers: AUTH.token ? { 'Authorization': 'Bearer ' + AUTH.token } : {},
      body: formData,
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Upload failed');
    if (status) status.textContent = '✓ Uploaded — now live for every new signup';
    showToast('Platform handbook updated');
  } catch (e) {
    showToast(e.message || 'Could not upload handbook');
    if (status) status.textContent = '';
  }
}

