function copyReferralLink() {
  const input = document.getElementById('referral-link-input');
  if (!input) return;
  input.select();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(input.value).then(() => showToast('Referral link copied!')).catch(() => { document.execCommand('copy'); showToast('Referral link copied!'); });
  } else {
    document.execCommand('copy');
    showToast('Referral link copied!');
  }
}

function shareReferralLink(channel) {
  const input = document.getElementById('referral-link-input');
  if (!input) return;
  const link = input.value;
  const text = `Join me on Trothen — trusted local pros, protected payments: ${link}`;
  if (channel === 'whatsapp') {
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank', 'noopener,noreferrer');
  } else if (channel === 'sms') {
    window.open(`sms:?body=${encodeURIComponent(text)}`, '_blank');
  } else if (channel === 'native' && navigator.share) {
    navigator.share({ title: 'Join me on Trothen', text, url: link }).catch(() => {});
  }
}

