async function logoutAllDevices() {
  if (!(await confirmDialog('Sign out of every device this account is currently logged into, including this one? You\'ll need to sign in again here too.', { danger: true, confirmLabel: 'Sign out everywhere' }))) return;
  try {
    const { signedOutDevices } = await apiFetch('POST', '/auth/logout-all', {});
    stopIdleTimer();
    stopMessagePolling();
    AUTH.token = null;
    AUTH.user = null;
    clearAuthSession();
    showToast(`Signed out of ${signedOutDevices} device${signedOutDevices === 1 ? '' : 's'}`);
    goHome();
  } catch (e) { showToast(e.message || 'Could not sign out of all devices'); }
}

async function changePassword(prefix) {
  const currentPassword = document.getElementById(`${prefix}-pw-current`).value;
  const newPassword = document.getElementById(`${prefix}-pw-new`).value;
  const confirm = document.getElementById(`${prefix}-pw-confirm`).value;
  if (!currentPassword || !newPassword || !confirm) return showToast('Fill in all three password fields');
  if (newPassword.length < 8 || newPassword.length > 72) return showToast('New password must be 8-72 characters');
  if (newPassword !== confirm) return showToast("New password and confirmation don't match");
  if (!BACKEND_AVAILABLE) return showToast('Password updated (demo mode — no backend detected)');
  try {
    const data = await apiFetch('POST', '/auth/change-password', { currentPassword, newPassword });
    AUTH.token = data.token;
    saveAuthSession(data.token);
    showToast('Password updated successfully');
    document.getElementById(`${prefix}-pw-current`).value = '';
    document.getElementById(`${prefix}-pw-new`).value = '';
    document.getElementById(`${prefix}-pw-confirm`).value = '';
  } catch (e) { showToast(e.message || 'Could not update password'); }
}

async function saveCustomerSettings() {
  const name = document.getElementById('set-cust-name').value.trim();
  const email = document.getElementById('set-cust-email').value.trim();
  const phone = document.getElementById('set-cust-phone').value.trim();
  const address = document.getElementById('set-cust-address').value.trim();
  const zipCode = document.getElementById('set-cust-zip').value.trim();
  if (name.length < 2) return showToast('Full name must be at least 2 characters');
  if (!isValidEmailClient(email)) return showToast('Enter a valid email address');
  if (phone && phone.length < 7) return showToast('Enter a valid phone number');
  if (!BACKEND_AVAILABLE) return showToast('Settings saved (demo mode — no backend detected)');
  try {
    const { user } = await apiFetch('PATCH', '/auth/me', { name, email, phone, address, zipCode });
    AUTH.user = user;
    updateCustomerSidebar();
    showToast('Settings saved to your account');
  } catch (e) { showToast(e.message || 'Could not save settings'); }
}

function selectCustomerSection(key) {
  renderDashNav('customer-nav', CUSTOMER_NAV_ITEMS, key, 'selectCustomerSection');
  renderSectionSafely('customer-main', key, () => CUSTOMER_SECTIONS[key]());
  if (key === 'messages') loadMessageThread();
  if (key === 'settings') { populateSettingsCountry('cust'); loadReferralPanel(); loadLoyaltyPointsPanel(); loadHandbookLink(); loadMyDataPanel('customer-main'); }
  if (key === 'verification') loadVerificationOptions();
  if (key === 'overview') loadPromotionsBanner('customer-promotions-banner');
  if (key === 'favorites') loadFavoritesPanel();
}

function updateCustomerSidebar() {
  const u = AUTH.user;
  if (!u) return;
  document.getElementById('customer-sidebar-avatar').textContent = u.initials || 'CU';
  document.getElementById('customer-sidebar-name').textContent = u.name;
  document.getElementById('customer-sidebar-role').textContent = `Customer · ${u.verified ? 'Verified ✓' : 'Verification pending'}`;
}

