// Downloads a file that requires an Authorization header — a plain <a
// href> download can't attach auth headers, so this fetches the file with
// the real token and triggers a save via a Blob instead.
async function downloadFileWithAuth(url, fallbackFilename) {
  try {
    const res = await fetch(url, { headers: AUTH.token ? { 'Authorization': 'Bearer ' + AUTH.token } : {} });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      throw new Error(data.error || 'Could not generate PDF');
    }
    const disposition = res.headers.get('Content-Disposition') || '';
    const match = disposition.match(/filename="([^"]+)"/);
    const filename = match ? match[1] : fallbackFilename;
    const blob = await res.blob();
    const blobUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(blobUrl);
  } catch (e) { showToast(e.message || 'Could not download PDF'); }
}

