// A simple lightbox for viewing a job's attached photos full-size — used
// by both the AI-matched job flow and direct bookings, wherever a
// provider is deciding whether to accept. Photo URLs are already escaped
// (this only ever receives an array already validated server-side as our
// own uploaded job-photo paths), so building the img tags directly here
// is safe.
function openJobPhotoViewer(photoUrls) {
  if (!photoUrls || !photoUrls.length) return;
  const modalHtml = `
    <div class="modal-overlay open" id="job-photo-viewer-overlay" onclick="if(event.target===this)document.getElementById('job-photo-viewer-overlay').remove()">
      <div class="modal" style="max-width:600px;">
        <div class="modal-header">
          <button class="modal-close" onclick="document.getElementById('job-photo-viewer-overlay').remove()">✕</button>
          <h3>Job Photos & Videos</h3>
          <p>What the customer shared for this job</p>
        </div>
        <div class="modal-body" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;">
          ${photoUrls.map(url => isVideoUrl(url)
            ? `<video src="${escapeHtml(url)}" controls style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px;background:#000;"></video>`
            : `<img src="${escapeHtml(url)}" alt="Job photo" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px;cursor:pointer;" onclick="window.open(${jsArg(url)},'_blank')"/>`
          ).join('')}
        </div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function matchesTable(list) {
  if (!list.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">No pending matches right now.</div>`;
  return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Job</th><th>Budget</th><th>Match Score</th><th>Distance</th><th>Status</th><th>Action</th></tr></thead><tbody>
  ${list.map(m => `<tr><td>${escapeHtml(m.customer)}</td><td>${escapeHtml(m.service)}${m.photoUrls && m.photoUrls.length ? ` <a onclick='openJobPhotoViewer(${JSON.stringify(m.photoUrls)})' style="color:var(--teal);cursor:pointer;font-size:13px;white-space:nowrap;">📎 ${m.photoUrls.length} file${m.photoUrls.length===1?'':'s'}</a>` : ''}${m.materialsOnHand ? `<div style="font-size:12.5px;color:var(--slate);margin-top:3px;">🧰 Already has: ${escapeHtml(m.materialsOnHand)}</div>` : ''}${m.materialsCost != null ? `<div style="font-size:12.5px;color:var(--slate);margin-top:3px;">💵 Materials budget: $${m.materialsCost}</div>` : ''}</td><td>${escapeHtml(m.budget)}</td><td><span class="badge badge-success">${m.matchScore}%</span></td><td>${escapeHtml(m.distance)}</td><td>${m.status === 'interested' ? '<span class="badge badge-success">🙋 Interested</span>' : '<span class="badge badge-warn">New</span>'}</td>
  <td class="row-actions">${m.status === 'interested'
    ? `<button class="btn-sm btn-sm-outline" onclick="messageCustomerAboutJob('${m.customerId}','${m.jobId}')">💬 Message</button>`
    : `<button class="btn-sm btn-sm-primary" onclick="respondToMatch('${m.id}','accept')">I'm Interested</button><button class="btn-sm btn-sm-outline" onclick="respondToMatch('${m.id}','decline')">Decline</button>`
  }</td></tr>`).join('')}
  </tbody></table></div>`;
}

// Opens a compact, job-scoped chat modal rather than the general
// messaging inbox — the inbox isn't job-scoped (it's built around
// contacts tied to actual bookings), and a provider negotiating over an
// open job doesn't have a booking yet. This mirrors the customer-side
// negotiation view in spirit (see viewJobCandidates) without needing the
// multi-candidate comparison layout a customer needs.
let CURRENT_JOB_NEGOTIATION = null; // { customerId, jobId }

function messageCustomerAboutJob(customerId, jobId) {
  CURRENT_JOB_NEGOTIATION = { customerId, jobId };
  const match = (providerData.matches || []).find(m => m.jobId === jobId && m.customerId === customerId);
  document.getElementById('job-negotiation-title').textContent = `Message ${match ? match.customer : 'Customer'}`;
  document.getElementById('job-negotiation-sub').textContent = match ? match.service : '';
  document.getElementById('job-negotiation-modal').classList.add('open');
  loadJobNegotiationThread();
}

function closeJobNegotiationModal() {
  document.getElementById('job-negotiation-modal').classList.remove('open');
  CURRENT_JOB_NEGOTIATION = null;
}

async function loadJobNegotiationThread() {
  if (!CURRENT_JOB_NEGOTIATION) return;
  const body = document.getElementById('job-negotiation-thread');
  body.innerHTML = `<div style="text-align:center;color:var(--slate);font-size:13.5px;padding:20px;">Loading…</div>`;
  try {
    const { messages } = await apiFetch('GET', `/messages/${CURRENT_JOB_NEGOTIATION.customerId}?jobId=${encodeURIComponent(CURRENT_JOB_NEGOTIATION.jobId)}`);
    body.innerHTML = messages.length
      ? messages.map(m => `<div class="msg-bubble ${m.fromId === AUTH.user.id ? 'me' : 'them'}">${escapeHtml(m.text)}</div>`).join('')
      : `<div style="text-align:center;color:var(--slate);font-size:13.5px;padding:20px;">No messages yet — say hello and start negotiating a price.</div>`;
    body.scrollTop = body.scrollHeight;
  } catch (e) {
    body.innerHTML = `<div style="text-align:center;color:var(--slate);font-size:13.5px;padding:20px;">Could not load messages.</div>`;
  }
}

async function sendJobNegotiationReply() {
  if (!CURRENT_JOB_NEGOTIATION) return;
  const input = document.getElementById('job-negotiation-input');
  const text = input.value.trim();
  if (!text) return;
  try {
    await apiFetch('POST', '/messages', { toId: CURRENT_JOB_NEGOTIATION.customerId, text, jobId: CURRENT_JOB_NEGOTIATION.jobId });
    input.value = '';
    await loadJobNegotiationThread();
  } catch (e) { showToast(e.message || 'Could not send message'); }
}

function contractsTable(list) {
  if (!list.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">No contracts yet.</div>`;
  return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Booking #</th><th>Customer</th><th>Service</th><th>Amount</th><th>Signed</th><th>Status</th><th>Action</th></tr></thead><tbody>
  ${list.map(c => {
    let actions = '';
    if (c.status === 'pending_agreement') {
      actions = `<button class="btn-sm btn-sm-primary" onclick="respondToOffer('${c.id}','accept')">Accept Offer</button> <button class="btn-sm btn-sm-outline" onclick="respondToOffer('${c.id}','decline')">Decline</button> <button class="btn-sm btn-sm-ghost" onclick="selectProviderSection('messages');setTimeout(()=>selectMessageContact('${c.customerId}'),50)">💬 Discuss</button>`;
    } else if (c.status === 'pending_provider_confirmation') {
      actions = `<button class="btn-sm btn-sm-primary" onclick="respondToOffer('${c.id}','accept')">Confirm Booking</button> <button class="btn-sm btn-sm-outline" onclick="respondToOffer('${c.id}','decline')">Can't Take This</button>`;
    } else if (c.status === 'active') {
      const gpsButtons = !c.onMyWayAt
        ? `<button class="btn-sm btn-sm-outline" onclick="markContractOnMyWay('${c.id}')">🚗 On My Way</button> `
        : !c.arrivedAt
          ? `<button class="btn-sm btn-sm-primary" onclick="openTripTracking('${c.id}')">${escapeHtml(tr('Trip map'))}</button> <button class="btn-sm btn-sm-outline" onclick="markContractArrived('${c.id}')">📍 Arrived</button> `
          : `<span style="font-size:12.5px;color:var(--slate);margin-right:6px;">🚗 On the way · 📍 Arrived</span>`;
      actions = `${gpsButtons}<button class="btn-sm btn-sm-outline" onclick="openScopeChangeRequestForm('${c.id}')">➕ Request Additional Payment</button> <button class="btn-sm btn-sm-outline" onclick="cancelProviderContract('${c.id}')">Cancel</button> <button class="btn-sm btn-sm-ghost" onclick="openDisputeForm('${c.id}')">Report a Problem</button>`;
    } else if (c.status === 'expired') {
      actions = `<span style="font-size:13px;color:var(--slate);">You didn't respond in time — automatically cancelled</span>`;
    }
    return `<tr><td>${escapeHtml(c.bookingNumber || c.id)}</td><td>${escapeHtml(c.customer)}</td><td>${escapeHtml(c.service)}${whereHTML(c)}${c.photoUrls && c.photoUrls.length ? ` <a onclick='openJobPhotoViewer(${JSON.stringify(c.photoUrls)})' style="color:var(--teal);cursor:pointer;font-size:13px;white-space:nowrap;">📎 ${c.photoUrls.length} file${c.photoUrls.length===1?'':'s'}</a>` : ''}${c.materialsOnHand ? `<div style="font-size:12.5px;color:var(--slate);margin-top:3px;">🧰 Already has: ${escapeHtml(c.materialsOnHand)}</div>` : ''}${contractGoodsHTML(c.id)}</td><td>$${c.amount}</td><td>${escapeHtml(c.signed) || '—'}</td><td>${statusBadge(c.status)}${responseDeadlineNote(c)}</td><td class="row-actions">${actions} ${handoverButtonHTML(c.id, c.status)} <button class="btn-sm btn-sm-outline" onclick="downloadContractPDF('${c.id}')" title="Download a PDF record of this contract">📄 PDF</button></td></tr>`;
  }).join('')}
  </tbody></table></div>`;
}

// Same as contractsTable, but with a real per-row Escrow column — held,
// released (ready for payout), or already paid out — so the Overview
// page's contract list carries genuine financial detail instead of just
// the booking status.
// The exact thresholds from the published Fees and Payment Policy — if
// those numbers ever change, update them here to match, not the other
// way around.
const TIER_THRESHOLDS = {
  starter: { next: 'pro', nextLabel: 'Pro', nextRate: '9%', jobs: 50, rating: 4.7, cancellationRate: 5 },
  pro: { next: 'superpro', nextLabel: 'Super-Pro', nextRate: '7%', jobs: 500, rating: 4.85, cancellationRate: 2 },
};
const TIER_LABELS = { starter: 'Starter', pro: 'Pro', superpro: 'Super-Pro' };
const TIER_RATES = { starter: '13%', pro: '9%', superpro: '7%' };

function renderTierProgress(currentPlan, jobsCompleted, rating, cancellationRate) {
  const currentLabel = TIER_LABELS[currentPlan] || 'Starter';
  const currentRate = TIER_RATES[currentPlan] || '13%';
  const threshold = TIER_THRESHOLDS[currentPlan];

  if (!threshold) {
    // Already at Super-Pro — nothing further to climb toward from here.
    return `<div class="panel"><div class="panel-title">Your Tier</div>
      <div style="font-size:14px;color:var(--navy);font-weight:700;">${currentLabel} · ${currentRate} commission</div>
      <div style="font-size:13.5px;color:var(--slate);margin-top:4px;">You've reached the top individual tier. Thank you for the record that got you here.</div>
    </div>`;
  }

  const bar = (label, current, target, unit, lowerIsBetter) => {
    const metGoal = lowerIsBetter ? current <= target : current >= target;
    const displayPct = lowerIsBetter ? Math.min(100, Math.max(0, 100 - (current / (target * 2)) * 100)) : Math.min(100, (current / target) * 100);
    return `
      <div style="margin-bottom:14px;">
        <div style="display:flex;justify-content:space-between;font-size:13.5px;margin-bottom:5px;">
          <span style="color:var(--navy);font-weight:600;">${label}</span>
          <span style="color:${metGoal ? '#2E8C6F' : 'var(--slate)'};font-weight:600;">${current}${unit} ${metGoal ? '✓' : `/ ${target}${unit} needed`}</span>
        </div>
        <div style="background:var(--border);border-radius:4px;height:6px;overflow:hidden;">
          <div style="background:${metGoal ? '#2E8C6F' : 'var(--teal)'};height:100%;width:${displayPct}%;border-radius:4px;"></div>
        </div>
      </div>`;
  };

  const jobsMet = jobsCompleted >= threshold.jobs;
  const ratingMet = rating !== null && rating >= threshold.rating;
  const cancellationMet = cancellationRate <= threshold.cancellationRate;
  const allMet = jobsMet && ratingMet && cancellationMet;

  return `<div class="panel">
    <div class="panel-title">Your Path to ${threshold.nextLabel} <small style="font-weight:400;color:var(--slate);">currently ${currentLabel} · ${currentRate} commission</small></div>
    ${allMet ? `<div style="background:#EAF4EF;border:1px solid #2E8C6F;border-radius:8px;padding:12px 14px;margin-bottom:14px;font-size:14px;color:#1C5C42;">✓ You meet every published requirement for ${threshold.nextLabel} (${threshold.nextRate} commission). Tier changes are reviewed, not automatic — reach out if you'd like it looked at.</div>` : ''}
    ${bar('Jobs completed', jobsCompleted, threshold.jobs, '', false)}
    ${bar('Average rating', rating !== null ? rating.toFixed(2) : 0, threshold.rating, '★', false)}
    ${bar('Cancellation rate', cancellationRate.toFixed(1), threshold.cancellationRate, '%', true)}
    <div style="font-size:12.5px;color:var(--muted);margin-top:4px;">Cancelling because a job wasn't as described, was unsafe, needed a different trade, or required a license you don't hold never counts here. ${threshold.next === 'superpro' ? 'Super-Pro also requires 12 months active with no upheld serious complaint.' : ''}</div>
  </div>`;
}

function contractsTableWithEscrow(list) {
  if (!list.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">No contracts yet.</div>`;
  return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Booking #</th><th>Customer</th><th>Service</th><th>Amount</th><th>Escrow</th><th>Status</th><th>Action</th></tr></thead><tbody>
  ${list.map(c => {
    let escrowLabel = '—';
    if (c.escrow) {
      if (c.escrow.status === 'released' && c.escrow.payoutId) escrowLabel = '<span style="color:var(--muted);">Paid out</span>';
      else if (c.escrow.status === 'released') escrowLabel = '<span style="color:#2E8C6F;font-weight:600;">Available</span>';
      else if (c.escrow.status === 'held') escrowLabel = '<span style="color:var(--gold);">Held</span>';
    }
    return `<tr><td>${c.bookingNumber || c.id}</td><td>${escapeHtml(c.customer)}</td><td>${escapeHtml(c.service)}</td><td>$${c.amount}</td><td>${escrowLabel}</td><td>${statusBadge(c.status)}</td><td class="row-actions"><button class="btn-sm btn-sm-outline" onclick="downloadContractPDF('${c.id}')" title="Download a PDF record of this contract">📄 PDF</button></td></tr>`;
  }).join('')}
  </tbody></table></div>`;
}

async function respondToOffer(contractId, decision) {
  if (!BACKEND_AVAILABLE) return showToast(decision === 'accept' ? 'Booking confirmed (demo mode)' : 'Booking declined (demo mode)');
  if (decision === 'decline' && !(await confirmDialog("Decline this booking? The customer will be notified and refunded."))) return;
  try {
    const { contract } = await apiFetch('POST', `/contracts/${contractId}/respond-offer`, { decision });
    showToast(decision === 'accept' ? `Booking confirmed — $${contract.amount} held in escrow` : 'Booking declined — customer refunded');
    await loadProviderData();
    selectProviderSection('contracts');
  } catch (e) { showToast(e.message || 'Could not respond to this booking'); }
}

// Captures a one-time GPS coordinate if possible (never blocks on it —
// declined permission or an unsupported browser just means the status
// update goes through without a coordinate attached, same as the rest of
// this app's honest-degradation pattern elsewhere).
// v92: uses the patient helper above. Still optional: if the phone can't
// find itself, the pro's "on my way" / "arrived" tap goes through anyway.
async function getOneTimeLocation() {
  const r = await getBestLocation({ goodEnoughM: 150, maxWaitMs: 12000 });
  return r.error ? null : { latitude: r.latitude, longitude: r.longitude, accuracyM: r.accuracyM };
}

async function viewScopeChangeRequests(contractId) {
  if (!BACKEND_AVAILABLE) return showToast('Requires a live backend connection');
  const modalHtml = `
    <div class="modal-overlay open" id="scope-requests-overlay" onclick="if(event.target===this)document.getElementById('scope-requests-overlay').remove()">
      <div class="modal">
        <div class="modal-header">
          <button class="modal-close" onclick="document.getElementById('scope-requests-overlay').remove()">✕</button>
          <h3>Additional Requests</h3>
          <p>Extra amounts your provider has requested for this job — nothing changes unless you approve.</p>
        </div>
        <div class="modal-body" id="scope-requests-body">Loading…</div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  try {
    const { requests } = await apiFetch('GET', `/contracts/${contractId}/scope-change-requests`);
    const body = document.getElementById('scope-requests-body');
    if (!body) return;
    if (!requests.length) {
      body.innerHTML = `<div style="color:var(--slate);font-size:13.5px;padding:12px 0;">No additional requests on this job.</div>`;
      return;
    }
    const STATUS_BADGE = { pending: '<span class="badge badge-warn">Awaiting your decision</span>', approved: '<span class="badge badge-success">Approved</span>', declined: '<span class="badge badge-neutral">Declined</span>' };
    body.innerHTML = requests.map(r => `
      <div class="panel" style="margin:0 0 12px 0;padding:14px 16px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
          <strong style="color:var(--navy);">$${r.amount}</strong>
          ${STATUS_BADGE[r.status] || r.status}
        </div>
        <div style="font-size:13.5px;color:var(--slate);margin-bottom:10px;">${escapeHtml(r.reason)}</div>
        ${r.status === 'pending' ? `<div style="display:flex;gap:8px;">
          <button class="btn-sm btn-sm-primary" onclick="decideScopeChangeRequest('${r.id}','approve','${contractId}')">Approve</button>
          <button class="btn-sm btn-sm-outline" onclick="decideScopeChangeRequest('${r.id}','decline','${contractId}')">Decline</button>
        </div>` : ''}
      </div>`).join('');
  } catch (e) {
    const body = document.getElementById('scope-requests-body');
    if (body) body.textContent = e.message || 'Could not load requests';
  }
}

async function decideScopeChangeRequest(requestId, decision, contractId) {
  if (decision === 'approve' && !(await confirmDialog('Approve this additional amount? This will update the contract total and the held escrow immediately.'))) return;
  try {
    await apiFetch('POST', `/scope-change-requests/${requestId}/decide`, { decision });
    showToast(decision === 'approve' ? 'Approved — contract updated' : 'Declined');
    document.getElementById('scope-requests-overlay')?.remove();
    await loadCustomerData();
    selectCustomerSection('bookings');
  } catch (e) { showToast(e.message || 'Could not process this decision'); }
}

function openScopeChangeRequestForm(contractId) {
  const modalHtml = `
    <div class="modal-overlay open" id="scope-change-overlay" onclick="if(event.target===this)document.getElementById('scope-change-overlay').remove()">
      <div class="modal">
        <div class="modal-header">
          <button class="modal-close" onclick="document.getElementById('scope-change-overlay').remove()">✕</button>
          <h3>Request Additional Payment</h3>
          <p>For when the job turns out bigger than what was originally posted or booked — the customer has to approve this before anything changes.</p>
        </div>
        <div class="modal-body">
          <div class="form-group"><label class="form-label">Additional Amount</label><input class="form-input" type="number" min="1" step="0.01" id="scope-change-amount" placeholder="$40.00"/></div>
          <div class="form-group"><label class="form-label">What changed?</label><textarea class="form-input" id="scope-change-reason" rows="3" style="resize:vertical;" placeholder="Explain what's different from what was originally agreed"></textarea></div>
        </div>
        <div class="modal-footer">
          <button class="confirm-btn" onclick="submitScopeChangeRequest('${contractId}')">Send Request to Customer</button>
        </div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

async function submitScopeChangeRequest(contractId) {
  const amount = parseFloat(document.getElementById('scope-change-amount').value);
  const reason = document.getElementById('scope-change-reason').value.trim();
  if (!(amount > 0)) return showToast('Enter a valid additional amount');
  if (reason.length < 10) return showToast('Explain what changed (at least 10 characters)');
  if (!BACKEND_AVAILABLE) { showToast('Request sent (demo mode)'); document.getElementById('scope-change-overlay')?.remove(); return; }
  try {
    await apiFetch('POST', `/contracts/${contractId}/scope-change-request`, { amount, reason });
    showToast('Additional request sent — the customer needs to approve it');
    document.getElementById('scope-change-overlay')?.remove();
  } catch (e) { showToast(e.message || 'Could not send this request'); }
}

async function markContractOnMyWay(contractId) {
  if (!BACKEND_AVAILABLE) return showToast('Marked on the way (demo mode)');
  // v93: the pro agrees to share their live position for this trip.
  const ok = await confirmDialog(tr("Tell the customer you're on the way? Your live location will be shared with this customer, and only this customer, until you tap Arrived. Keep this page open on your phone so they can see you coming."), { confirmLabel: tr("I'm on my way") });
  if (!ok) return;
  showToast('Finding your location…');
  const location = await getOneTimeLocation();
  try {
    await apiFetch('POST', `/contracts/${contractId}/on-my-way`, location || {});
    showToast('Customer notified you\'re on the way');
    startLiveTrip(contractId);
    await loadProviderData();
    selectProviderSection('contracts');
    openTripTracking(contractId);
  } catch (e) { showToast(e.message || 'Could not update status'); }
}

async function markContractArrived(contractId) {
  if (!BACKEND_AVAILABLE) return showToast('Marked arrived (demo mode)');
  const location = await getOneTimeLocation();
  try {
    await apiFetch('POST', `/contracts/${contractId}/arrived`, location || {});
    stopLiveTrip();
    showToast('Customer notified you\'ve arrived');
    await loadProviderData();
    selectProviderSection('contracts');
  } catch (e) { showToast(e.message || 'Could not update status'); }
}

function cancelProviderContract(contractId) {
  if (!BACKEND_AVAILABLE) return showToast('Contract cancelled (demo mode)');
  const reasons = [
    ['not_as_described', "Job wasn't as described"],
    ['unsafe', 'Became unsafe to continue'],
    ['out_of_category', 'Turned out to need a different trade/category'],
    ['unlicensed_required', "Requires a license I don't hold"],
    ['schedule_conflict', 'Scheduling conflict'],
    ['other', 'Other'],
  ];
  const modalHtml = `
    <div class="modal-overlay open" id="cancel-reason-overlay" onclick="if(event.target===this)document.getElementById('cancel-reason-overlay').remove()">
      <div class="modal" style="max-width:420px;">
        <div class="modal-header">
          <button class="modal-close" onclick="document.getElementById('cancel-reason-overlay').remove()">✕</button>
          <h3>Why are you cancelling?</h3>
          <p>The customer's held escrow will be refunded, and you won't be paid for this job.</p>
        </div>
        <div class="modal-body">
          ${reasons.map(([val, label], i) => `
            <label style="display:flex;align-items:center;gap:10px;padding:9px 0;cursor:pointer;font-size:13.5px;">
              <input type="radio" name="cancel-reason" value="${escapeHtml(val)}" ${i === 0 ? 'checked' : ''}/>
              <span>${label}</span>
            </label>`).join('')}
          <div style="font-size:13px;color:var(--muted);margin-top:10px;line-height:1.5;">Cancelling because a job wasn't as described, became unsafe, needs a different trade, or requires a license you don't hold never counts against your standing — that's a system rule, not a judgment call.</div>
        </div>
        <div class="modal-footer">
          <button class="confirm-btn" onclick="confirmProviderCancel('${contractId}')">Cancel This Job</button>
        </div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

async function confirmProviderCancel(contractId) {
  const selected = document.querySelector('input[name="cancel-reason"]:checked');
  const reason = selected ? selected.value : 'other';
  try {
    await apiFetch('POST', `/contracts/${contractId}/cancel`, { reason });
    const overlay = document.getElementById('cancel-reason-overlay');
    if (overlay) overlay.remove();
    showToast('Contract cancelled — customer notified and refunded');
    await loadProviderData();
    selectProviderSection('contracts');
  } catch (e) { showToast(e.message || 'Could not cancel this contract'); }
}

function selectProviderSection(key) {
  const availableForPayout = providerData.contracts
    .filter(c => c.escrow && c.escrow.status === 'released' && !c.escrow.payoutId)
    .reduce((s, c) => s + c.escrow.amount, 0);
  const navItems = PROVIDER_NAV_ITEMS.map(it => it.key === 'earnings' ? { ...it, dot: availableForPayout > 0 } : it);
  renderDashNav('provider-nav', navItems, key, 'selectProviderSection');
  renderSectionSafely('provider-main', key, () => PROVIDER_SECTIONS[key]());
  if (key === 'messages') loadMessageThread();
  if (key === 'settings') { populateSettingsCountry('prov'); populateSettingsCategory(); loadReferralPanel(); loadHandbookLink(); loadMyDataPanel('provider-main'); }
  if (key === 'verification') loadVerificationOptions();
  if (key === 'earnings') loadPlanFeePanel();
  if (key === 'overview') { loadProviderScorePanel(); loadPromotionsBanner('provider-promotions-banner'); }
  if (key === 'store') loadMyStore(); // v105
  if (key === 'business') loadBusiness();
  if (key === 'settings') loadExtraSkillsPanel();
}

function updateProviderSidebar() {
  const u = AUTH.user;
  if (!u) return;
  document.getElementById('provider-sidebar-avatar').textContent = u.initials || 'PR';
  document.getElementById('provider-sidebar-avatar').style.background = u.color || '#2E8C6F';
  document.getElementById('provider-sidebar-name').textContent = u.name;
  document.getElementById('provider-sidebar-role').textContent = `Provider · ${u.verified ? 'Verified ✓' : 'Verification pending'}`;
}

function portfolioGridHTML(photos) {
  if (!photos.length) return `<div style="color:var(--slate);font-size:14px;padding:8px 0;">No portfolio photos yet.</div>`;
  return `<div class="cats-grid">${photos.map(p => `
    <div style="position:relative;">
      <img src="${p.url}" alt="Portfolio photo" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px;display:block;"/>
      <button onclick="deletePortfolioPhoto('${p.id}')" title="Remove" style="position:absolute;top:6px;right:6px;background:rgba(18,22,31,.75);color:#fff;border:none;border-radius:50%;width:26px;height:26px;cursor:pointer;font-size:14px;line-height:1;">✕</button>
    </div>`).join('')}</div>`;
}

// Selecting a file no longer uploads it immediately — it shows a real
// preview first ("is this actually the right photo?") with an explicit
// Use / Choose Different step. Uploading instantly on selection, with no
// chance to double-check, is exactly how an unrelated screenshot ends up
// saved as a portfolio photo.
function selectPortfolioPhoto(file) {
  if (!file) return;
  // v80: any photo is fine here. It's shrunk and saved as JPEG before it's
  // sent (see prepareImageForUpload), so size is no longer a reason to refuse.
  if (!/^image\//.test(file.type || '')) return showToast('Please choose a photo');
  const reader = new FileReader();
  reader.onload = () => showPortfolioPhotoPreview(reader.result, file);
  reader.readAsDataURL(file);
}

function showPortfolioPhotoPreview(dataUrl, file) {
  const modalHtml = `
    <div class="modal-overlay open" id="portfolio-preview-overlay">
      <div class="modal" style="max-width:420px;">
        <div class="modal-header">
          <button class="modal-close" onclick="document.getElementById('portfolio-preview-overlay').remove()">✕</button>
          <h3>Use this photo?</h3>
          <p>Make sure it's a real photo of your completed work</p>
        </div>
        <div class="modal-body">
          <img src="${dataUrl}" alt="Preview of the completed-work photo you're about to add to your portfolio" style="width:100%;border-radius:10px;display:block;"/>
        </div>
        <div class="modal-footer" style="display:flex;gap:10px;">
          <button class="btn-sm btn-sm-outline" style="flex:1;" onclick="document.getElementById('portfolio-preview-overlay').remove();document.getElementById('portfolio-file-input').value='';">Choose Different</button>
          <button class="confirm-btn" style="flex:1;" id="portfolio-confirm-upload-btn" onclick="confirmPortfolioPhotoUpload()">Use This Photo</button>
        </div>
      </div>
    </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  window.__pendingPortfolioFile = file;
}

async function confirmPortfolioPhotoUpload() {
  const file = window.__pendingPortfolioFile;
  const btn = document.getElementById('portfolio-confirm-upload-btn');
  btn.disabled = true;
  btn.innerHTML = '<span class="btn-spinner" style="border-top-color:#fff;"></span>Uploading…';
  await uploadPortfolioPhoto(file);
  const overlay = document.getElementById('portfolio-preview-overlay');
  if (overlay) overlay.remove();
  window.__pendingPortfolioFile = null;
}

async function uploadPortfolioPhoto(file) {
  if (!file) return;
  if (!BACKEND_AVAILABLE) return showToast('Photo uploaded (demo mode — no backend detected)');

  const formData = new FormData();
  try {
    showToast('Uploading your photo…');
    formData.append('photo', await prepareImageForUpload(file)); // v80: shrunk first, so a phone photo is never "too large"
    const res = await fetch(API_BASE + '/portfolio/upload', {
      method: 'POST',
      headers: AUTH.token ? { 'Authorization': 'Bearer ' + AUTH.token } : {},
      body: formData, // deliberately no Content-Type header — the browser sets the correct multipart boundary itself
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Upload failed');
    showToast('Photo uploaded');
    providerData.portfolioPhotos = providerData.portfolioPhotos || [];
    providerData.portfolioPhotos.push(data.photo);
    document.getElementById('portfolio-grid-wrap').innerHTML = portfolioGridHTML(providerData.portfolioPhotos);
    document.getElementById('portfolio-file-input').value = '';
  } catch (e) {
    showToast(e.message || 'Could not upload photo');
  }
}

async function deletePortfolioPhoto(id) {
  if (!BACKEND_AVAILABLE) return showToast('Photo removed (demo mode)');
  if (!(await confirmDialog('Remove this portfolio photo?', {danger: true, confirmLabel: 'Remove'}))) return;
  try {
    await apiFetch('DELETE', `/portfolio/${id}`);
    providerData.portfolioPhotos = (providerData.portfolioPhotos || []).filter(p => p.id !== id);
    document.getElementById('portfolio-grid-wrap').innerHTML = portfolioGridHTML(providerData.portfolioPhotos);
    showToast('Photo removed');
  } catch (e) { showToast(e.message || 'Could not remove photo'); }
}

async function uploadProfilePhoto(file) {
  if (!file) return;
  if (!BACKEND_AVAILABLE) return showToast('Profile photo updated (demo mode — no backend detected)');

  const formData = new FormData();
  try {
    showToast('Uploading your photo…');
    formData.append('photo', await prepareImageForUpload(file, { maxSide: 1200 })); // v80
    const res = await fetch(API_BASE + '/profile-photo/upload', {
      method: 'POST',
      headers: AUTH.token ? { 'Authorization': 'Bearer ' + AUTH.token } : {},
      body: formData,
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Upload failed');
    AUTH.user.profilePhotoUrl = data.profilePhotoUrl;
    showToast('Profile photo updated');
    // Re-render Settings so the new photo shows immediately, without a
    // page reload — and re-render the navbar avatar too if one exists.
    if (AUTH.user.role === 'provider') selectProviderSection('settings');
    else if (AUTH.user.role === 'customer') selectCustomerSection('settings');
  } catch (e) {
    showToast(e.message || 'Could not upload photo');
  }
}

async function removeProfilePhoto() {
  if (!BACKEND_AVAILABLE) { AUTH.user.profilePhotoUrl = null; showToast('Profile photo removed (demo mode)'); return; }
  if (!(await confirmDialog('Remove your profile photo? This reverts to your initials.', {danger: true, confirmLabel: 'Remove'}))) return;
  try {
    await apiFetch('DELETE', '/profile-photo');
    AUTH.user.profilePhotoUrl = null;
    showToast('Profile photo removed');
    if (AUTH.user.role === 'provider') selectProviderSection('settings');
    else if (AUTH.user.role === 'customer') selectCustomerSection('settings');
  } catch (e) { showToast(e.message || 'Could not remove photo'); }
}

async function initProviderDash() { await loadProviderData(); updateProviderSidebar(); selectProviderSection('overview'); }

