// No made-up records. These used to hold invented users, disputes, cities
// and dollar amounts that stayed on screen for any admin whose role isn't
// allowed to load that section (or whenever a request failed) — an admin
// could not tell them apart from real data. Empty means "nothing loaded".
const FALLBACK_PENDING_USERS = [];
const FALLBACK_VERIFICATION_QUEUE = [];
const FALLBACK_DISPUTES = [];
const FALLBACK_CATEGORIES = [];
const FALLBACK_COUNTRIES = [];
const FALLBACK_CITIES = [];

let adminData = {
  stats: { totalUsers: 0, pendingApprovals: 0, openDisputes: 0, gmv: 0, region: null },
  pendingUsers: FALLBACK_PENDING_USERS, verificationQueue: FALLBACK_VERIFICATION_QUEUE,
  disputes: FALLBACK_DISPUTES, categories: FALLBACK_CATEGORIES, countries: FALLBACK_COUNTRIES,
  cities: FALLBACK_CITIES, subAdmins: [], people: [], categoryRequests: [], transactions: [], fraudFlags: [], advertisingInquiries: [], salesInquiries: [], planPricing: null, membershipPricing: null, exchangeRates: [], reportsAnalytics: null, organizations: [], bookingWindowTiers: null, supportContact: null, homepageContent: null, homepageImages: null, categoryImages: null, aboutUsContent: null, termsOfServiceCustomerContent: null, termsOfServiceProviderContent: null, footerInfo: null, financialByRegion: { regions: [], total: { held: 0, released: 0, commissionRevenue: 0, transactionCount: 0 } },
  escrow: { held: 0, released: 0 },
};

async function loadAdminData() {
  if (!BACKEND_AVAILABLE) return;

  // Each call is fetched independently rather than as one all-or-nothing
  // Promise.all — a regular regional admin (or a department-scoped admin)
  // is expected to be denied access to some of these by design, and that
  // must not silently wipe out every OTHER section's real data. Each
  // result is applied on its own if it succeeded, and quietly left alone
  // (keeping whatever was there before) if that specific call wasn't
  // permitted for this account.
  async function tryFetch(path) {
    try { return await apiFetch('GET', path); }
    catch (e) { return null; }
  }

  const [stats, pending, allPeople, verQueue, disputes, cats, countries, escrow, catRequests, transactions, fraudFlags, financialByRegion, planPricing, membershipPricing, advertisingInquiries, reportsAnalytics, salesInquiries, organizations, careersInquiries, accessLogs, referralsOverview, contactSubmissions] = await Promise.all([
    tryFetch('/admin/stats'),
    tryFetch('/admin/users/pending'),
    tryFetch('/admin/users/all'),
    tryFetch('/admin/verification-queue'),
    tryFetch('/admin/disputes'),
    tryFetch('/admin/categories'),
    tryFetch('/admin/countries'),
    tryFetch('/escrow/summary'),
    tryFetch('/admin/category-requests'),
    tryFetch('/admin/transactions'),
    tryFetch('/admin/fraud-flags'),
    tryFetch('/admin/financial-by-region'),
    tryFetch('/admin/plan-pricing'),
    tryFetch('/admin/settings/membership-pricing'),
    tryFetch('/admin/advertising-inquiries'),
    tryFetch('/admin/reports/analytics'),
    tryFetch('/admin/sales-inquiries'),
    tryFetch('/admin/organizations'),
    tryFetch('/admin/careers-inquiries'),
    tryFetch('/admin/access-logs'),
    tryFetch('/admin/referrals-overview'),
    tryFetch('/admin/contact-submissions'),
  ]);

  if (stats) adminData.stats = stats;
  if (pending) adminData.pendingUsers = pending.users.map(u => ({ id: u.id, name: u.name, role: u.role[0].toUpperCase() + u.role.slice(1), country: u.country, city: u.city, submitted: (u.createdAt || '').slice(0, 10), status: 'pending', idStatus: u.idStatus || 'none' }));
  if (allPeople) adminData.people = allPeople.users.map(u => ({ ...u, role: u.role[0].toUpperCase() + u.role.slice(1), active: u.active !== false }));
  if (verQueue) adminData.verificationMeta = { storage: verQueue.storage || null, retentionDays: verQueue.retentionDays, automatedCheckConnected: !!verQueue.automatedCheckConnected };
  adminData.verificationQueueBlocked = !verQueue; // v107: this account isn't allowed to open the queue
  if (verQueue) adminData.verificationQueue = verQueue.queue.map(v => ({ id: v.id, name: v.userName, role: v.role, doc: v.docType, country: v.country, city: v.city, status: v.status, reviewDeadline: v.reviewDeadline, idLegalName: v.idLegalName || null, nameMatch: v.nameMatch, hasDocument: !!v.hasDocument, hasSelfie: !!v.hasSelfie, hasBack: !!v.hasBack, source: v.source || 'upload', createdAt: v.createdAt }));
  if (disputes) adminData.disputes = disputes.disputes.map(d => ({ id: d.id, parties: d.parties, reason: d.reason, amount: d.amount, status: d.status, createdAt: d.createdAt }));
  if (cats) adminData.categories = cats.categories.map(c => ({ id: c.id, name: c.name, pros: c.pros, active: c.active, responseWindowOverrideHours: c.responseWindowOverrideHours }));
  if (countries) adminData.countries = countries.countries.map(c => ({ id: c.id, name: c.name, status: c.status }));
  if (escrow) adminData.escrow = escrow;
  if (catRequests) adminData.categoryRequests = catRequests.requests;
  if (transactions) { adminData.transactions = transactions.transactions; currentAdminTransactions = transactions.transactions; }
  if (fraudFlags) adminData.fraudFlags = fraudFlags.flags;
  if (financialByRegion) adminData.financialByRegion = financialByRegion;
  if (planPricing) adminData.planPricing = planPricing;
  if (membershipPricing) adminData.membershipPricing = membershipPricing.tiers;
  if (advertisingInquiries) { adminData.advertisingInquiries = advertisingInquiries.inquiries; adminData.adDefaultRunDays = advertisingInquiries.defaultRunDays || 30; }
  if (reportsAnalytics) adminData.reportsAnalytics = reportsAnalytics;
  if (salesInquiries) adminData.salesInquiries = salesInquiries.inquiries;
  if (organizations) adminData.organizations = organizations.organizations;
  if (careersInquiries) adminData.careersInquiries = careersInquiries.inquiries;
  if (contactSubmissions) adminData.contactSubmissions = contactSubmissions.submissions;
  if (accessLogs) adminData.accessLogs = accessLogs.logs;
  if (referralsOverview) adminData.referralsOverview = referralsOverview;

  // A genuine live check, not a hardcoded "everything's fine" badge — this
  // hits the real /api/health endpoint right now and times it.
  try {
    const start = performance.now();
    const healthRes = await fetch(API_BASE + '/health');
    adminData.apiHealth = { ok: healthRes.ok, ms: Math.round(performance.now() - start) };
  } catch (e) {
    adminData.apiHealth = { ok: false, ms: null };
  }

  if (AUTH.user && AUTH.user.isSuperAdmin) {
    const [cities, subAdmins, exchangeRates, bookingWindow, supportContact, homepageContent, homepageImages, categoryImages, aboutUsContent, termsCustomerContent, termsProviderContent, footerInfo] = await Promise.all([
      tryFetch('/admin/cities'),
      tryFetch('/admin/sub-admins'),
      tryFetch('/admin/exchange-rates'),
      tryFetch('/admin/settings/booking-window'),
      tryFetch('/admin/settings/support-contact'),
      tryFetch('/admin/settings/homepage-content'),
      tryFetch('/homepage-images'),
      tryFetch('/admin/category-images'),
      tryFetch('/admin/settings/about-us'),
      tryFetch('/admin/settings/terms-of-service-customer'),
      tryFetch('/admin/settings/terms-of-service-provider'),
      tryFetch('/admin/settings/footer'),
    ]);
    if (cities) adminData.cities = cities.cities;
    if (subAdmins) adminData.subAdmins = subAdmins.admins;
    if (exchangeRates) adminData.exchangeRates = exchangeRates.rates;
    if (bookingWindow) adminData.bookingWindowTiers = bookingWindow.tiers;
    if (supportContact) { adminData.supportContact = supportContact; adminData.allRegionalContacts = supportContact.allRegional || []; }
    if (homepageContent) adminData.homepageContent = homepageContent;
    if (homepageImages) adminData.homepageImages = homepageImages;
    if (categoryImages) adminData.categoryImages = categoryImages;
    if (aboutUsContent) adminData.aboutUsContent = aboutUsContent.content;
  if (footerInfo) adminData.footerInfo = footerInfo.footer;
    if (termsCustomerContent) adminData.termsOfServiceCustomerContent = termsCustomerContent.content;
    if (termsProviderContent) adminData.termsOfServiceProviderContent = termsProviderContent.content;
  } else if (AUTH.user && AUTH.user.role === 'admin' && !AUTH.user.isSuperAdmin && !AUTH.user.adminDepartment) {
    const supportContact = await tryFetch('/admin/settings/support-contact');
    if (supportContact) adminData.supportContact = supportContact;
  }
}

async function adminDecide(listName, id, decision, sectionKey) {
  let rejectionReason = null;
  if (decision === 'reject') {
    // Real fix for a live bug: the backend for both flows requires a
    // typed reason on rejection (so the person actually knows what to
    // fix), but nothing here ever collected or sent one — every reject
    // click was failing. Now actually asks for it.
    rejectionReason = await confirmDialog(
      listName === 'users'
        ? 'Reject this account application? This will permanently block them from logging in — this is not the same as leaving them pending, and is harder to casually undo. Type the reason they\'re being rejected — they\'ll see this.'
        : 'Reject this verification submission? Type the reason — the applicant will see this and can resubmit.',
      { danger: true, confirmLabel: 'Reject', requireTextInput: true }
    );
    if (rejectionReason === null) return; // cancelled
  }
  if (!BACKEND_AVAILABLE) {
    const list = listName === 'users' ? adminData.pendingUsers : adminData.verificationQueue;
    const item = list.find(x => x.id === id);
    if (!item) return;
    item.status = decision === 'approve' ? 'approved' : 'rejected';
    showToast(`${item.name} ${decision === 'approve' ? 'approved' : 'rejected'}`);
    return selectAdminSection(sectionKey);
  }
  try {
    const payload = decision === 'reject' ? { decision, rejectionReason } : { decision };
    let decided = null;
    if (listName === 'users') decided = await apiFetch('POST', `/admin/users/${id}/decide`, payload);
    else await apiFetch('POST', `/admin/verification/${id}/decide`, payload);
    // v107: an approved account is not a verified person. Say what is still needed.
    if (listName === 'users' && decision === 'approve' && decided && decided.needsId) {
      await confirmDialog(decided.idStatus === 'waiting'
        ? 'Account approved. This person is still Unverified: their ID is waiting in the Verification Queue. Approve it there and they become Verified.'
        : 'Account approved. This person is still Unverified because they have not uploaded an ID yet. They have been told to do it in their Verification section. They become Verified when that ID is approved in the Verification Queue.',
        { confirmLabel: decided.idStatus === 'waiting' ? 'OK' : 'OK' });
      await loadAdminData();
      return selectAdminSection(decided.idStatus === 'waiting' ? 'verification' : sectionKey);
    }
    showToast(listName === 'users' ? `Account ${decision === 'approve' ? 'approved' : 'rejected'}` : (decision === 'approve' ? 'ID approved. This person is now Verified.' : 'ID rejected. They have been told why.'));
    await loadAdminData();
    selectAdminSection(sectionKey);
  } catch (e) { showToast(e.message || 'Could not update'); }
}

// v96: split a disputed payment: part back to the customer, the rest to the pro.
function openSplitDispute(id, amountText) {
  const total = parseFloat(String(amountText || '').replace(/[^0-9.]/g, '')) || 0;
  const old = document.getElementById('split-dispute-overlay'); if (old) old.remove();
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-overlay open" id="split-dispute-overlay" style="z-index:5300;"><div class="modal" style="max-width:460px;" role="dialog" aria-modal="true">
    <div class="modal-header"><h3>Split the payment</h3><p>${total ? 'The held payment is $' + total.toFixed(2) + '.' : ''} Enter how much goes back to the customer. The rest is released to the pro.</p></div>
    <div class="modal-body">
      <div class="form-group"><label class="form-label" for="split-refund">Refund to the customer ($)</label>
        <input class="form-input" type="number" id="split-refund" min="0.01" step="0.01" ${total ? 'max="' + (total - 0.01).toFixed(2) + '"' : ''} oninput="updateSplitPreview(${total})"/></div>
      <div id="split-preview" class="ver-note" style="margin:-4px 0 12px;"></div>
      <div class="form-group" style="margin-bottom:0;"><label class="form-label" for="split-note">Note both sides will see</label>
        <textarea class="form-input" id="split-note" rows="3" maxlength="500" placeholder="Why the payment is being split this way"></textarea></div>
    </div>
    <div class="modal-footer" style="display:flex;gap:10px;">
      <button class="btn-sm btn-sm-outline" style="flex:1;" onclick="document.getElementById('split-dispute-overlay').remove()">Cancel</button>
      <button class="confirm-btn" style="flex:1;" id="split-confirm-btn" onclick="confirmSplitDispute(${jsArg(id)})">Split the payment</button>
    </div></div></div>`);
}
function updateSplitPreview(total) {
  const el = document.getElementById('split-preview'); if (!el) return;
  const x = parseFloat(document.getElementById('split-refund').value);
  if (!total || !Number.isFinite(x) || x <= 0) { el.textContent = ''; return; }
  el.textContent = x >= total ? 'That is the whole payment. Use "Refund Customer" for a full refund.' : `Customer gets $${x.toFixed(2)} back. Pro gets $${(total - x).toFixed(2)}, before commission.`;
}
async function confirmSplitDispute(id) {
  const refundAmount = parseFloat(document.getElementById('split-refund').value);
  const note = document.getElementById('split-note').value.trim();
  if (!Number.isFinite(refundAmount) || refundAmount <= 0) return showToast('Enter the amount to refund to the customer');
  if (note.length < 3) return showToast('Add a short note explaining the split');
  const btn = document.getElementById('split-confirm-btn'); btn.disabled = true;
  try {
    await apiFetch('POST', `/admin/disputes/${id}/resolve`, { decision: 'split', refundAmount, note });
    document.getElementById('split-dispute-overlay').remove();
    showToast('Dispute resolved with a split');
    await loadAdminData(); selectAdminSection('disputes');
  } catch (e) { btn.disabled = false; showToast(e.message || 'Could not split this payment'); }
}

async function resolveDispute(id, decision) {
  const note = await confirmDialog(
    decision === 'refund_customer'
      ? 'Refund the customer for this dispute? Type a short note explaining the decision — both the customer and provider will see it.'
      : 'Release escrow to the provider for this dispute? Type a short note explaining the decision — both parties will see it.',
    { confirmLabel: decision === 'refund_customer' ? 'Refund Customer' : 'Release to Provider', requireTextInput: true }
  );
  if (note === null) return; // cancelled
  if (!BACKEND_AVAILABLE) {
    const d = adminData.disputes.find(x => x.id === id);
    if (!d) return;
    d.status = 'resolved';
    showToast(decision === 'refund_customer' ? `Dispute ${id} marked resolved — customer refunded` : `Dispute ${id} marked resolved — escrow released`);
    return selectAdminSection('disputes');
  }
  try {
    await apiFetch('POST', `/admin/disputes/${id}/resolve`, { decision, note });
    showToast(decision === 'refund_customer' ? `Dispute ${id} marked resolved — customer refunded` : `Dispute ${id} marked resolved — escrow released`);
    await loadAdminData();
    selectAdminSection('disputes');
  } catch (e) { showToast(e.message || 'Could not resolve dispute'); }
}

