// Item 13 / Data Management & Cleanup — preview-then-execute, with a
// typed confirmation phrase as the real safety gate (see
// POST /admin/data-cleanup/execute in admin.routes.js for why: this is
// permanent deletion, so a checkbox isn't enough friction for it).
let lastCleanupPreviewCountry = null;
let lastCleanupPreviewDone = false; // separate from the country value itself, since "all countries" is a real, valid target (country: null) distinct from "nothing previewed yet"

async function previewDataCleanup() {
  // Item: Walter's real, explicit need before going live — clearing test
  // data across every country at once, not one at a time. Leaving the
  // country field blank now means exactly that; typing a specific
  // country still scopes it the same way as before.
  const countryInput = document.getElementById('cleanup-country-input').value.trim();
  const country = countryInput || null;
  const target = document.getElementById('data-cleanup-preview-panel');
  if (!BACKEND_AVAILABLE) { target.innerHTML = '<div style="color:var(--slate);font-size:13.5px;">Preview unavailable in demo mode.</div>'; return; }
  try {
    const result = await apiFetch('POST', '/admin/data-cleanup/preview', { country });
    lastCleanupPreviewCountry = country;
    lastCleanupPreviewDone = true;
    const scopeLabel = country ? escapeHtml(country) : 'every country';
    const expectedPhrase = country ? `DELETE TEST DATA FOR ${country.toUpperCase()}` : 'DELETE ALL TEST DATA';
    if (!result.accountsEligible.length) {
      target.innerHTML = `<div style="color:var(--slate);font-size:13.5px;">No untouched test accounts found under ${scopeLabel} — nothing eligible to clear. Any account there has real contract, payment, or dispute history and won't be touched by this tool.</div>`;
      return;
    }
    target.innerHTML = `
      <div style="font-size:13.5px;color:var(--navy);margin-bottom:8px;"><strong>${result.accountsEligible.length} account${result.accountsEligible.length === 1 ? '' : 's'}</strong> eligible for removal under ${scopeLabel}, plus related match/notification/verification/photo records for whichever ones you select below. None of these have ever had a real contract, payment, or dispute.</div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <span style="font-size:13px;color:var(--slate);">Select which accounts to remove — all selected by default</span>
        <span><a onclick="toggleAllCleanupSelections(true)" style="font-size:13px;cursor:pointer;color:var(--navy);font-weight:600;">Select all</a> · <a onclick="toggleAllCleanupSelections(false)" style="font-size:13px;cursor:pointer;color:var(--navy);font-weight:600;">Select none</a></span>
      </div>
      <div style="max-height:220px;overflow-y:auto;font-size:13px;color:var(--slate);border:1px solid var(--border);border-radius:6px;padding:8px;margin-bottom:10px;">
        ${result.accountsEligible.map(a => `<label style="display:flex;align-items:center;gap:8px;padding:4px 0;cursor:pointer;">
          <input type="checkbox" class="cleanup-account-checkbox" data-account-id="${a.id}" checked onchange="updateCleanupSelectionCount()"/>
          <span>${escapeHtml(a.name)} (${escapeHtml(a.email)}) — ${escapeHtml(a.role)}</span>
        </label>`).join('')}
      </div>
      <div class="form-group"><label class="form-label">Type <code>${expectedPhrase}</code> to confirm</label><input class="form-input" id="cleanup-confirm-input" placeholder="${escapeHtml(expectedPhrase)}"/></div>
      <button class="btn-sm" style="background:#C1554D;color:#fff;" id="cleanup-execute-btn" onclick="executeDataCleanup()">Permanently delete these ${result.accountsEligible.length} test accounts</button>`;
  } catch (e) { target.innerHTML = `<div style="color:#C1554D;font-size:13.5px;">${escapeHtml(e.message || 'Could not load preview')}</div>`; }
}

// Keeps the delete button's label honest about exactly how many accounts
// are actually currently selected, not the original preview total — so
// it's never possible to misread "delete 12" and get 3, or vice versa.
function updateCleanupSelectionCount() {
  const checked = document.querySelectorAll('.cleanup-account-checkbox:checked').length;
  const btn = document.getElementById('cleanup-execute-btn');
  if (!btn) return;
  btn.textContent = checked === 0 ? 'Select at least one account to delete' : `Permanently delete ${checked} selected test account${checked === 1 ? '' : 's'}`;
  btn.disabled = checked === 0;
  btn.style.opacity = checked === 0 ? '0.5' : '1';
  btn.style.cursor = checked === 0 ? 'not-allowed' : 'pointer';
}

function toggleAllCleanupSelections(checked) {
  document.querySelectorAll('.cleanup-account-checkbox').forEach(cb => { cb.checked = checked; });
  updateCleanupSelectionCount();
}

async function executeDataCleanup() {
  const confirmPhrase = document.getElementById('cleanup-confirm-input').value.trim();
  if (!lastCleanupPreviewDone) return showToast('Preview first');
  const accountIds = Array.from(document.querySelectorAll('.cleanup-account-checkbox:checked')).map(cb => cb.dataset.accountId);
  if (!accountIds.length) return showToast('Select at least one account first');
  try {
    const { deleted } = await apiFetch('POST', '/admin/data-cleanup/execute', { country: lastCleanupPreviewCountry, confirmPhrase, accountIds });
    showToast(`Removed ${deleted.accounts} test account${deleted.accounts === 1 ? '' : 's'} and related records`);
    document.getElementById('data-cleanup-preview-panel').innerHTML = '';
    loadDataCleanupLogPanel();
  } catch (e) { showToast(e.message || 'Could not complete cleanup'); }
}

// ---- Go-Live screen (backend: /admin/go-live/* in admin.routes.js) ----
async function loadGoLivePanel() {
  const box = document.getElementById('golive-checklist');
  if (!box) return;
  try {
    const r = await apiFetch('GET', '/admin/go-live/status');
    const sevLabel = { required: 'Required', recommended: 'Recommended', optional: 'Optional', business: 'Business step' };
    box.innerHTML = `<div style="font-size:13.5px;margin-bottom:10px;">${r.counts.realAccounts} real account(s) · ${r.counts.demoAccounts} demo account(s)</div>` +
      r.items.map(i => `
      <div style="display:flex;gap:10px;align-items:flex-start;padding:9px 0;border-top:1px solid var(--border);">
        <div style="font-size:16px;line-height:1.2;">${i.ok ? '✅' : (i.severity === 'required' ? '❌' : '⚪')}</div>
        <div style="flex:1;">
          <div style="font-weight:600;font-size:14px;">${escapeHtml(i.label)} <span class="badge badge-neutral" style="margin-left:6px;">${sevLabel[i.severity] || ''}</span></div>
          <div style="font-size:13px;color:var(--slate);margin-top:2px;">${escapeHtml(i.detail || '')}</div>
        </div>
      </div>`).join('');
  } catch (e) { box.textContent = (e && e.message) || 'Could not load the checklist.'; }
  const logBox = document.getElementById('golive-log');
  if (logBox) {
    try {
      const { log } = await apiFetch('GET', '/admin/go-live/audit-log');
      logBox.innerHTML = log.length ? log.map(l => `<div style="font-size:13.5px;padding:6px 0;border-top:1px solid var(--border);">${new Date(l.createdAt).toLocaleString()} — <strong>${escapeHtml(l.actorName)}</strong>: ${l.action === 'create_super_admin' ? `created super admin ${escapeHtml((l.target && l.target.email) || '')}` : l.action === 'set_live_countries' ? `set live countries: ${escapeHtml(((l.target && l.target.live) || []).join(', '))}` : `removed ${(l.counts && l.counts.accounts) || 0} demo account(s) and their records`}</div>`).join('')
        : '<div style="color:var(--slate);font-size:13.5px;">Nothing yet.</div>';
    } catch (e) { logBox.textContent = ''; }
  }
}
