async function handlePromoImageSelect(event) {
  const file = event.target.files[0];
  event.target.value = '';
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) return showToast('Image must be under 5MB');
  document.getElementById('promo-image-name').textContent = 'Uploading…';
  if (!BACKEND_AVAILABLE) {
    document.getElementById('promo-image-name').textContent = file.name + ' (demo mode)';
    return;
  }
  try {
    const formData = new FormData();
    formData.append('image', file);
    const res = await fetch(API_BASE + '/admin/promotions/image', {
      method: 'POST',
      headers: AUTH.token ? { 'Authorization': 'Bearer ' + AUTH.token } : {},
      body: formData,
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Upload failed');
    document.getElementById('promo-image-url').value = data.url;
    document.getElementById('promo-image-name').textContent = file.name;
  } catch (e) {
    showToast(e.message || 'Could not upload image');
    document.getElementById('promo-image-name').textContent = 'No image chosen';
  }
}

async function submitPromotion() {
  const title = document.getElementById('promo-title').value.trim();
  const message = document.getElementById('promo-message').value.trim();
  const audience = document.getElementById('promo-audience').value;
  const imageUrl = document.getElementById('promo-image-url').value.trim();
  const sendEmailChecked = document.getElementById('promo-send-email').checked;
  const regionInput = document.getElementById('promo-region');
  const region = regionInput ? regionInput.value.trim() : '';
  if (!title || title.length < 2) return showToast('Enter a short title');
  if (!message || message.length < 5) return showToast('Enter the promotion message');
  if (!BACKEND_AVAILABLE) return showToast('Promotion posted (demo mode)');
  try {
    const result = await apiFetch('POST', '/admin/promotions', { title, message, audience, imageUrl: imageUrl || undefined, region: region || undefined, sendEmail: sendEmailChecked });
    if (sendEmailChecked && result.emailConfigured === false) {
      showToast('Promotion posted — email not sent (no email provider connected yet)');
    } else if (sendEmailChecked) {
      showToast(`Promotion posted — emailed to ${result.promotion.emailSentCount} people`);
    } else {
      showToast('Promotion posted');
    }
    document.getElementById('promo-title').value = '';
    document.getElementById('promo-message').value = '';
    document.getElementById('promo-image-url').value = '';
    document.getElementById('promo-image-name').textContent = 'No image chosen';
    document.getElementById('promo-send-email').checked = false;
    if (regionInput) regionInput.value = '';
    document.getElementById('new-promotion-panel').style.display = 'none';
    await loadAdminPromotionsPanel();
  } catch (e) { showToast(e.message || 'Could not post promotion'); }
}

