function tierBadgeHTML(plan, superProEligibleSince) {
  const p = plan || 'starter';
  if (p === 'superpro') return '<span class="badge badge-success">★ Super-Pro</span>';
  if (superProEligibleSince) return `<span class="badge badge-warn">${p === 'pro' ? 'Pro' : 'Starter'} · Super-Pro ready</span>`;
  if (p === 'pro') return '<span class="badge badge-pending">Pro</span>';
  return '<span class="badge badge-neutral">Starter</span>';
}

