// ── v83: MY DATA, AND CLOSING MY ACCOUNT ───────────────────────────────
function loadMyDataPanel(mainId) {
  const main = document.getElementById(mainId);
  if (!main || !BACKEND_AVAILABLE || !AUTH.user) return;
  const old = document.getElementById('my-data-panel'); if (old) old.remove();
  main.insertAdjacentHTML('beforeend', `<div class="panel" id="my-data-panel">
    <div class="panel-title">${escapeHtml(tr("Your data and your account"))}</div>
    <div style="font-size:14px;line-height:1.6;color:var(--text);margin-bottom:12px;">${escapeHtml(tr("You can download a copy of everything Trothen holds about your account: your profile, bookings, payments, messages, reviews and identity-check records."))}</div>
    <button class="btn-sm btn-sm-outline" id="my-data-download-btn" onclick="downloadMyData()">${escapeHtml(tr("Download my data"))}</button>
    <div style="border-top:1px solid var(--border);margin:18px 0 14px;"></div>
    <div style="font-size:14px;line-height:1.6;color:var(--text);margin-bottom:12px;"><strong>${escapeHtml(tr("Close my account."))}</strong> ${escapeHtml(tr("Your account stops working straight away and you're signed out everywhere. Records of past bookings and payments are kept, because the other person in each one has a right to them and money records have to be kept. Your personal details are then removed by our team."))}</div>
    <button class="btn-sm btn-sm-ghost" style="color:#A5352B;" onclick="startCloseAccount()">${escapeHtml(tr("Close my account"))}</button>
  </div>`);
}
async function downloadMyData() {
  const btn = document.getElementById('my-data-download-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Preparing…'; }
  try {
    const res = await fetch(API_BASE + '/auth/me/export', { headers: { Authorization: 'Bearer ' + AUTH.token } });
    if (!res.ok) { const d = await res.json().catch(() => ({})); throw new Error(d.error || 'Could not prepare your data'); }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'trothen-my-data-' + new Date().toISOString().slice(0, 10) + '.json';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 5000);
    showToast('Your data has been downloaded');
  } catch (e) { showToast(e.message || 'Could not prepare your data'); }
  if (btn) { btn.disabled = false; btn.textContent = tr('Download my data'); }
}
async function startCloseAccount() {
  let blockers = [];
  try { blockers = (await apiFetch('GET', '/auth/me/close-account/check')).blockers || []; } catch (e) { return showToast(e.message || 'Could not check your account'); }
  const usesGoogle = !!(AUTH.user && AUTH.user.googleId);
  const body = blockers.length
    ? `<p style="margin:0 0 10px;">${escapeHtml(tr("Your account can't be closed just yet:"))}</p><ul style="margin:0 0 4px 18px;line-height:1.6;">${blockers.map(b => `<li>${escapeHtml(b)}</li>`).join('')}</ul>`
    : `<p style="margin:0 0 12px;line-height:1.6;">${escapeHtml(tr("This closes your account now. You'll be signed out everywhere and won't be able to sign back in. If you change your mind, contact support before your details are removed."))}</p>
       <div class="form-group"><label class="form-label">${escapeHtml(tr(usesGoogle ? 'Your password, or type CLOSE' : 'Your password'))}</label><input class="form-input" type="${usesGoogle ? 'text' : 'password'}" id="close-account-password" autocomplete="current-password"/></div>
       <div class="form-group" style="margin-bottom:0;"><label class="form-label">${escapeHtml(tr("Why are you leaving?"))} <span style="font-weight:400;color:var(--slate);">${escapeHtml(tr("(optional)"))}</span></label><textarea class="form-input" id="close-account-reason" rows="2" maxlength="500"></textarea></div>`;
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-overlay open" id="close-account-overlay" style="z-index:5200;"><div class="modal" style="max-width:460px;" role="dialog" aria-modal="true">
    <div class="modal-header"><h3>${escapeHtml(tr("Close my account"))}</h3></div>
    <div class="modal-body" style="font-size:14px;">${body}</div>
    <div class="modal-footer" style="display:flex;gap:10px;">
      <button class="btn-sm btn-sm-outline" style="flex:1;" onclick="document.getElementById('close-account-overlay').remove()">${blockers.length ? 'OK' : escapeHtml(tr('Keep my account'))}</button>
      ${blockers.length ? '' : '<button class="confirm-btn" style="flex:1;background:#A5352B;" id="close-account-confirm-btn" onclick="confirmCloseAccount()">' + escapeHtml(tr('Close my account')) + '</button>'}
    </div></div></div>`);
}
async function confirmCloseAccount() {
  const entry = document.getElementById('close-account-password').value;
  const reason = document.getElementById('close-account-reason').value;
  if (!entry) return showToast('Enter your password to confirm');
  const btn = document.getElementById('close-account-confirm-btn');
  btn.disabled = true; btn.textContent = 'Closing…';
  try {
    await apiFetch('POST', '/auth/me/close-account', { password: entry, confirm: entry, reason });
    document.getElementById('close-account-overlay').remove();
    showToast('Your account has been closed.');
    setTimeout(() => { try { clearAuthSession(); } catch (e) {} location.href = '/'; }, 1500);
  } catch (e) {
    btn.disabled = false; btn.textContent = tr('Close my account');
    showToast(e.message || 'Could not close your account');
  }
}

// Admin → People (super admin): accounts their owners closed.
async function loadAccountClosuresPanel() {
  const main = document.getElementById('admin-main');
  if (!main || !BACKEND_AVAILABLE || !(AUTH.user && AUTH.user.isSuperAdmin)) return;
  let d; try { d = await apiFetch('GET', '/admin/account-closures'); } catch (e) { return; }
  const old = document.getElementById('account-closures-panel'); if (old) old.remove();
  const badge = (s) => s === 'erased' ? '<span class="badge badge-neutral">Details erased</span>' : s === 'reopened' ? '<span class="badge badge-success">Reopened</span>' : '<span class="badge badge-warn">Closed, details still held</span>';
  const rows = d.closures.map(c => `<tr><td><strong>${escapeHtml(c.name)}</strong>${c.email ? `<div class="ver-note">${escapeHtml(c.email)}</div>` : ''}</td><td>${escapeHtml(c.role === 'provider' ? 'Pro' : 'Customer')}</td><td>${escapeHtml(String(c.requestedAt).slice(0, 10))}<div class="ver-note">${c.daysSinceClosed} day${c.daysSinceClosed === 1 ? '' : 's'} ago</div></td><td>${escapeHtml(c.reason || '—')}</td><td>${badge(c.status)}</td>
    <td class="row-actions">${c.status === 'closed' ? `<button class="btn-sm btn-sm-outline" onclick="reopenClosedAccount('${escapeHtml(c.id)}')">Reopen</button><button class="btn-sm btn-sm-ghost" style="color:#A5352B;" onclick="eraseClosedAccount(${jsArg(c.id)}, ${jsArg(c.name)})">Erase details</button>` : '—'}</td></tr>`).join('');
  main.insertAdjacentHTML('beforeend', `<div class="panel" id="account-closures-panel">
    <div class="panel-title">Accounts closed by their owners <small>${d.closures.filter(c => c.status === 'closed').length} waiting for a decision</small></div>
    <div style="font-size:14px;line-height:1.6;color:var(--text);margin-bottom:10px;">A closed account can't sign in and isn't shown anywhere. <strong>Erase details</strong> permanently removes the person's name, contact details, photos and ID files. Their bookings, payments, reviews and disputes stay on record, shown as "Closed account". Nothing is erased automatically; how long to wait is a decision for me and the attorney.</div>
    ${rows ? `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Type</th><th>Closed</th><th>Reason given</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div>` : '<div class="ver-note">No one has closed their account.</div>'}
  </div>`);
}
async function reopenClosedAccount(id) {
  const ok = await confirmDialog('Reopen this account? The person will be able to sign in again.', { confirmLabel: 'Reopen' });
  if (!ok) return;
  try { await apiFetch('POST', '/admin/account-closures/' + encodeURIComponent(id) + '/reopen'); showToast('Account reopened'); loadAccountClosuresPanel(); }
  catch (e) { showToast(e.message || 'Could not reopen'); }
}
async function eraseClosedAccount(id, name) {
  const ok = await confirmDialog(`Erase the personal details of ${name}? Their name, email, phone, address, photos and ID files are removed for good and the account can never be reopened. Records of their bookings and payments are kept.`, { confirmLabel: 'Erase for good', danger: true });
  if (!ok) return;
  try { await apiFetch('POST', '/admin/account-closures/' + encodeURIComponent(id) + '/erase'); showToast('Personal details erased'); loadAccountClosuresPanel(); }
  catch (e) { showToast(e.message || 'Could not erase'); }
}

