// v95: what visitors are told to write to, and whether it looks right.
async function loadContactCheck() {
  const box = document.getElementById('contact-check-box');
  if (!box) return;
  let d; try { d = await apiFetch('GET', '/admin/settings/contact-check'); } catch (e) { return; }
  const tone = (l) => l === 'problem' ? 'background:#FBEAE8;border:1px solid #E3B4AE;color:#8A2D25;' : 'background:#FBF3E4;border:1px solid #E9D6A8;color:#5C4A12;';
  box.innerHTML = `<div style="font-size:14px;line-height:1.6;padding:10px 12px;border:1px solid var(--border);border-radius:8px;">
    <div><strong>Contact address visitors see:</strong> ${d.email ? escapeHtml(d.email) : '<em>none set</em>'}</div>
    <div class="ver-note" style="margin-top:2px;">One address, used in ${d.usedIn.map(escapeHtml).join(', ')}. Change it in the Footer settings above (Support email).</div>
    <div class="ver-note" style="margin-top:2px;">ID files: ${d.retentionDays > 0 ? 'deleted ' + d.retentionDays + ' days after a decision' : 'kept until deleted by hand'}. Change it in Verification Queue → How ID files are kept.</div>
    ${d.advice.map(a => `<div style="margin-top:8px;padding:8px 10px;border-radius:8px;font-size:13.5px;${tone(a.level)}">${escapeHtml(a.text)}</div>`).join('')}
  </div>`;
}
async function savePrivacyPolicy() {
  const content = document.getElementById('settings-privacy-policy').value.trim();
  if (content.length < 10) return showToast('Enter some real content first');
  try { await apiFetch('PATCH', '/admin/settings/privacy-policy', { content }); showToast('Privacy Policy updated. Live now.'); }
  catch (e) { showToast(e.message || 'Could not save this'); }
}

// v82: Admin → Settings (super admin): the nightly data copies.
async function loadBackupsPanel() {
  const main = document.getElementById('admin-main');
  if (!main || !BACKEND_AVAILABLE || !(AUTH.user && AUTH.user.isSuperAdmin)) return;
  let d; try { d = await apiFetch('GET', '/admin/backups'); } catch (e) { return; }
  const old = document.getElementById('backups-panel'); if (old) old.remove();
  if (!d.applies) return;
  const latest = d.backups[0];
  const rows = d.backups.map(b => `<tr><td>${escapeHtml(b.day)}</td><td>${b.files}</td><td>${Math.max(1, Math.round(b.bytes / 1024)).toLocaleString()} KB</td><td><button class="btn-sm btn-sm-ghost" onclick="downloadBackup(${jsArg(b.day)})">Download</button></td></tr>`).join('');
  main.insertAdjacentHTML('beforeend', `<div class="panel" id="backups-panel">
    <div class="panel-title">Data backups <small>a copy of the records, taken every night</small></div>
    <div style="font-size:14px;line-height:1.6;color:var(--text);margin-bottom:10px;">${latest ? `Latest copy: <strong>${escapeHtml(latest.day)}</strong>. The newest ${d.keepDays} days are kept.` : 'No copy has been taken yet. The first one is made about a minute after the server starts.'} These copies sit on the same disk as the data, so they protect against a bad change or a mistake, not against losing the disk. Uploaded photos and ID files are not included.</div>
    <div style="font-size:14px;line-height:1.6;color:var(--text);margin-bottom:10px;">These copies sit on the same disk as the site, so they wouldn't survive losing that disk. Press <strong>Download</strong> beside a day to save that copy to this computer, and keep it somewhere safe (a different computer, a USB drive, or a cloud folder only you can open). About once a week is a sensible habit. The file holds every record on the site, so treat it like the keys to the business.</div>
    <button class="btn-sm btn-sm-outline" onclick="runBackupNow()">Take a copy now</button>
    ${rows ? `<div class="data-table-wrap" style="margin-top:12px;"><table class="data-table"><thead><tr><th>Day</th><th>Files</th><th>Size</th><th>Keep a copy</th></tr></thead><tbody>${rows}</tbody></table></div>` : ''}
  </div>`);
}
// v99: save one day's backup to this computer.
function downloadBackup(day) {
  const old = document.getElementById('backup-dl-overlay'); if (old) old.remove();
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-overlay open" id="backup-dl-overlay" style="z-index:5300;"><div class="modal" style="max-width:440px;" role="dialog" aria-modal="true">
    <div class="modal-header"><h3>Download the backup for ${escapeHtml(day)}</h3><p>This file holds every record on the site. Enter your own sign-in password to confirm it's you.</p></div>
    <div class="modal-body"><div class="form-group" style="margin-bottom:0;"><label class="form-label" for="backup-dl-pw">Your password</label><input class="form-input" type="password" id="backup-dl-pw" autocomplete="current-password" onkeydown="if(event.key==='Enter'){event.preventDefault();confirmDownloadBackup(${jsArg(day)})}"/></div></div>
    <div class="modal-footer" style="display:flex;gap:10px;">
      <button class="btn-sm btn-sm-outline" style="flex:1;" onclick="document.getElementById('backup-dl-overlay').remove()">Cancel</button>
      <button class="confirm-btn" style="flex:1;" id="backup-dl-btn" onclick="confirmDownloadBackup(${jsArg(day)})">Download</button>
    </div></div></div>`);
  setTimeout(() => { const i = document.getElementById('backup-dl-pw'); if (i) i.focus(); }, 50);
}
async function confirmDownloadBackup(day) {
  const pw = document.getElementById('backup-dl-pw').value;
  if (!pw) return showToast('Enter your password');
  const btn = document.getElementById('backup-dl-btn'); btn.disabled = true; btn.textContent = 'Preparing…';
  try {
    const res = await fetch(API_BASE + '/admin/backups/download', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + AUTH.token }, body: JSON.stringify({ password: pw, day }) });
    if (!res.ok) { let msg = 'The download failed'; try { msg = (await res.json()).error || msg; } catch (e) {} throw new Error(msg); }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `trothen-backup-${day}.tar.gz`; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    document.getElementById('backup-dl-overlay').remove();
    showToast('Backup saved to your downloads. Keep it somewhere safe.');
  } catch (e) { btn.disabled = false; btn.textContent = 'Download'; showToast(e.message || 'The download failed'); }
}
async function runBackupNow() {
  try { const r = await apiFetch('POST', '/admin/backups/run'); showToast(`Copied ${r.files} data files`); loadBackupsPanel(); }
  catch (e) { showToast(e.message || 'The backup failed'); }
}

// v81: super admin gives someone a one-time password. For when a person
// can't get in and reset-by-email isn't connected.
async function issueTempPassword(userId, name) {
  const ok = await confirmDialog(`Reset the password for ${name}? Only do this after you've confirmed it's really them (for example, by calling the phone number on their account). They'll be signed out everywhere and must choose a new password at their next sign-in.`, { confirmLabel: 'Reset password', danger: true });
  if (!ok) return;
  try {
    const { tempPassword } = await apiFetch('POST', '/admin/users/' + encodeURIComponent(userId) + '/temp-password');
    document.body.insertAdjacentHTML('beforeend', `<div class="modal-overlay open" id="temp-password-overlay" style="z-index:5200;"><div class="modal" style="max-width:440px;" role="dialog" aria-modal="true">
      <div class="modal-header"><h3>One-time password for ${escapeHtml(name)}</h3><p>This is shown once. Give it to them directly, by phone or in person. Don't send it in a message other people can read.</p></div>
      <div class="modal-body"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:20px;letter-spacing:.06em;padding:14px;border:1.5px solid var(--border);border-radius:10px;text-align:center;user-select:all;word-break:break-all;">${escapeHtml(tempPassword)}</div></div>
      <div class="modal-footer"><button class="confirm-btn" onclick="document.getElementById('temp-password-overlay').remove()">I've given it to them</button></div>
    </div></div>`);
  } catch (e) { showToast(e.message || 'Could not reset the password'); }
}

// v75: under the Verified badge, how it happened and who did it.
function verifiedHowHTML(u) {
  if (!u.verified || !u.verifiedVia) return '';
  const when = u.verifiedAt ? ', ' + escapeHtml(String(u.verifiedAt).slice(0, 10)) : '';
  const who = u.verifiedByName ? ' by ' + escapeHtml(u.verifiedByName) : '';
  const text = u.verifiedVia === 'id_review' ? `ID reviewed${who}${when}`
    : u.verifiedVia === 'persona' ? `Automated ID check${when}`
    : u.verifiedVia === 'account_approval' ? `Account approved${who}${when}. No ID on file`
    : 'No ID on file, and no record of who approved';
  const warn = u.verifiedVia === 'account_approval' || u.verifiedVia === 'unknown';
  return `<div style="font-size:11.5px;line-height:1.35;margin-top:4px;max-width:170px;color:${warn ? '#8C6423' : 'var(--slate)'};">${text}</div>`;
}

