async function toggleUserActive(userId, active) {
  if (!BACKEND_AVAILABLE) return showToast(active ? 'Reactivated (demo mode)' : 'Suspended (demo mode)');
  try {
    const { user } = await apiFetch('PATCH', `/admin/users/${userId}/status`, { active });
    showToast(`${user.name} ${active ? 'reactivated' : 'suspended'}`);
    await loadAdminData();
    selectAdminSection('people');
  } catch (e) { showToast(e.message || 'Could not update user status'); }
}

// Item: a real, complete backend feature (propose → super-admin-approve
// a custom commission rate for a standout provider) existed with zero
// way to actually reach it from the UI — found during a full audit, not
// reported by name. Two sequential prompts rather than a bigger custom
// modal, reusing the existing confirmDialog text-input mode: rate first
// (validated as a real percentage before the reason is even asked for,
// so nobody types a paragraph only to get rejected on the number after),
// then the reason the backend actually requires.
async function proposeCommissionRate(providerId) {
  const rateText = await confirmDialog('What commission rate should this provider get? Enter a percentage, e.g. 8 for 8%.', { requireTextInput: true, confirmLabel: 'Next' });
  if (rateText === null) return;
  const ratePercent = parseFloat(rateText);
  if (isNaN(ratePercent) || ratePercent < 0 || ratePercent > 50) return showToast('Enter a number between 0 and 50');
  const reason = await confirmDialog(`Why does this provider deserve a custom ${ratePercent}% rate? A super admin will see this to decide.`, { requireTextInput: true, confirmLabel: 'Submit for Approval' });
  if (reason === null) return;
  try {
    await apiFetch('POST', `/admin/providers/${providerId}/propose-commission-rate`, { rate: ratePercent / 100, reason });
    showToast('Proposal sent — a super admin will review it');
    document.getElementById('person-detail-overlay') && document.getElementById('person-detail-overlay').remove();
    await loadAdminData();
  } catch (e) { showToast(e.message || 'Could not submit the proposal'); }
}

async function decideCommissionRate(providerId, decision) {
  if (!(await confirmDialog(decision === 'approve' ? 'Approve this custom commission rate? It takes effect immediately.' : 'Reject this proposal? The provider stays on their normal plan rate.', { danger: decision === 'reject', confirmLabel: decision === 'approve' ? 'Approve' : 'Reject' }))) return;
  try {
    await apiFetch('POST', `/admin/providers/${providerId}/commission-rate/${decision}`, {});
    showToast(decision === 'approve' ? 'Custom rate approved' : 'Proposal rejected');
    document.getElementById('person-detail-overlay') && document.getElementById('person-detail-overlay').remove();
    await loadAdminData();
  } catch (e) { showToast(e.message || 'Could not record this decision'); }
}

function usersTable(list, sectionKey) {
  if (!list.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">No pending approvals.</div>`;
  return `<div class="ver-note" style="margin-bottom:10px;"><strong>Approving an account here does not verify the person.</strong> It lets them in. They only become "Verified" when the ID they upload is approved in the <a onclick="selectAdminSection('verification')" style="color:var(--teal);font-weight:600;cursor:pointer;">Verification Queue</a>. The ID column shows where that stands.</div>
  <div class="data-table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Role</th><th>City</th><th>Country</th><th>Submitted</th><th>Account</th><th>ID</th><th>Action</th></tr></thead><tbody>
  ${list.map(u => `<tr><td>${escapeHtml(u.name)}</td><td>${escapeHtml(u.role)}</td><td>${escapeHtml(u.city) || '—'}</td><td>${escapeHtml(u.country)}</td><td>${escapeHtml(u.submitted)}</td><td>${statusBadge(u.status)}</td><td>${idStatusHTML(u.idStatus, true)}</td>
  <td class="row-actions">${u.status==='pending' ? `<button class="btn-sm btn-sm-primary" onclick="adminDecide('users','${u.id}','approve','${sectionKey}')">Approve</button><button class="btn-sm btn-sm-outline" onclick="adminDecide('users','${u.id}','reject','${sectionKey}')">Reject</button>` : '—'}</td></tr>`).join('')}
  </tbody></table></div>`;
}

// v77: how ID files are stored and for how long, on the page itself.
function verificationKeepingPanelHTML() {
  const m = adminData.verificationMeta;
  if (!m) return '';
  const isSuper = AUTH.user && AUTH.user.isSuperAdmin;
  const days = Number(m.retentionDays) || 0;
  const storageLine = m.storage && m.storage.persistent
    ? '<div class="ver-note">Storage: ID files are saved to the permanent disk.</div>'
    : '<div style="background:#FBEAE8;border:1px solid #E3B4AE;color:#8A2D25;border-radius:8px;padding:10px 12px;font-size:13.5px;margin-bottom:10px;"><strong>ID files are not on the permanent disk.</strong> PRIVATE_UPLOADS_DIR is not set on the server, so uploaded IDs are lost every time the site is redeployed. Set it in Render to a folder on the disk (for example /var/data/private-uploads).</div>';
  const encLine = m.storage && m.storage.encrypted
    ? '<div class="ver-note">Extra encryption: on. New ID files are scrambled on the disk and only unscrambled when a reviewer opens one.</div>'
    : ''; // v104: when it's off, this panel says nothing. It was a technical note shown to every reviewer, on every visit. The status and the steps to switch it on are in Admin → Go-Live, where set-up tasks belong.
  const autoLine = m.automatedCheckConnected
    ? '<div class="ver-note">Automated ID and face check (Persona): connected.</div>'
    : '<div class="ver-note">Every ID is checked by a person on the team, using the uploaded ID and face photo.</div>'; // v104: says how checks are done, without the "not connected" notice (that is on Go-Live too)
  const keepLine = days > 0
    ? `ID and face photos are deleted <strong>${days} days</strong> after a decision (approved, rejected or replaced). The record of the check is kept. Files are held longer, automatically, while the person has an open dispute, an open fraud review, or an account on hold.`
    : 'ID and face photos are kept until someone deletes them. No automatic deletion is set.';
  return `<div class="panel">
    <div class="panel-title">How ID files are kept</div>
    ${storageLine}
    <div style="font-size:14px;color:var(--text);margin:8px 0;">${keepLine}</div>
    ${isSuper ? `<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:10px 0;">
      <label class="form-label" style="margin:0;" for="id-retention-days">Delete files after</label>
      <input class="form-input" id="id-retention-days" type="number" min="0" max="3650" value="${escapeHtml(days)}" style="width:100px;"/>
      <span style="font-size:14px;color:var(--slate);">days (0 = keep)</span>
      <button class="btn-sm btn-sm-primary" onclick="saveIdRetention()">Save</button>
    </div>` : ''}
    ${encLine}
    ${autoLine}
  </div>`;
}
async function saveIdRetention() {
  const days = Number(document.getElementById('id-retention-days').value);
  if (!Number.isInteger(days) || days < 0) return showToast('Enter a whole number of days, or 0 to keep files');
  const current = Number(adminData.verificationMeta && adminData.verificationMeta.retentionDays) || 0;
  if (days > 0 && (current === 0 || days < current)) {
    const ok = await confirmDialog(`Delete ID and face photos ${days} days after a decision? Files already older than that are deleted within a day and can't be brought back. The record of each check is kept.`, { confirmLabel: 'Save', danger: true });
    if (!ok) return;
  }
  try {
    const res = await apiFetch('PATCH', '/admin/settings/id-retention', { days });
    adminData.verificationMeta.retentionDays = res.retentionDays;
    showToast(res.retentionDays > 0 ? `Saved. Files are deleted ${res.retentionDays} days after a decision.` : 'Saved. Files are kept until deleted by hand.');
    selectAdminSection('verification');
  } catch (e) { showToast(e.message || 'Could not save'); }
}
async function askAllVerificationGaps() {
  const ok = await confirmDialog('Send everyone on this list a message asking them to verify their ID? Nobody\'s badge is removed.', { confirmLabel: 'Send' });
  if (!ok) return;
  try {
    const { asked } = await apiFetch('POST', '/admin/verification-gaps-ask-all');
    showToast(asked ? `Asked ${asked} ${asked === 1 ? 'person' : 'people'} to verify their ID` : 'Nobody to ask. Everyone has an ID on file or waiting.');
  } catch (e) { showToast(e.message || 'Could not send'); }
}

function verificationQueueTable() {
  // v107: never say "nothing is waiting" to an account that simply isn't allowed to look.
  if (adminData.verificationQueueBlocked) return `<div style="background:#FBF3E4;border:1px solid #E9D6A8;color:#5C4A12;border-radius:8px;padding:12px 14px;font-size:14px;line-height:1.6;"><strong>Your admin account can't open ID submissions.</strong> ID documents can only be opened by a super admin, the verification team, or the regional admin for that person's area. If IDs are waiting, one of them needs to review them. You can still approve accounts in User Approvals, but that does not verify anyone.</div>`;
  if (!adminData.verificationQueue.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">Nothing is waiting for review. When someone submits an ID it appears here with a View documents button. IDs already decided are under Past checks below.</div>`;
  return `<div class="ver-howto">Open the ID (front, and back if there is one) and the face photo side by side. Check that the ID is a real document, that it isn't expired, that the photo and details are readable, that the name on it matches the account, and that the face photo shows the same person as the ID. Then approve, or reject with a reason the applicant will see. If there's no face photo, or you can't tell, reject and ask for a clearer one.</div>
  <div class="data-table-wrap"><table class="data-table"><thead><tr><th>Applicant</th><th>Name on the ID</th><th>Document</th><th>Submitted</th><th>Status</th><th>Action</th></tr></thead><tbody>
  ${adminData.verificationQueue.map(v => {
    // Real 48-hour review SLA: only ever shown for items still open.
    const isOpen = v.status === 'pending' || v.status === 'review_required';
    const isOverdue = isOpen && v.reviewDeadline && new Date(v.reviewDeadline) < new Date();
    const match = v.nameMatch === true ? '<span class="badge badge-success">Matches account</span>'
      : v.nameMatch === false ? '<span class="badge badge-danger">Doesn\'t match account</span>' : '';
    const docCell = v.source === 'persona'
      ? `${escapeHtml(v.doc)}<div class="ver-note">Checked by Persona. See this person in your Persona dashboard.</div>`
      : `${escapeHtml(v.doc)}${v.hasDocument ? `<div><button class="btn-sm btn-sm-ghost" style="margin-top:6px;" onclick="viewVerificationDocument('${escapeHtml(v.id)}')">View documents</button></div>` : '<div class="ver-note">No file on record</div>'}${v.hasBack ? `<div><button class="btn-sm btn-sm-ghost" style="margin-top:6px;" onclick="viewVerificationDocument('${escapeHtml(v.id)}','back')">View back of ID</button></div>` : ''}${v.hasSelfie ? `<div><button class="btn-sm btn-sm-ghost" style="margin-top:6px;" onclick="viewVerificationDocument('${escapeHtml(v.id)}','selfie')">View face photo</button></div>` : '<div class="ver-note" style="color:#8C6423;">No face photo (sent before it was required)</div>'}`;
    return `<tr>
      <td><strong>${escapeHtml(v.name)}</strong><div class="ver-note">${escapeHtml([v.role ? v.role[0].toUpperCase() + v.role.slice(1) : '', v.city, v.country].filter(Boolean).join(' · '))}</div></td>
      <td>${v.idLegalName ? escapeHtml(v.idLegalName) : '<span class="ver-note">Not given</span>'}<div style="margin-top:4px;">${match}</div></td>
      <td>${docCell}</td>
      <td>${v.createdAt ? escapeHtml(new Date(v.createdAt).toLocaleString()) : '—'}</td>
      <td>${statusBadge(v.status).replace('review_required', 'Needs review')}${isOverdue ? ' <span class="badge badge-danger" title="Past the 48-hour review window">Overdue</span>' : ''}</td>
      <td class="row-actions">${isOpen ? `<button class="btn-sm btn-sm-primary" onclick="adminDecide('verification','${escapeHtml(v.id)}','approve','verification')">Approve</button><button class="btn-sm btn-sm-outline" onclick="adminDecide('verification','${escapeHtml(v.id)}','reject','verification')">Reject</button>` : '—'}</td>
    </tr>`;
  }).join('')}
  </tbody></table></div>`;
}

// Opens a submitted ID in a new tab. The file is fetched with the admin's
// own sign-in (it's never publicly reachable), and every view is recorded
// on the server in the access log.
// v85: documents open inside the page, side by side, instead of in a
// pop-up tab that browsers often block. One window shows the front of the
// ID, the back (if there is one) and the face photo together, which is
// what a reviewer needs to compare. Each file opened is written to the
// access log by the server, as before.
let ID_VIEWER_URLS = [];
function closeIdViewer() {
  const o = document.getElementById('id-viewer-overlay'); if (o) o.remove();
  ID_VIEWER_URLS.forEach(u => { try { URL.revokeObjectURL(u); } catch (e) {} });
  ID_VIEWER_URLS = [];
}
async function viewVerificationDocument(id, kind) {
  closeIdViewer();
  const parts = [['document', 'Front of ID'], ['back', 'Back of ID'], ['selfie', 'Face photo']];
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-overlay open" id="id-viewer-overlay" style="z-index:5300;" onclick="if(event.target===this)closeIdViewer()">
    <div class="modal" style="max-width:min(1180px,96vw);width:96vw;max-height:94vh;display:flex;flex-direction:column;" role="dialog" aria-modal="true" aria-label="Identity documents">
      <div class="modal-header" style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-shrink:0;">
        <div><h3 style="margin:0;">Identity documents</h3><p style="margin:4px 0 0;">Compare the face photo with the photo on the ID. Click a picture to see it full size. Every file opened here is recorded in the access log.</p></div>
        <button class="modal-close" onclick="closeIdViewer()" aria-label="Close">✕</button>
      </div>
      <div class="modal-body" id="id-viewer-body" style="overflow:auto;flex:1 1 auto;min-height:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px;align-items:start;">
        ${parts.map(([k, label]) => `<div id="id-viewer-${k}" style="border:1px solid var(--border);border-radius:10px;padding:10px;${k === kind || (!kind && k === 'document') ? 'outline:2px solid var(--teal);' : ''}">
          <div style="font-weight:600;font-size:14px;margin-bottom:8px;">${label}</div>
          <div class="ver-note" data-slot>Loading…</div>
        </div>`).join('')}
      </div>
    </div>
  </div>`);
  await Promise.all(parts.map(async ([k]) => {
    const box = document.getElementById('id-viewer-' + k);
    if (!box) return;
    const slot = box.querySelector('[data-slot]');
    try {
      const res = await fetch(API_BASE + '/admin/verification/' + encodeURIComponent(id) + '/' + k, { headers: { Authorization: 'Bearer ' + AUTH.token } });
      if (res.status === 404) {
        if (k === 'back') { box.remove(); return; } // most IDs have no back; don't show an empty box
        let why = 'Not on file.'; try { why = (await res.json()).error || why; } catch (e) {}
        slot.textContent = k === 'selfie' ? 'No face photo on file. It may have been sent before face photos were required, or the files have been deleted.' : why;
        return;
      }
      if (!res.ok) { let msg = 'Could not open this file.'; try { msg = (await res.json()).error || msg; } catch (e) {} slot.textContent = msg; return; }
      const blob = await res.blob();
      const url = URL.createObjectURL(blob); ID_VIEWER_URLS.push(url);
      const isPdf = (res.headers.get('content-type') || blob.type || '').includes('pdf');
      slot.className = '';
      slot.innerHTML = isPdf
        ? `<iframe src="${url}" title="PDF document" style="width:100%;height:62vh;border:0;border-radius:6px;background:#fff;"></iframe><div style="margin-top:6px;"><a href="${url}" target="_blank" rel="noopener" class="tg-link" style="font-size:13px;">Open the PDF in a new tab</a></div>`
        : `<a href="${url}" target="_blank" rel="noopener" title="Open full size"><img src="${url}" alt="" style="width:100%;max-height:68vh;object-fit:contain;border-radius:6px;background:var(--offwhite);display:block;"/></a>`;
    } catch (e) { slot.textContent = 'Could not open this file. Check your connection and try again.'; }
  }));
}

// v85: Admin → Verification Queue → "Past checks". Decisions already made,
// with the same View button, for as long as the files are kept.
async function loadVerificationHistory() {
  const box = document.getElementById('verification-history-panel');
  if (!box || !BACKEND_AVAILABLE) return;
  let history;
  try { history = (await apiFetch('GET', '/admin/verification-history')).history; }
  catch (e) { box.innerHTML = '<div class="ver-note">Could not load past checks.</div>'; return; }
  if (!history.length) { box.innerHTML = '<div style="color:var(--slate);font-size:14px;padding:12px 0;">No ID has been approved or rejected yet.</div>'; return; }
  window.__verHistory = history;
  renderVerificationHistory('');
}
function renderVerificationHistory(filter) {
  const box = document.getElementById('verification-history-rows');
  const host = document.getElementById('verification-history-panel');
  if (!host) return;
  const f = String(filter || '').trim().toLowerCase();
  const list = (window.__verHistory || []).filter(h => !f || String(h.userName || '').toLowerCase().includes(f) || String(h.idLegalName || '').toLowerCase().includes(f));
  const badge = (s) => s === 'approved' ? '<span class="badge badge-success">Approved</span>' : s === 'rejected' ? '<span class="badge badge-danger">Rejected</span>' : '<span class="badge badge-neutral">Replaced by a newer upload</span>';
  const rows = list.map(h => {
    const hasFiles = h.hasDocument || h.hasBack || h.hasSelfie;
    const files = hasFiles
      ? `<button class="btn-sm btn-sm-outline" onclick="viewVerificationDocument(${jsArg(h.id)})">View documents</button>${h.filesHeldReason ? `<div class="ver-note" style="margin-top:4px;color:#8C6423;">Files held: ${escapeHtml(h.filesHeldReason)}</div>` : (h.filesDeleteOn ? `<div class="ver-note" style="margin-top:4px;">Files deleted on ${escapeHtml(h.filesDeleteOn)}</div>` : '')}`
      : `<div class="ver-note">${h.filesDeletedAt ? 'Files deleted ' + escapeHtml(String(h.filesDeletedAt).slice(0, 10)) : 'No files on record'}</div>`;
    return `<tr><td><strong>${escapeHtml(h.userName)}</strong><div class="ver-note">${h.role === 'provider' ? 'Pro' : 'Customer'}${h.city ? ' · ' + escapeHtml(h.city) : ''}</div></td>
      <td>${escapeHtml(h.docType || '—')}<div class="ver-note">${escapeHtml(h.idLegalName || '')}</div></td>
      <td>${badge(h.status)}${h.rejectionReason ? `<div class="ver-note" style="margin-top:4px;max-width:220px;">${escapeHtml(h.rejectionReason)}</div>` : ''}</td>
      <td>${escapeHtml(String(h.decidedAt || '').slice(0, 10))}<div class="ver-note">${escapeHtml(h.reviewedByName || '')}</div></td>
      <td>${files}</td></tr>`;
  }).join('');
  const table = rows ? `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Document</th><th>Decision</th><th>Decided</th><th>Files</th></tr></thead><tbody>${rows}</tbody></table></div>` : '<div class="ver-note" style="padding:10px 0;">No one matches that name.</div>';
  if (box) { box.innerHTML = table; return; }
  host.innerHTML = `<input class="form-input" type="search" placeholder="Search by name" aria-label="Search past checks by name" style="max-width:280px;margin-bottom:10px;" oninput="renderVerificationHistory(this.value)"/><div id="verification-history-rows">${table}</div>`;
}

// Providers who carry the "ID checked" badge with no reviewed ID on file.
async function loadVerificationGaps() {
  const box = document.getElementById('verification-gaps-panel');
  if (!box || !BACKEND_AVAILABLE) return;
  try {
    const { gaps } = await apiFetch('GET', '/admin/verification-gaps');
    if (!gaps.length) { box.innerHTML = '<div style="color:var(--slate);font-size:14px;padding:12px 0;">Everyone marked verified has a reviewed ID on file.</div>'; return; }
    box.innerHTML = `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Role</th><th>Where</th><th>ID submitted?</th><th>Action</th></tr></thead><tbody>
      ${gaps.map(g => `<tr><td><strong>${escapeHtml(g.name)}</strong></td><td>${g.role === 'customer' ? 'Customer' : 'Provider'}</td><td>${escapeHtml([g.city, g.country].filter(Boolean).join(', ') || '—')}</td><td>${g.idSubmitted ? '<span class="badge badge-pending">Waiting in the queue above</span>' : '<span class="badge badge-neutral">Not yet</span>'}</td>
      <td class="row-actions"><button class="btn-sm btn-sm-ghost" onclick="verificationGapAction('${escapeHtml(g.id)}','request')">Ask for ID</button><button class="btn-sm btn-sm-outline" onclick="verificationGapAction('${escapeHtml(g.id)}','remove_badge')">Remove badge until checked</button></td></tr>`).join('')}
    </tbody></table></div>`;
  } catch (e) { box.innerHTML = ''; }
}
async function verificationGapAction(userId, action) {
  if (action === 'remove_badge') {
    const ok = await confirmDialog('Take "Verified" off this account until their ID is reviewed? A provider is hidden from search until then; a customer can\'t post a job or book. We\'ll message them asking for their ID.', { confirmLabel: 'Remove badge' });
    if (!ok) return;
  }
  try {
    await apiFetch('POST', '/admin/verification-gaps/' + encodeURIComponent(userId), { action });
    showToast(action === 'request' ? 'Asked them to verify their ID' : 'Badge removed until their ID is checked');
    loadVerificationGaps();
  } catch (e) { showToast(e.message || 'Could not update'); }
}

function disputesTable(list) {
  if (!list.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">No disputes.</div>`;
  return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Dispute</th><th>Parties</th><th>Reason</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>
  ${list.map(d => `<tr style="cursor:pointer" onclick="viewDispute('${d.id}')"><td>${escapeHtml(d.id)}</td><td>${escapeHtml(d.parties)}</td><td>${escapeHtml(d.reason)}</td><td>$${d.amount}</td><td>${statusBadge(d.status)}</td>
  <td class="row-actions"><button class="btn-sm btn-sm-ghost" onclick="event.stopPropagation();viewDispute('${d.id}')">${d.status === 'open' ? 'Resolve' : 'View'}</button></td></tr>`).join('')}
  </tbody></table></div>`;
}

const FRAUD_TYPE_LABELS = {
  duplicate_identity: 'Duplicate Identity',
  price_anomaly: 'Price Anomaly',
  repeat_disputes: 'Repeat Disputes',
  new_account_high_value: 'New Account, High Value',
  implausible_travel_speed: 'Implausible Travel Speed',
  payout_velocity: 'Unusual Payout Velocity',
  protected_cancellation_pattern: 'Repeated Protected Cancellations',
};

function fraudFlagsTableHTML(flags) {
  const open = flags.filter(f => f.status === 'open');
  const resolved = flags.filter(f => f.status !== 'open');
  if (!flags.length) return `<div style="color:var(--slate);font-size:14px;padding:12px 0;">No fraud flags yet — this fills in automatically as real signups, bookings, and disputes get screened.</div>`;
  return `
    ${open.length ? `<div style="font-size:13px;color:var(--slate);font-weight:600;margin-bottom:8px;">${open.length} open</div>` : ''}
    <div class="data-table-wrap"><table class="data-table"><thead><tr><th>Type</th><th>Severity</th><th>Account</th><th>Details</th><th>Flagged</th><th>Status</th><th>Action</th></tr></thead><tbody>
    ${flags.map(f => `<tr><td>${escapeHtml(FRAUD_TYPE_LABELS[f.type] || f.type)}</td><td>${f.severity==='high' ? '<span class="badge badge-danger">High</span>' : '<span class="badge badge-warn">Medium</span>'}</td><td>${escapeHtml(f.userName || '—')}${f.relatedUserName ? ` ↔ ${escapeHtml(f.relatedUserName)}` : ''}</td><td style="max-width:280px;">${escapeHtml(f.details)}</td><td>${new Date(f.createdAt).toLocaleDateString()}</td><td>${f.status === 'open' ? '<span class="badge badge-pending">Open</span>' : statusBadge(f.status)}</td>
    <td class="row-actions">${f.status === 'open' ? `<button class="btn-sm btn-sm-outline" onclick="resolveFraudFlag('${f.id}','reviewed')">Mark Reviewed</button> <button class="btn-sm btn-sm-ghost" onclick="resolveFraudFlag('${f.id}','dismissed')">Dismiss</button>` : '—'}</td></tr>`).join('')}
    </tbody></table></div>`;
}

async function resolveFraudFlag(id, decision) {
  if (!BACKEND_AVAILABLE) return showToast(`Flag ${decision} (demo mode)`);
  try {
    await apiFetch('POST', `/admin/fraud-flags/${id}/resolve`, { decision });
    showToast(decision === 'reviewed' ? 'Marked as reviewed' : 'Flag dismissed');
    await loadAdminData();
    selectAdminSection('fraud');
  } catch (e) { showToast(e.message || 'Could not update flag'); }
}

async function viewDispute(id) {
  const d = adminData.disputes.find(x => x.id === id);
  if (!d) return;
  document.getElementById('dispute-modal-title').textContent = 'Dispute ' + d.id;
  document.getElementById('dispute-modal-sub').textContent = d.parties;
  const openedDate = d.createdAt ? new Date(d.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : null;

  let auditLogHTML = '';
  let evidenceHTML = '';
  if (BACKEND_AVAILABLE) {
    try {
      const { log } = await apiFetch('GET', `/admin/disputes/${id}/audit-log`);
      if (log && log.length) {
        auditLogHTML = `<div class="form-label" style="margin:14px 0 8px;">Audit trail</div>
          <div style="font-size:13px;color:var(--slate);line-height:1.8;max-height:160px;overflow-y:auto;border-top:1px solid var(--border);padding-top:8px;">
          ${log.map(l => `<div style="margin-bottom:6px;"><strong style="color:var(--navy);">${DISPUTE_ACTION_LABEL[l.action] || l.action}</strong> by ${escapeHtml(l.actorName)} — ${escapeHtml(l.note)} <span style="opacity:.6;">(${new Date(l.createdAt).toLocaleString()})</span></div>`).join('')}
          </div>`;
      }
    } catch (e) { /* no audit entries yet, or not permitted — leave blank */ }
    try {
      const { evidence } = await apiFetch('GET', `/disputes/${id}/evidence`);
      evidenceHTML = `<div class="form-label" style="margin:14px 0 8px;">Evidence ${evidence.length ? `(${evidence.length})` : ''}</div>` +
        (evidence.length
          ? `<div style="font-size:13.5px;line-height:2;">${evidence.map(e => `<div>📎 <a href="${API_BASE}/disputes/${id}/evidence/${e.id}/file" target="_blank" rel="noopener" onclick="event.preventDefault();downloadDisputeEvidence('${id}','${e.id}',${jsArg(e.originalName)})" style="color:var(--navy);">${escapeHtml(e.originalName)}</a> <span style="color:var(--muted);">— uploaded by ${escapeHtml(e.uploadedByName)}</span></div>`).join('')}</div>`
          : `<div style="font-size:13.5px;color:var(--slate);">No evidence uploaded for this dispute.</div>`);
    } catch (e) { /* not permitted or none yet */ }
  }

  document.getElementById('dispute-modal-body').innerHTML = `
    <div class="booking-summary">
      <div class="summary-row"><span>Reason</span><span>${escapeHtml(d.reason)}</span></div>
      <div class="summary-row"><span>Amount in escrow</span><span>$${d.amount}</span></div>
      <div class="summary-row total"><span>Status</span><span>${statusBadge(d.status)}</span></div>
    </div>
    <div class="form-label" style="margin-bottom:10px;">Timeline</div>
    <div style="font-size:13.5px;color:var(--slate);line-height:2;">
      ⚠️ Dispute opened${openedDate ? ` — ${openedDate}` : ''}<br/>
      ${d.status === 'resolved' ? (d.resolution === 'refund_customer' ? '✅ Resolved — customer refunded' : '✅ Resolved — escrow released to provider') : `Current status: ${DISPUTE_ACTION_LABEL[d.status] || d.status}`}
    </div>
    ${evidenceHTML}
    ${auditLogHTML}`;

  const isSuperAdmin = AUTH.user && AUTH.user.isSuperAdmin;
  // v96: any dispute that hasn't been decided can be decided. This used to
  // show the buttons only for "open", so one marked "in review" or
  // "escalated" had no way to be resolved from this window.
  const isOpen = !['resolved', 'closed', 'rejected'].includes(d.status);
  const resolveButtons = isOpen
    ? `<button class="confirm-btn" onclick="resolveDispute('${d.id}','release_to_provider');closeDisputeModal();">Release Escrow to Provider</button><button class="btn-sm btn-sm-outline" onclick="resolveDispute('${d.id}','refund_customer');closeDisputeModal();">Refund Customer Instead</button><button class="btn-sm btn-sm-outline" onclick="closeDisputeModal();openSplitDispute(${jsArg(d.id)}, ${jsArg(d.amount)})">Split Between Them</button>`
    : '';
  // Item 14: the super-admin-only action set — request info, escalate,
  // reject, close, and (only from a settled state) reopen. Every one of
  // these calls the same POST /admin/disputes/:id/action endpoint and
  // requires a real note, which is what actually populates the audit
  // trail shown above.
  const superAdminButtons = isSuperAdmin
    ? (isOpen
        ? `<button class="btn-sm btn-sm-outline" onclick="dispatchDisputeAction('${d.id}','request_info')">Request Info</button><button class="btn-sm btn-sm-outline" onclick="dispatchDisputeAction('${d.id}','escalate')">Escalate</button><button class="btn-sm btn-sm-outline" onclick="dispatchDisputeAction('${d.id}','reject')">Reject</button><button class="btn-sm btn-sm-outline" onclick="dispatchDisputeAction('${d.id}','close')">Close</button>`
        : `<button class="btn-sm btn-sm-outline" onclick="dispatchDisputeAction('${d.id}','reopen')">Reopen</button>`)
    : '';
  document.getElementById('dispute-modal-footer').innerHTML = (resolveButtons || superAdminButtons)
    ? `<div style="display:flex;gap:8px;flex-wrap:wrap;">${resolveButtons}${superAdminButtons}</div>`
    : `<button class="pricing-cta" style="width:100%;" onclick="closeDisputeModal()">Close</button>`;
  document.getElementById('dispute-modal').classList.add('open');
}

const DISPUTE_ACTION_LABEL = {
  open: 'Open', escalated: 'Escalated', rejected: 'Rejected', closed: 'Closed', resolved: 'Resolved',
  request_info: 'Info requested', escalate: 'Escalated', reject: 'Rejected', close: 'Closed', reopen: 'Reopened', resolve: 'Resolved',
};

async function dispatchDisputeAction(id, action) {
  const note = (prompt(`Add a note for this action (required, becomes part of the permanent audit trail):`) || '').trim();
  if (!note) return showToast('A note is required for this action');
  if (!BACKEND_AVAILABLE) return showToast(`${DISPUTE_ACTION_LABEL[action]} (demo mode)`);
  try {
    await apiFetch('POST', `/admin/disputes/${id}/action`, { action, note });
    showToast(`Dispute ${DISPUTE_ACTION_LABEL[action].toLowerCase()}`);
    closeDisputeModal();
    await loadAdminData();
    selectAdminSection('disputes');
  } catch (e) { showToast(e.message || 'Could not update dispute'); }
}
function closeDisputeModal() {
  document.getElementById('dispute-modal').classList.remove('open');
}

function selectAdminSection(key) {
  if (!ADMIN_SECTIONS[key]) key = 'overview';
  renderDashNav('admin-nav', getAdminNavItems(), key, 'selectAdminSection');
  renderSectionSafely('admin-main', key, () => ADMIN_SECTIONS[key]());
  if (key === 'providerscores') loadProviderScoresPanel();
  if (key === 'verification') { loadGuarantorsReviewPanel(); loadVerificationGaps(); loadVerificationHistory(); loadVerificationWaiting(); }
  if (key === 'people') loadAccountClosuresPanel();
  if (key === 'pricing') loadPlanBillingPanel();
  if (key === 'settings') { loadWordingEditor(); loadBackupsPanel(); loadPrivacyEditor(); }
  if (key === 'promotions') loadAdminPromotionsPanel();
  if (key === 'announcements') loadAnnouncementsPanel();
  if (key === 'datacleanup') loadDataCleanupLogPanel();
  if (key === 'golive') loadGoLivePanel();
  if (key === 'stores') loadAdminStores(); // v105
}

function updateAdminSidebar() {
  const u = AUTH.user;
  if (!u) return;
  document.getElementById('admin-sidebar-avatar').textContent = u.initials || 'AD';
  document.getElementById('admin-sidebar-avatar').style.background = u.isSuperAdmin ? 'var(--gold)' : '#6B4C7A';
  document.getElementById('admin-sidebar-name').textContent = u.name;
  document.getElementById('admin-sidebar-role').textContent = u.isSuperAdmin ? 'Super Admin · All Locations' : `Admin · ${u.region || u.city || 'Unassigned'} Region`;
}

async function initAdminDash() {
  await loadAdminData();
  updateAdminSidebar();
  const firstAvailable = getAdminNavItems()[0];
  selectAdminSection(firstAvailable ? firstAvailable.key : 'overview');
}


function stars(n) {
  return '★'.repeat(Math.floor(n)) + (n % 1 >= 0.5 ? '½' : '') + ' ' + n;
}

// Shows a provider's real uploaded profile photo wherever their avatar
// appears, falling back to the initials-in-a-colored-circle placeholder
// only when they haven't uploaded one. `sizePx` controls both the avatar's
// dimensions and its font size (initials scale down for smaller avatars).
function avatarHTML(p, sizePx, extraStyle = '') {
  if (p.profilePhotoUrl) {
    return `<img src="${p.profilePhotoUrl}" alt="${escapeHtml(p.name)}" style="width:${sizePx}px;height:${sizePx}px;border-radius:50%;object-fit:cover;display:block;flex-shrink:0;${extraStyle}"/>`;
  }
  const fontSize = Math.round(sizePx * 0.36);
  return `<div style="width:${sizePx}px;height:${sizePx}px;border-radius:50%;background:${p.color};color:#fff;display:flex;align-items:center;justify-content:center;font-family:var(--font-display);font-weight:600;font-size:${fontSize}px;flex-shrink:0;${extraStyle}">${p.initials}</div>`;
}

function providerCardsHTML(list) {
  if (!list.length) return `<div style="grid-column:1/-1;padding:28px 0;color:var(--slate);font-size:15px;">No pros to show here yet. Try a different kind of work, or a nearby city.</div>`;
  return list.map(p => `
    <div class="provider-card" onclick="openProQuickView('${p.id}')">
      <div class="pc-top">
        ${p.profilePhotoUrl
          ? `<img src="${escapeHtml(p.profilePhotoUrl)}" alt="${escapeHtml(p.name)}" class="provider-avatar" style="object-fit:cover;"/>`
          : `<div class="provider-avatar" style="background:${p.color};color:#fff">${escapeHtml(p.initials)}</div>`}
        <div class="pc-id">
          <div class="provider-name">${escapeHtml(p.name)}</div>
          <div class="provider-role">${escapeHtml(p.role)}</div>
          ${p.verified === true ? `<div class="pc-verified">${uiIcon('check')}ID checked</div>` : ''}
          ${storeNameLine(p, 'margin-top:4px;')}
        </div>
      </div>
      <div class="provider-body">
        <div class="provider-meta">
          <div class="meta-chip"><span class="star">★</span> ${p.rating ? Number(p.rating).toFixed(1) : 'New'}</div>
          <div class="meta-chip">${uiIcon('jobs')} ${escapeHtml(p.jobs)} jobs</div>
          <div class="meta-chip">${uiIcon('pin')} ${p.distanceMiles != null ? `${distLabel(p.distanceMiles)} away` : ([escapeHtml(p.city), escapeHtml(p.country)].filter(Boolean).join(', ') || 'Location not set')}</div>
          ${p.isNewPro ? `<div class="meta-chip" title="ID checked. This pro gets a Trothen Score after their first five completed jobs.">${escapeHtml(tr('New on Trothen'))}</div>` : (p.trustScore != null ? `<div class="meta-chip" title="Trothen Score: a computed measure of this pro's reliability and track record">${uiIcon('score')} ${p.trustScore}/100</div>` : '')}
        </div>
        <div class="provider-tags">${p.tags.map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div>
        <div class="provider-footer">
          <div class="provider-price">$${p.price}<span>/hr</span></div>
          ${p.acceptingBookings === false
            ? `<span class="badge badge-neutral" style="font-size:12px;">Not taking bookings</span>`
            : `<button class="book-btn" onclick="event.stopPropagation();openBooking('${p.id}')">Book</button>`}
        </div>
      </div>
    </div>
  `).join('');
}

function renderProviders(list) {
  document.getElementById('providers-grid').innerHTML = providerCardsHTML(list);
}

function filterCat(cat) {
  const filtered = PROVIDERS.filter(p => proHasSkill(p, cat)); // v105: main skill or an extra one
  document.getElementById('providers-title').textContent = translateCategoryName(cat);
  document.getElementById('providers-sub').textContent = filtered.length
    ? `${filtered.length} ${filtered.length === 1 ? t('pro_one') : t('pro_many')}`
    : t('cat_empty');
  renderProviders(filtered);
  markResultsArrived();
  document.getElementById('providers-grid').scrollIntoView({ behavior:'smooth', block:'start' });
}

let MY_REAL_LOCATION = null; // { lat, lng } once genuinely shared — never guessed, never assumed

async function saveServiceRadius() {
  const raw = document.getElementById('set-prov-service-radius').value.trim();
  const serviceRadiusMiles = raw ? parseFloat(raw) : null;
  if (raw && (!(serviceRadiusMiles > 0) || serviceRadiusMiles > 500)) return showToast('Enter a positive number of miles (500 max), or leave it blank');
  if (!BACKEND_AVAILABLE) return showToast('Service radius saved (demo mode)');
  try {
    const { user } = await apiFetch('PATCH', '/auth/me', { serviceRadiusMiles });
    AUTH.user = user;
    showToast(serviceRadiusMiles ? `Service radius set to ${serviceRadiusMiles} miles` : 'Service radius cleared — you\'ll be shown regardless of distance');
  } catch (e) { showToast(e.message || 'Could not save service radius'); }
}

async function shareProviderLocation() {
  if (!BACKEND_AVAILABLE) return showToast('Requires a live backend connection');
  showToast('Finding your location. This can take up to 20 seconds…');
  const r = await getBestLocation({ goodEnoughM: 100, maxWaitMs: 20000 });
  if (r.error) return showToast(locationErrorMessage(r.error));
  try {
    const { user } = await apiFetch('PATCH', '/auth/me', { latitude: r.latitude, longitude: r.longitude });
    AUTH.user = user;
    showToast(`Location saved (${describeAccuracy(r.accuracyM)}). Nearby customers will see the real distance to you.`);
    selectProviderSection('settings');
  } catch (e) { showToast(e.message || 'Could not save your location'); }
}

async function clearProviderLocation() {
  if (!BACKEND_AVAILABLE) return showToast('Requires a live backend connection');
  try {
    const { user } = await apiFetch('PATCH', '/auth/me', { latitude: null, longitude: null });
    AUTH.user = user;
    showToast('Real location removed — matching falls back to your city');
    selectProviderSection('settings');
  } catch (e) { showToast(e.message || 'Could not remove your location'); }
}

async function useMyLocation() {
  const btn = document.getElementById('use-location-btn');
  const originalHTML = btn.innerHTML;
  btn.innerHTML = uiIcon('wait');
  // For searching, a rough fix is fine (which part of town), so this
  // settles quickly instead of waiting for a perfect one.
  const r = await getBestLocation({ goodEnoughM: 500, maxWaitMs: 12000 });
  if (r.error) {
    btn.innerHTML = originalHTML;
    return showToast(locationErrorMessage(r.error) + ' You can still search by typing your city.');
  }
  MY_REAL_LOCATION = { lat: r.latitude, lng: r.longitude };
  btn.innerHTML = uiIcon('check');
  document.getElementById('search-location-input').value = 'Current location';
  document.getElementById('search-location-input').readOnly = true;
  showToast('Using your location. Pros are sorted by real distance.');
  handleSearchClick();
}

function clearMyLocation() {
  MY_REAL_LOCATION = null;
  const input = document.getElementById('search-location-input');
  input.value = '';
  input.readOnly = false;
  document.getElementById('use-location-btn').innerHTML = uiIcon('locate');
}

function handleSearch(e) { if(e.key === 'Enter') handleSearchClick(); }


// A genuine, explicit choice — shown only after a real search comes back
// completely empty for someone's own country, and only acted on if they
// actually click it. Never substitutes another country's results
// automatically.
async function searchOtherCountry(country) {
  document.getElementById('providers-sub').textContent = 'Searching…';
  try {
    const result = await apiFetch('GET', `/providers?country=${encodeURIComponent(country)}`);
    document.getElementById('providers-sub').textContent = `${result.providers.length} pros found in ${country}`;
    document.getElementById('providers-grid').innerHTML =
      `<div style="grid-column:1/-1;font-size:13.5px;color:var(--slate);margin-bottom:14px;">Showing pros in ${escapeHtml(country)} — a suggestion you chose to view, not your own country's results.</div>` +
      providerCardsHTML(result.providers);
  } catch (e) { showToast('Could not load that suggestion right now'); }
}

async function handleSearchClick() {
  const q = document.getElementById('search-input').value.trim();
  const locationRaw = document.getElementById('search-location-input').value.trim();
  if (!q && !locationRaw && !MY_REAL_LOCATION) return;

  (document.getElementById('providers-section') || document.querySelector('.section')).scrollIntoView({ behavior: 'smooth' });
  document.getElementById('providers-title').textContent = q ? `Results for "${q}"` : 'Pros near you';
  document.getElementById('providers-sub').textContent = 'Searching…';

  // Parse "City, State" or just "City" from the free-text location field.
  // Country comes from the signed-in user's account if we have it — an
  // anonymous visitor typing a location has no country context to expand
  // within, so their search only narrows by city/state text matching
  // against whatever's already loaded, rather than hitting the real
  // country-scoped endpoint.
  let cityPart = '', statePart = '';
  if (locationRaw && !MY_REAL_LOCATION) {
    const parts = locationRaw.split(',').map(s => s.trim());
    cityPart = parts[0] || '';
    statePart = parts[1] || '';
  }
  const country = (AUTH.user && AUTH.user.country) || null;

  if (BACKEND_AVAILABLE && (country || MY_REAL_LOCATION)) {
    try {
      const params = new URLSearchParams();
      if (q) params.set('q', q);
      if (cityPart) params.set('city', cityPart);
      if (statePart) params.set('state', statePart);
      if (country) params.set('country', country);
      if (MY_REAL_LOCATION) { params.set('lat', MY_REAL_LOCATION.lat); params.set('lng', MY_REAL_LOCATION.lng); }
      const result = await apiFetch('GET', `/providers?${params.toString()}`);
      const scopeNote = result.locationScope === 'state'
        ? `<div style="grid-column:1/-1;font-size:13.5px;color:var(--gold);background:var(--offwhite);border:1px dashed var(--gold);border-radius:8px;padding:8px 12px;margin-bottom:14px;">📍 No matches in ${cityPart} yet, so we widened to your state/region.</div>`
        : result.locationScope === 'country'
        ? (cityPart ? `<div style="grid-column:1/-1;font-size:13.5px;color:var(--gold);background:var(--offwhite);border:1px dashed var(--gold);border-radius:8px;padding:8px 12px;margin-bottom:14px;">📍 No matches nearby yet, so we widened the search to all of ${country}.</div>` : '')
        : result.locationScope === 'country_empty'
        ? `<div style="grid-column:1/-1;font-size:13.5px;color:var(--navy);background:var(--offwhite);border:1px dashed var(--border);border-radius:8px;padding:12px 14px;margin-bottom:14px;">📍 No pros in ${country} yet for this search.${result.suggestedCountry ? ` <a onclick="searchOtherCountry('${result.suggestedCountry}')" style="cursor:pointer;font-weight:600;">Would you like to see pros in ${result.suggestedCountry} instead?</a> This is only a suggestion — nothing is booked or shown automatically.` : ''}</div>`
        : '';
      document.getElementById('providers-sub').textContent = `${result.providers.length} pros found`;
      document.getElementById('providers-grid').innerHTML = scopeNote + (result.providers.length || !scopeNote ? providerCardsHTML(result.providers) : '');
      markResultsArrived();
      return;
    } catch (e) {
      console.warn('Real location search failed, falling back to local filtering', e);
    }
  }

  // Fallback: no location typed, not signed in, or the real search call
  // failed — filter whatever's already loaded client-side instead of
  // showing nothing.
  const needle = q.toLowerCase();
  const synonymCategories = categoriesForSearchTerm(needle);
  let match = q ? PROVIDERS.filter(p => p.cat.toLowerCase().includes(needle) || p.role.toLowerCase().includes(needle) || p.tags.some(t => t.toLowerCase().includes(needle)) || synonymCategories.includes(p.cat) || (p.skills || []).some(sk => sk.toLowerCase().includes(needle) || synonymCategories.includes(sk))) : PROVIDERS.slice();
  if (cityPart) match = match.filter(p => (p.city || '').toLowerCase().includes(cityPart.toLowerCase()));
  document.getElementById('providers-sub').textContent = `${match.length} pros found`;
  renderProviders(match);
  markResultsArrived();
}

// ── RESUME-AFTER-AUTH ────────────────────────────────────────────────────
// When openBooking() has to redirect an anonymous (or wrong-role) visitor
// to sign in/sign up, this remembers what they were actually trying to do
// so they land back on that exact booking form the moment they're
// authenticated — instead of a real customer completing signup and just
// being dropped on a generic empty dashboard, having to go find the same
// provider again. Persisted to localStorage (not just an in-memory
// variable) so it survives even if the two-step signup verification
// somehow spans a page reload.
function setPendingBookingIntent(providerId) {
  try { localStorage.setItem('trothen_pending_intent', JSON.stringify({ type: 'book', providerId })); } catch (e) { /* private browsing etc. — booking just won't auto-resume, no crash */ }
}
function getPendingBookingIntent() {
  try { return JSON.parse(localStorage.getItem('trothen_pending_intent') || 'null'); } catch (e) { return null; }
}
function clearPendingBookingIntent() {
  try { localStorage.removeItem('trothen_pending_intent'); } catch (e) { /* ignore */ }
}

// Remembers the email of whoever last signed in/up successfully ON THIS
// DEVICE — not a session, just enough to recognize "this looks like a
// returning visitor" so a booking redirect can default to Sign In
// (pre-filled) instead of guessing Sign Up for someone who actually
// already has an account. Never stores a password, and this is purely a
// convenience default — a first-time visitor on a shared/public computer
// isn't affected since nothing's been remembered on that device yet.
function rememberLastLoginEmail(email, role) {
  try {
    localStorage.setItem('trothen_last_email', email);
    localStorage.setItem('trothen_last_role', role || '');
  } catch (e) { /* ignore */ }
}
function getLastLoginEmail() {
  try { return localStorage.getItem('trothen_last_email'); } catch (e) { return null; }
}
// Specifically for contexts like "continue booking a provider" — only
// ever meaningful for a customer account. Suggesting a remembered admin
// or provider email here would be nonsensical (they can't book a service
// as themselves) and would expose whose account that is to anyone using
// a shared device, so this returns null for any non-customer role rather
// than the email itself.
function getLastCustomerLoginEmail() {
  try {
    const role = localStorage.getItem('trothen_last_role');
    return role === 'customer' ? localStorage.getItem('trothen_last_email') : null;
  } catch (e) { return null; }
}

// After a real sign-in or sign-up completes, resume whatever the visitor
// was actually trying to do (right now: booking a specific provider)
// instead of unconditionally dropping them on a generic dashboard. Falls
// through to the normal dashboard exactly as before whenever there's no
// pending intent — a direct, ordinary login is completely unaffected.
function showForcePasswordChangeScreen() {
  showScreen('screen-force-password-change');
  renderNavbar('navbar-force-password-change', 'auth');
  document.getElementById('force-pw-current').value = '';
  document.getElementById('force-pw-new').value = '';
  document.getElementById('force-pw-confirm').value = '';
}

async function submitForcePasswordChange() {
  const currentPassword = document.getElementById('force-pw-current').value;
  const newPassword = document.getElementById('force-pw-new').value;
  const confirm = document.getElementById('force-pw-confirm').value;
  if (!currentPassword || !newPassword || !confirm) return showToast('Fill in all three password fields');
  if (newPassword.length < 8 || newPassword.length > 72) return showToast('New password must be 8-72 characters');
  if (newPassword !== confirm) return showToast("New passwords don't match");
  try {
    const data = await apiFetch('POST', '/auth/change-password', { currentPassword, newPassword });
    AUTH.token = data.token;
    saveAuthSession(data.token);
    AUTH.user = { ...AUTH.user, mustChangePassword: false };
    showToast('Password set — welcome to Trothen!');
    await completeAuthAndResumeIntent(AUTH.user.role);
  } catch (e) {
    showToast(e.message || 'Could not set your new password');
  }
}

async function completeAuthAndResumeIntent(role) {
  if (AUTH.user && AUTH.user.mustChangePassword) {
    return showForcePasswordChangeScreen();
  }
  startIdleTimer();
  loadSupportContact().catch(() => {});
  const intent = getPendingBookingIntent();
  if (intent && intent.type === 'book' && role === 'customer') {
    clearPendingBookingIntent();
    const provider = PROVIDERS.find(p => p.id === intent.providerId);
    if (provider) {
      checkTermsGate(role); // this path skips goDashboard(), the only other place this fires — never skip the agreement screen just because someone signed up mid-booking
      showToast(`Welcome! Continuing your booking with ${provider.name}...`);
      await openBooking(intent.providerId);
      return;
    }
    // The provider's no longer around (removed/deactivated since) — fall
    // through to the normal dashboard rather than silently doing nothing.
  }
  await goDashboard(role);
  // Set when the page was opened from the "verify your identity" email
  // link (?verify=1). Lands the person on the real verification form
  // right after sign-in instead of the dashboard's default tab.
  if (OPEN_VERIFICATION_AFTER_AUTH) {
    OPEN_VERIFICATION_AFTER_AUTH = false;
    if (role === 'provider') selectProviderSection('verification');
    else if (role === 'customer') goToCustomerDashboard('verification'); // v75: same fix for the email link
  }
}
let OPEN_VERIFICATION_AFTER_AUTH = false;

let bookingPricingChoice = null; // 'hourly' | 'offer' — only meaningful when the provider's pricingModel is 'both'

function setBookingPricingChoice(choice) {
  bookingPricingChoice = choice;
  setTimeout(() => { if (BOOKING_BASKET_PRICED) drawBookingGoods(); }, 0); // v105
  document.getElementById('booking-pricing-opt-hourly').classList.toggle('active', choice === 'hourly');
  document.getElementById('booking-pricing-opt-offer').classList.toggle('active', choice === 'offer');
  renderBookingPricingBody();
}

function renderBookingPricingBody() {
  const target = document.getElementById('booking-pricing-body');
  if (!target) return;
  if (bookingPricingChoice === 'offer') {
    target.innerHTML = `
      <div class="summary-row"><span>Pricing</span><span>Your Offer</span></div>
      <div class="form-group" style="margin-top:10px;"><label class="form-label">Your Offer ($)</label><input class="form-input" type="number" min="1" placeholder="e.g. 120" id="job-offer-amount" oninput="updateCurrencyPreview()"/></div>
      <div class="summary-row"><span>Service fee</span><span id="offer-service-fee">Calculated from your offer</span></div>
      <div class="summary-row total"><span>Total charged</span><span id="offer-total-charged">Set once your offer is entered</span></div>
      ${currencyToggleHTML()}
    `;
  } else {
    const jobAmount = currentPro.price * 2;
    const fee = Math.round(Math.min(Math.max(jobAmount * 0.09, 2.99), 25) * 100) / 100;
    target.innerHTML = `
      <div class="summary-row"><span>Service rate</span><span>$${currentPro.price}/hr</span></div>
      <div class="summary-row"><span>Job amount (2hr)</span><span>$${jobAmount}</span></div>
      <div class="summary-row"><span>Service fee <small style="color:var(--muted);">(9%, $2.99–$25)</small></span><span>$${fee.toFixed(2)}</span></div>
      <div class="summary-row"><span>Smart Contract</span><span style="color:#2E8C6F">Included ✓</span></div>
      <div class="summary-row total"><span>Total charged</span><span>$${(jobAmount + fee).toFixed(2)}</span></div>
      ${currencyToggleHTML()}
    `;
  }
}

async function openBooking(id) {
  currentPro = PROVIDERS.find(p => p.id === id);

  // A booking has to belong to a real signed-in customer — check this
  // BEFORE showing any part of the form, not after someone's already
  // filled out the job description, date, address, and materials advance
  // and only discovers they need an account at the final "Confirm & Pay"
  // step. Same rule confirmBooking() already enforced at submission —
  // just moved to where a visitor actually needs to see it.
  if (BACKEND_AVAILABLE && (!AUTH.token || AUTH.user.role !== 'customer')) {
    setPendingBookingIntent(id);
    if (!AUTH.token) {
      const lastEmail = getLastCustomerLoginEmail();
      if (lastEmail) {
        // This browser has signed in before — much more likely a returning
        // visitor than a brand-new one, so default to Sign In (pre-filled)
        // instead of guessing Sign Up and making them switch tabs.
        showAuth('login');
        const emailInput = document.getElementById('auth-email');
        if (emailInput) emailInput.value = lastEmail;
        showToast(`Sign in as ${lastEmail} to continue booking ${currentPro.name}`);
      } else {
        showAuth('signup');
        setAuthRole('customer');
        showToast('Create a free customer account to book a pro');
      }
    } else {
      showAuth('login');
      showToast('Sign in as a customer to book a pro');
    }
    return;
  }

  const availability = currentPro.availability && currentPro.availability.length ? currentPro.availability : ['Morning (8–12pm)', 'Afternoon (12–5pm)', 'Evening (5–8pm)'];
  const isNegotiable = currentPro.pricingModel === 'negotiable';

  JOB_PHOTO_STATE.booking = [];
  // v92: fresh "Where is the job?" block each time the booking form opens.
  JOB_PIN.book = null;
  { const slot = document.getElementById('book-where-slot'); if (slot) slot.innerHTML = locationPickerHTML('book'); }
  document.getElementById('booking-photo-upload-container').innerHTML = jobPhotoUploadHTML('booking');

  document.getElementById('modal-pro-name').textContent = 'Book ' + currentPro.name;
  document.getElementById('modal-pro-role').textContent = currentPro.role + (isNegotiable ? ' · Mutual Agreement' : ' · $' + currentPro.price + '/hr');

  // Previously this forced the customer to pick one of the provider's own
  // availability labels as the "time" — meaning even a provider who'd set
  // real windows still only ever gave a customer a coarse range, never an
  // actual time. Now it's shown as context under a real time input
  // instead of being the only option: the customer picks the exact time
  // they actually want, and can see when this provider tends to be free.
  document.getElementById('job-time').value = '';
  document.getElementById('job-time-availability-note').textContent = `${currentPro.name.split(' ')[0]}'s usual availability: ${availability.join(', ')}`;

  // Real currency choice — only shown when the signed-in customer's actual
  // country uses a non-USD currency. The contract is always denominated in
  // USD (that stays the accounting figure of record); this only affects
  // what currency they actually pay in, converted at time of payment.
  currentCurrencyInfo = null;
  if (BACKEND_AVAILABLE && AUTH.token && AUTH.user && AUTH.user.role === 'customer') {
    try {
      const hourlyTotal = currentPro.price * 2 + Math.round(currentPro.price * 0.08);
      currentCurrencyInfo = await apiFetch('GET', `/currency/mine?amount=${hourlyTotal}`);
    } catch (e) { console.warn('Could not load currency info', e); }
  }

  const isBothPricing = currentPro.pricingModel === 'both';
  bookingPricingChoice = isBothPricing ? 'hourly' : null; // customer's choice when the provider allows either
  if (isBothPricing) {
    document.getElementById('booking-summary').innerHTML = `
      <div class="auth-role-grid" style="grid-template-columns:1fr 1fr;margin-bottom:12px;">
        <div class="auth-role-opt active" id="booking-pricing-opt-hourly" onclick="setBookingPricingChoice('hourly')"><span class="r-icon">⏱️</span>Hourly Rate</div>
        <div class="auth-role-opt" id="booking-pricing-opt-offer" onclick="setBookingPricingChoice('offer')"><span class="r-icon">🤝</span>Make an Offer</div>
      </div>
      <div id="booking-pricing-body"></div>
    `;
    renderBookingPricingBody();
  } else if (isNegotiable) {
    document.getElementById('booking-summary').innerHTML = `
      <div class="summary-row"><span>Pricing</span><span>Mutual Agreement</span></div>
      <div class="form-group" style="margin-top:10px;"><label class="form-label">Your Offer ($)</label><input class="form-input" type="number" min="1" placeholder="e.g. 120" id="job-offer-amount" oninput="updateCurrencyPreview()"/></div>
      <div class="summary-row"><span>Service fee</span><span id="offer-service-fee">Calculated from your offer</span></div>
      <div class="summary-row total"><span>Total charged</span><span id="offer-total-charged">Set once your offer is entered</span></div>
      ${currencyToggleHTML()}
    `;
  } else {
    const jobAmount = currentPro.price * 2;
    const fee = Math.round(Math.min(Math.max(jobAmount * 0.09, 2.99), 25) * 100) / 100;
    document.getElementById('booking-summary').innerHTML = `
      <div class="summary-row"><span>Service rate</span><span>$${currentPro.price}/hr</span></div>
      <div class="summary-row"><span>Job amount (2hr)</span><span>$${jobAmount}</span></div>
      <div class="summary-row"><span>Service fee <small style="color:var(--muted);">(9%, $2.99–$25)</small></span><span>$${fee.toFixed(2)}</span></div>
      <div class="summary-row"><span>Smart Contract</span><span style="color:#2E8C6F">Included ✓</span></div>
      <div class="summary-row total"><span>Total charged</span><span>$${(jobAmount + fee).toFixed(2)}</span></div>
      ${currencyToggleHTML()}
    `;
  }
  // Default date to tomorrow
  const d = new Date(); d.setDate(d.getDate()+1);
  document.getElementById('job-date').value = d.toISOString().split('T')[0];

  // Only shown when the customer actually has enough points — never a
  // checkbox offering a discount they haven't earned.
  const loyaltyRow = document.getElementById('booking-loyalty-row');
  if (loyaltyRow) {
    if (AUTH.user && (AUTH.user.loyaltyPoints || 0) >= 25) {
      loyaltyRow.style.display = 'block';
      loyaltyRow.innerHTML = `<label style="display:flex;align-items:center;gap:8px;font-size:13.5px;cursor:pointer;"><input type="checkbox" id="booking-use-loyalty-points"/> 🎁 Use 25 loyalty points for a free booking (waives the service fee — you have ${AUTH.user.loyaltyPoints})</label>`;
    } else {
      loyaltyRow.style.display = 'none';
      loyaltyRow.innerHTML = '';
    }
  }
  // v105: goods picked in this pro's store, if any.
  BOOKING_GOODS_ONLY = window.__nextBookingGoodsOnly === true && basketCount(currentPro.id) > 0;
  window.__nextBookingGoodsOnly = false;
  document.getElementById('booking-modal').classList.add('open');
  renderBookingGoods();
}

// Only rendered when the customer's real country uses a non-USD currency —
// an American customer never sees a currency choice, since there's nothing
// to choose between.
function currencyToggleHTML() {
  if (!currentCurrencyInfo || currentCurrencyInfo.isUSD) return '';
  const c = currentCurrencyInfo.currency;
  return `
    <div class="form-group" style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border);">
      <label class="form-label">Pay in</label>
      <div style="display:flex;gap:8px;">
        <button type="button" class="btn-sm btn-sm-primary" id="pay-currency-local-btn" onclick="setPayCurrency('local')" style="flex:1;">${c.symbol} ${escapeHtml(c.name)}</button>
        <button type="button" class="btn-sm btn-sm-outline" id="pay-currency-usd-btn" onclick="setPayCurrency('usd')" style="flex:1;">$ USD</button>
      </div>
      <div id="currency-preview" style="font-size:13px;color:var(--muted);margin-top:6px;"></div>
    </div>`;
}

let selectedPayCurrency = 'local';
function setPayCurrency(choice) {
  selectedPayCurrency = choice;
  document.getElementById('pay-currency-local-btn').className = choice === 'local' ? 'btn-sm btn-sm-primary' : 'btn-sm btn-sm-outline';
  document.getElementById('pay-currency-usd-btn').className = choice === 'usd' ? 'btn-sm btn-sm-primary' : 'btn-sm btn-sm-outline';
  updateCurrencyPreview();
}

async function updateCurrencyPreview() {
  const offerInput = document.getElementById('job-offer-amount');
  const feeEl = document.getElementById('offer-service-fee');
  const totalEl = document.getElementById('offer-total-charged');
  if (offerInput && feeEl && totalEl) {
    const offerAmount = parseFloat(offerInput.value) || 0;
    if (offerAmount > 0) {
      const fee = Math.round(Math.min(Math.max(offerAmount * 0.09, 2.99), 25) * 100) / 100;
      feeEl.textContent = `$${fee.toFixed(2)} (9%, $2.99–$25)`;
      totalEl.textContent = `$${(offerAmount + fee).toFixed(2)}`;
    } else {
      feeEl.textContent = 'Calculated from your offer';
      totalEl.textContent = 'Set once your offer is entered';
    }
  }
  if (BOOKING_BASKET_PRICED) drawBookingGoods(); // v105: keep the total with goods in step with the offer
  const preview = document.getElementById('currency-preview');
  if (!preview || !currentCurrencyInfo || currentCurrencyInfo.isUSD) return;
  const c = currentCurrencyInfo.currency;
  if (selectedPayCurrency === 'usd') {
    preview.textContent = 'You will be charged in US dollars.';
    return;
  }
  const amount = offerInput ? parseFloat(offerInput.value) || 0 : (currentPro.price * 2 + Math.round(currentPro.price * 0.08));
  if (!amount) { preview.textContent = ''; return; }
  try {
    const data = await apiFetch('GET', `/currency/mine?amount=${amount}`);
    preview.textContent = data.convertedAmount
      ? `≈ ${c.symbol}${data.convertedAmount} ${c.code} (${data.exchangeRateNote})`
      : '';
  } catch (e) { preview.textContent = ''; }
}

function closeModal() {
  document.getElementById('booking-modal').classList.remove('open');
}

async function confirmBooking() {
  const desc = document.getElementById('job-desc').value.trim();
  const date = document.getElementById('job-date').value;
  const rawTime = document.getElementById('job-time').value;
  const time = rawTime ? new Date(`2000-01-01T${rawTime}`).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : '';
  const addr = document.getElementById('job-address').value.trim();

  // Client-side validation — mirrors what the backend requires, so the user
  // gets immediate feedback instead of a confusing failure after the modal
  // has already closed.
  const goods = bookingGoodsPayload(); // v105: goods from the pro's store, if any
  const goodsOnly = goods.goodsOnly === true;
  if (!goodsOnly && (!desc || desc.length < 3)) return showToast('Describe the job in at least 3 characters');
  if (!date) return showToast('Pick a date for the job');
  if (!time) return showToast('Pick a time for the job');
  const bookWhere = readJobWhere('book'); // v92: a pin or a landmark is enough where there is no street address
  if ((!addr || addr.length < 5) && !bookWhere.jobLocation && !(bookWhere.landmark && bookWhere.landmark.length >= 5)) return showToast('Tell your pro where the job is: pin the location, describe a landmark, or type an address');

  // A booking has to belong to a real signed-in customer — never silently
  // create a session behind the scenes. If nobody's signed in (or they're
  // signed in as a provider/admin), send them to sign in/sign up instead of
  // completing the booking, so the confirmation screen always reflects a
  // real account, not a guest slipped into a shared demo login.
  if (BACKEND_AVAILABLE && (!AUTH.token || AUTH.user.role !== 'customer')) {
    closeModal();
    showAuth('login');
    showToast('Sign in as a customer to complete your booking');
    return;
  }

  // v105: "total" is now the job amount itself. It used to be sent with an
  // extra 8% added on top, while the form showed the job amount plus the
  // 9% service fee, so the booking came out higher than the form said.
  // The server adds the service fee; the page no longer adds anything.
  let total;
  const wantsOffer = !goodsOnly && (currentPro.pricingModel === 'negotiable' || (currentPro.pricingModel === 'both' && bookingPricingChoice === 'offer'));
  if (goodsOnly) {
    total = 0;
  } else if (wantsOffer) {
    const offer = parseFloat(document.getElementById('job-offer-amount').value);
    if (!offer || offer <= 0) return showToast('Enter your offer amount');
    total = Math.round(offer * 100) / 100;
  } else {
    total = currentPro.price * 2;
  }
  const materialsAdvanceInput = document.getElementById('job-materials-advance').value;
  const materialsAdvance = (materialsAdvanceInput && !goodsOnly) ? parseFloat(materialsAdvanceInput) : 0;
  if (materialsAdvance < 0) return showToast('Materials advance can\'t be negative');
  if (materialsAdvance > total) return showToast('The materials advance can\'t be more than the total job amount');
  const photoUrls = getUploadedJobPhotoUrls('booking');
  let contractId = 'CT-' + Math.floor(1000 + Math.random() * 9000);
  let isPendingOffer = false;
  let savedContract = null; // v105: what the server actually recorded

  if (BACKEND_AVAILABLE) {
    try {
      const { contract } = await apiFetch('POST', '/contracts', {
        providerId: currentPro.id, service: goodsOnly ? undefined : desc, date, time, address: addr, ...bookWhere, amount: goodsOnly ? undefined : total, ...goods, payCurrency: selectedPayCurrency, materialsAdvance, photoUrls: goodsOnly ? [] : photoUrls, isOffer: wantsOffer, useLoyaltyPoints: !!document.getElementById('booking-use-loyalty-points')?.checked, materialsOnHand: document.getElementById('job-materials-on-hand')?.value.trim() || undefined,
      });
      contractId = contract.bookingNumber || contract.id;
      isPendingOffer = contract.status === 'pending_agreement';
      savedContract = contract;
      delete STORE_BASKET[currentPro.id]; BOOKING_GOODS_ONLY = false; // v105: the basket is now a booking
    } catch (e) {
      // A real failure (validation error, server down, etc.) must NOT show a
      // fake success screen — that would tell the user their booking is
      // confirmed and protected by escrow when nothing was actually saved.
      showToast(e.message || 'Could not complete booking — please try again');
      return;
    }
  }

  closeModal();

  // Show confirmation screen
  document.getElementById('screen-home').classList.remove('active');
  const confirmScreen = document.getElementById('screen-confirm');
  confirmScreen.classList.add('active');
  renderNavbar('navbar-confirm', 'home');

  // A Mutual Agreement offer isn't a confirmed booking yet — no escrow
  // exists until the provider actually accepts this specific amount, so the
  // confirmation screen has to say that honestly rather than claiming funds
  // are held when they aren't.
  document.getElementById('confirm-details').innerHTML = isPendingOffer ? `
    <div class="confirm-detail"><span>Booking #</span><strong>${contractId}</strong></div>
    <div class="confirm-detail"><span>Pro</span><strong>${escapeHtml(currentPro.name)}</strong></div>
    <div class="confirm-detail"><span>Service</span><strong>${escapeHtml(desc)}</strong></div>
    <div class="confirm-detail"><span>Date</span><strong>${escapeHtml(date)} · ${escapeHtml(time)}</strong></div>
    <div class="confirm-detail"><span>${escapeHtml(tr('Where'))}</span><strong>${escapeHtml(savedContract ? savedContract.address : addr)}</strong></div>
    <div class="confirm-detail"><span>Your Offer</span><strong>$${total}</strong></div>
    ${confirmGoodsRows(savedContract)}
    <div class="confirm-detail"><span>Status</span><strong style="color:var(--gold)">⏳ Awaiting ${escapeHtml(currentPro.name)}'s response</strong></div>
  ` : `
    <div class="confirm-detail"><span>Booking #</span><strong>${contractId}</strong></div>
    <div class="confirm-detail"><span>Pro</span><strong>${escapeHtml(currentPro.name)}</strong></div>
    <div class="confirm-detail"><span>Service</span><strong>${escapeHtml(savedContract ? savedContract.service : desc)}</strong></div>
    <div class="confirm-detail"><span>Date</span><strong>${escapeHtml(date)} · ${escapeHtml(time)}</strong></div>
    <div class="confirm-detail"><span>${escapeHtml(tr('Where'))}</span><strong>${escapeHtml(savedContract ? savedContract.address : addr)}</strong></div>
    ${confirmGoodsRows(savedContract)}
    <div class="confirm-detail"><span>Escrow held</span><strong>${savedContract ? usd2(savedContract.amount) : '$' + total}</strong></div>
    ${savedContract ? `<div class="confirm-detail"><span>${escapeHtml(tr('Fees to Trothen'))}</span><strong>${usd2(savedContract.serviceFee)}</strong></div><div class="confirm-detail"><span>${escapeHtml(tr('Total charged'))}</span><strong>${usd2(savedContract.amount + savedContract.serviceFee)}</strong></div>` : ''}
    <div class="confirm-detail"><span>Contract</span><strong style="color:#2E8C6F">Auto-Generated ✓</strong></div>
  `;
  window.scrollTo(0,0);
}

function showToast(msg) {
  const t = document.getElementById('toast');
  document.getElementById('toast-msg').textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 3000);
}

// Real in-app confirm dialog — replaces native browser confirm() popups,
// which can't be styled, freeze the whole page/tab while open, and which
// browsers can start silently auto-dismissing after a few fire in a row
// from the same page (meaning a real "are you sure you want to delete
// this" could just silently vanish and do nothing, or worse, silently
// resolve as if cancelled). Promise-based so every call site keeps its
// existing `if (!(await confirmDialog(...))) return;` shape — the same
// shape the native confirm() calls already had, just awaited.
// options.danger switches the confirm button to a red/destructive style
// for irreversible actions (deletes), leaving it as the normal primary
// style otherwise.
// Item: a real, live bug found while fixing this — the backend for
// verification rejections has required a typed reason since it was
// built (see POST /admin/verification/:id/decide), but the frontend
// never actually collected or sent one, so every reject click there was
// silently failing with a 400. requireTextInput adds a real textarea to
// this same modal instead of building a second one: resolves with the
// trimmed text on Confirm (validated non-empty first — Confirm just
// shakes the field and refuses to close if it's blank), or null on
// Cancel/Escape/overlay-click, in place of the usual true/false.
// Item: real idle-timeout sign-out. A person is warned 60 seconds before
// being signed out for real inactivity, with a live countdown and a
// clear way to stay signed in — never a silent logout, which would just
// look like a broken app to whoever it happens to. 20 minutes idle is
// the actual trigger point; chosen because this app holds real escrow
// payments and identity documents, not a low-stakes browsing site where
// a much longer timeout would be reasonable.
const IDLE_TIMEOUT_MS = 20 * 60 * 1000;
const IDLE_WARNING_MS = 60 * 1000;
let idleLastActivityAt = Date.now();
let idleCheckInterval = null;
let idleWarningShowing = false;
const idleActivityListenerOptions = { passive: true };

function idleRecordActivity() {
  idleLastActivityAt = Date.now();
}

function idleCheckTick() {
  if (!AUTH.token) return; // nothing to protect if nobody's signed in
  const idleFor = Date.now() - idleLastActivityAt;
  if (idleFor >= IDLE_TIMEOUT_MS) {
    stopIdleTimer();
    document.getElementById('idle-warning-modal').classList.remove('open');
    idleWarningShowing = false;
    showToast('Signed out after 20 minutes of inactivity');
    logout();
    return;
  }
  const remainingMs = IDLE_TIMEOUT_MS - idleFor;
  if (remainingMs <= IDLE_WARNING_MS) {
    if (!idleWarningShowing) {
      idleWarningShowing = true;
      document.getElementById('idle-warning-modal').classList.add('open');
    }
    document.getElementById('idle-warning-countdown').textContent = Math.max(1, Math.ceil(remainingMs / 1000));
  } else if (idleWarningShowing) {
    // Real activity came in while the warning was up (moving the mouse,
    // typing) — dismiss it rather than forcing an explicit button click
    // for every single kind of "still here" signal.
    idleWarningShowing = false;
    document.getElementById('idle-warning-modal').classList.remove('open');
  }
}

// Started once, right after a real sign-in (see completeAuthAndResumeIntent)
// or a restored session on page load — never for an anonymous visitor,
// since there's no session to protect yet.
function startIdleTimer() {
  stopIdleTimer(); // never stack a second set of listeners on repeated logins
  idleRecordActivity();
  ['mousemove', 'mousedown', 'keydown', 'touchstart', 'scroll', 'click'].forEach(evt => {
    document.addEventListener(evt, idleRecordActivity, idleActivityListenerOptions);
  });
  idleCheckInterval = setInterval(idleCheckTick, 2000);
  document.getElementById('idle-warning-stay-btn').onclick = () => {
    idleRecordActivity();
    idleWarningShowing = false;
    document.getElementById('idle-warning-modal').classList.remove('open');
  };
}

function stopIdleTimer() {
  ['mousemove', 'mousedown', 'keydown', 'touchstart', 'scroll', 'click'].forEach(evt => {
    document.removeEventListener(evt, idleRecordActivity, idleActivityListenerOptions);
  });
  if (idleCheckInterval) { clearInterval(idleCheckInterval); idleCheckInterval = null; }
  idleWarningShowing = false;
}

function confirmDialog(message, options = {}) {
  return new Promise((resolve) => {
    const overlay = document.getElementById('confirm-dialog-modal');
    const confirmBtn = document.getElementById('confirm-dialog-confirm-btn');
    const cancelBtn = document.getElementById('confirm-dialog-cancel-btn');
    const textInput = document.getElementById('confirm-dialog-textinput');
    const textError = document.getElementById('confirm-dialog-textinput-error');
    document.getElementById('confirm-dialog-message').textContent = message;
    confirmBtn.textContent = options.confirmLabel || 'Confirm';
    confirmBtn.style.background = options.danger ? '#C1554D' : '';
    confirmBtn.style.color = options.danger ? '#fff' : '';
    confirmBtn.className = options.danger ? 'btn-sm' : 'btn-sm btn-sm-primary';
    textInput.style.display = options.requireTextInput ? 'block' : 'none';
    textInput.value = '';
    textError.style.display = 'none';
    if (options.requireTextInput) setTimeout(() => textInput.focus(), 50);

    let settled = false;
    const cleanup = (result) => {
      if (settled) return; // a click and a keydown could both fire for the same dismissal — only resolve once
      settled = true;
      overlay.classList.remove('open');
      confirmBtn.removeEventListener('click', onConfirm);
      cancelBtn.removeEventListener('click', onCancel);
      overlay.removeEventListener('click', onOverlayClick);
      document.removeEventListener('keydown', onKeydown);
      resolve(result);
    };
    const onConfirm = () => {
      if (options.requireTextInput) {
        const text = textInput.value.trim();
        if (text.length < 3) { textError.style.display = 'block'; textInput.focus(); return; }
        cleanup(text);
      } else {
        cleanup(true);
      }
    };
    const onCancel = () => cleanup(options.requireTextInput ? null : false);
    const onOverlayClick = (e) => { if (e.target === overlay) cleanup(options.requireTextInput ? null : false); };
    const onKeydown = (e) => { if (e.key === 'Escape') cleanup(options.requireTextInput ? null : false); };

    confirmBtn.addEventListener('click', onConfirm);
    cancelBtn.addEventListener('click', onCancel);
    overlay.addEventListener('click', onOverlayClick);
    document.addEventListener('keydown', onKeydown);
    overlay.classList.add('open');
  });
}

// Close modal on overlay click
document.getElementById('booking-modal').addEventListener('click', function(e) {
  if (e.target === this) closeModal();
});
document.getElementById('postjob-modal').addEventListener('click', function(e) {
  if (e.target === this) closePostJobModal();
});
document.getElementById('dispute-modal').addEventListener('click', function(e) {
  if (e.target === this) closeDisputeModal();
});

// Init
/* ══════════════════════ AI SUPPORT CHAT ══════════════════════
   This is a real, working assistant right now — a rule-based FAQ engine
   with no external dependency, so it's fully functional out of the box.
   It is NOT a general-purpose LLM. If you want open-ended AI answers later,
   this is the function to replace (sendSupportChatMessage) — swap the
   keyword matching below for a call to an LLM API (e.g. the Anthropic API),
   which needs its own API key and a small cost per message, so it's kept
   separate from this always-available baseline rather than silently
   assumed. */
// ── SUPPORT CONTACT INFO ──────────────────────────────────────────────────
// The real numbers live in the database now (Settings → Platform Settings,
// super admin only) — this starts as the same obviously-fake placeholder
// as before, purely as a fallback in case the fetch below hasn't completed
// yet, and gets replaced with the real value (or confirmed still-a-
// placeholder) as soon as loadSupportContact() resolves.
let SUPPORT_CONTACT = {
  whatsapp: '15551234567',
  phoneDisplay: '+1 (555) 123-4567',
  isPlaceholder: true,
};
async function loadSupportContact() {
  if (!BACKEND_AVAILABLE) return;
  try {
    const city = (AUTH.user && AUTH.user.city) ? `?city=${encodeURIComponent(AUTH.user.city)}` : '';
    const data = await apiFetch('GET', `/support-contact${city}`);
    SUPPORT_CONTACT = data;
  } catch (e) { console.warn('Could not load support contact info, using placeholder.', e); }
}

// The site footer — previously hardcoded text repeated in five places in
// this file, with no way to correct it without a code deploy. Now a real,
// admin-editable setting (Settings → Platform Settings → Site Footer);
// this fetches the current version and updates every footer on the page
// to match, the same "paint the static fallback immediately, then upgrade
// once the real backend value loads" approach already used for support
// contact info and homepage copy.
let FOOTER_INFO = null;
// v95: the support chat names the same address as the footer, Terms and Privacy Policy.
function supportEmailLineHTML() {
  const e = FOOTER_INFO && FOOTER_INFO.supportEmail ? String(FOOTER_INFO.supportEmail).trim() : '';
  return e ? '<br/><br/>Or email ' + escapeHtml(e) + '.' : '';
}
function footerLine() {
  if (!FOOTER_INFO) return null;
  return `© ${FOOTER_INFO.copyrightYear} ${FOOTER_INFO.companyName} · ${FOOTER_INFO.location} · ${FOOTER_INFO.supportEmail}`;
}
async function loadFooterInfo() {
  if (!BACKEND_AVAILABLE) return;
  try {
    const { footer } = await apiFetch('GET', '/footer');
    FOOTER_INFO = footer;
    const line = footerLine();
    if (line) document.querySelectorAll('.footer-text').forEach(el => { el.textContent = line; });
  } catch (e) { console.warn('Could not load footer info, using placeholder.', e); }
}

// Homepage copy — hero prefix/rotating word/suffix/subheadline and the
// mission section — is real, admin-editable content (Settings → Platform
// Settings), not hardcoded. This fetches the current version and starts
// the rotating-word cycle; falls back to whatever's already in the static
// HTML (the same defaults) if the fetch fails for any reason.
let HERO_ROTATING_WORDS = ['pros', 'plumbers', 'cleaners', 'tutors', 'electricians', 'painters'];
let heroRotationTimer = null;
async function loadHomepageContent() {
  if (!BACKEND_AVAILABLE) return;
  // v86: the "Live now in" strip is drawn FIRST and on its own. It used to
  // be the last step of this function, so if the homepage request failed,
  // or anything earlier in here stumbled, the strip silently stayed
  // hidden. Now it has its own request path and a fallback: the list of
  // countries open for sign-up (which is the same "live" list).
  let content = null;
  try { content = await apiFetch('GET', '/homepage-content'); }
  catch (e) { console.warn('Could not load homepage content, using defaults.', e); }
  try {
    let live = content && Array.isArray(content.featuredCountries) ? content.featuredCountries : [];
    if (!live.length) {
      const geo = await apiFetch('GET', '/geo');
      live = (geo && Array.isArray(geo.countries)) ? geo.countries : [];
    }
    if (live.length) renderHeroLocales(live);
    else console.warn('"Live now in" strip is hidden: no country is marked live in Admin → Categories & Countries.');
  } catch (e) { console.warn('Could not draw the "Live now in" strip.', e); }
  if (!content) return;
  try {
    const prefixEl = document.getElementById('hero-prefix');
    const suffixEl = document.getElementById('hero-suffix');
    const subheadEl = document.getElementById('hero-subheadline');
    const missionHeadEl = document.getElementById('mission-headline');
    const missionBodyEl = document.getElementById('mission-body');
    // isCustomized (from the backend — see GET /homepage-content) tells
    // us whether this is genuine admin-written text, which has no
    // translation and stays exactly as typed regardless of language, or
    // still the untouched default copy, which DOES have real
    // translations (hero_prefix/hero_suffix/hero_sub/mission_headline/
    // mission_body in I18N). Real fix for the hero never translating:
    // it previously always showed this raw content verbatim, in every
    // language, with no distinction between the two cases.
    if (!content.isCustomized) {
      if (prefixEl) prefixEl.textContent = t('hero_prefix');
      if (suffixEl) suffixEl.textContent = t('hero_suffix');
      if (subheadEl) subheadEl.textContent = t('hero_sub');
      if (missionHeadEl) missionHeadEl.textContent = t('mission_headline');
      if (missionBodyEl) missionBodyEl.textContent = t('mission_body');
    } else {
      if (prefixEl) prefixEl.textContent = content.heroPrefix;
      if (suffixEl) suffixEl.textContent = content.heroSuffix;
      if (subheadEl) subheadEl.textContent = content.heroSubheadline;
      if (missionHeadEl) missionHeadEl.textContent = content.missionHeadline;
      if (missionBodyEl) missionBodyEl.textContent = content.missionBody;
    }
    if (Array.isArray(content.heroRotatingWords) && content.heroRotatingWords.length) {
      HERO_ROTATING_WORDS = content.heroRotatingWords;
      const firstWord = document.getElementById('hero-rotating-word');
      if (firstWord) firstWord.textContent = HERO_ROTATING_WORDS[0];
      startHeroWordRotation(); // restart with the real word list
    }
    const blank = document.querySelector('.hero-blank');
    if (blank) blank.style.display = (!content.isCustomized && CURRENT_LANG !== 'en') ? 'none' : '';
    // Item: "Live in the U.S. · Nigeria · Ghana · Liberia" used to be
    // permanently hardcoded — never reflected reality, and could only
    // ever be changed by editing the code. Real now, and the content is
    // duplicated once here so the scrolling animation below can loop
    // seamlessly at exactly the halfway point, with no visible seam or
    // jump.
    const localesTrack = document.getElementById('hero-locales-track');
    if (localesTrack && Array.isArray(content.featuredCountries) && content.featuredCountries.length) {
      renderHeroLocales(content.featuredCountries);
    }
  } catch (e) { console.warn('Could not load homepage content, using defaults.', e); }
}


// Real categories, real "starting at" prices (computed server-side from
// actual provider rates), real optional photos — see GET
// /api/popular-projects. The whole section stays hidden if there's
// nothing real to show yet (a brand-new deployment with no verified
// providers in any category), rather than displaying an empty or
// placeholder-filled grid.
// "Live now in" strip: each live country as a chip. If they all fit on
// one line it sits still in the middle; only a long list scrolls (and is
// then duplicated once so the loop has no seam).
let HERO_LOCALES = null;
// "Live now in": sits still in the middle of the band; the country chips
// flash (see .is-flash in the stylesheet).
function renderHeroLocales(countries) {
  HERO_LOCALES = countries;
  const bar = document.getElementById('hero-locales');
  const track = document.getElementById('hero-locales-track');
  if (!bar || !track) return;
  bar.hidden = false;
  bar.classList.remove('is-ticker', 'is-static');
  bar.classList.add('is-flash');
  const chips = countries.map(c => `<span class="loc-chip">${escapeHtml(c)}</span>`).join('');
  track.innerHTML = `<span class="loc-set"><span class="loc-label"><i class="live-dot" aria-hidden="true"></i>${escapeHtml(t('loc_live'))}</span>${chips}</span>`;
}
window.addEventListener('resize', () => { if (HERO_LOCALES) renderHeroLocales(HERO_LOCALES); });

async function loadPopularProjects() {
  const section = document.getElementById('popular-projects-section');
  if (!section || !BACKEND_AVAILABLE) return;
  try {
    const { projects } = await apiFetch('GET', '/popular-projects');
    if (!projects.length) return; // stays hidden — nothing real to show yet
    document.getElementById('popular-projects-grid').innerHTML = projects.map((p, i) => popularCardHTML(p, i)).join('');
    section.style.display = '';
  } catch (e) { console.warn('Could not load popular projects', e); }
}

// Applies real, admin-uploaded photos to the hero and mission sections, if
// any have been set (Settings → Platform Settings, super admin). Both
// slots are designed to degrade invisibly — no photo uploaded means
// exactly the current icon/gradient look, never a broken image or empty
// gap.
async function loadHomepageImages() {
  if (!BACKEND_AVAILABLE) return;
  try {
    const images = await apiFetch('GET', '/homepage-images');
    if (images.hero) {
      const heroEl = document.querySelector('.hero');
      if (heroEl) {
        heroEl.style.setProperty('--hero-photo-url', `url("${images.hero}")`);
        heroEl.classList.add('has-photo');
      }
    }
    if (images.mission) {
      const missionImg = document.getElementById('mission-photo');
      if (missionImg) { missionImg.src = images.mission; missionImg.classList.add('loaded'); }
    }
  } catch (e) { console.warn('Could not load homepage images', e); }
}
// scrolls to them, instead of everything just being present on load — a
// standard, subtle technique (used across most modern marketing sites),
// not applied to content someone needs to read immediately (the hero
// itself is untouched, so there's no delay seeing what Trothen is).
function setupScrollFadeIn() {
  return; // v57: sections no longer fade in on scroll
  const selectors = ['.trust-strip', '.mission-section', '.section', '.how-it-works', '#featured-carousel-section'];
  const els = document.querySelectorAll(selectors.join(','));
  if (!els.length) return;
  els.forEach(el => el.classList.add('scroll-fade-section'));
  if (!('IntersectionObserver' in window)) { els.forEach(el => el.classList.add('in-view')); return; }
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) { entry.target.classList.add('in-view'); observer.unobserve(entry.target); }
    });
  }, { threshold: 0.12 });
  els.forEach(el => observer.observe(el));
}
function supportContactHTML() {
  return `<br/><br/>📱 WhatsApp: <a href="https://wa.me/${SUPPORT_CONTACT.whatsapp}" target="_blank" style="color:var(--gold);">Chat with us</a><br/>☎️ Call: <a href="tel:+${SUPPORT_CONTACT.whatsapp}" style="color:var(--gold);">${SUPPORT_CONTACT.phoneDisplay}</a>${SUPPORT_CONTACT.email ? `<br/>✉️ Email: <a href="mailto:${escapeHtml(SUPPORT_CONTACT.email)}" style="color:var(--gold);">${escapeHtml(SUPPORT_CONTACT.email)}</a>` : ''}`;
}

const SUPPORT_FAQ = [
  { keywords: ['escrow', 'hold', 'held', 'release fund'], answer: "Escrow means the money for your job is held safely by Trothen — not paid to the pro — until you confirm the work is done. Once you mark a booking \"Complete\" in My Bookings, the funds release to your pro automatically." },
  { keywords: ['verif', 'id check', 'background check', 'kyc'], answer: "Every customer and provider on Trothen goes through identity verification — submit a government ID in Settings, and an admin reviews it (usually quickly). Providers also get a background check before their first job." },
  { keywords: ['dispute', 'problem', 'complaint', 'refund', 'bad job', 'not happy'], answer: "If something's wrong with a job, don't mark it complete — that releases escrow. Instead, message your pro first to try to resolve it, and if that doesn't work, our Finance & Dispute team can step in to review and resolve it fairly." },
  { keywords: ['pay', 'payment', 'card', 'billing'], answer: "You can add a payment method in Customer → Payments. Right now this runs in test mode (no real charges) while we finalize our payment processor — you can use any test card number to try the flow." },
  { keywords: ['become a pro', 'sign up as provider', 'join as provider', 'provider account'], answer: "Click \"Become a Pro\" at the top of the page, or choose \"Provider\" when you sign up. You'll need your category, skills, and location — new providers start unverified until an admin approves their documents." },
  { keywords: ['price', 'pricing', 'plan', 'cost', 'subscription', 'fee'], get answer() { return `Trothen has three plans for pros. Starter takes ${PLAN_COMMISSION.starter}% commission on each job. Pro takes ${PLAN_COMMISSION.pro}% and is reached automatically once you qualify. Super Pro takes ${PLAN_COMMISSION.superpro}% and is confirmed by our team once you qualify. Each plan also has a monthly price, which depends on your country: the Provider Plans page shows yours. ${PLAN_BILLING_PUBLIC.active ? 'The monthly fee comes out of your payouts, never a card.' : 'The monthly fee isn\'t being charged during early access.'} Customers don't pay to join.`; } },
  { keywords: ['categor', 'service', 'what can i book', 'what do you offer'], answer: "Trothen covers Plumbing, Cleaning, Tutoring, Electrical, Moving, Painting, Landscaping, Fitness, Pick & Drop, and more — browse them all from \"See all categories\" on the homepage." },
  { keywords: ['match', 'ai match', 'how does matching work', 'algorithm'], answer: "When you post a job, our matching engine ranks verified pros in your category and community by rating, experience, and proximity (we prioritize pros in your exact zip code first). You'll see the top matches with a fit score." },
  { keywords: ['community', 'zip', 'postal', 'location match'], answer: "We use your zip/postal code to find pros right in your community first, before widening to your broader city — this tends to mean faster response times and pros who already know the area." },
  { keywords: ['phone verif', 'otp', 'verify my phone', 'text code'], answer: "You don't need to verify your phone to create an account — just your email. If you'd like to verify your phone later (useful for two-factor login), you can do that any time from Settings." },
  { keywords: ['human', 'agent', 'real person', 'support team', 'talk to someone', 'whatsapp', 'call'], answer: "Of course — reach a real person any time:" + supportContactHTML() + supportEmailLineHTML() },
  { keywords: ['hi', 'hello', 'hey'], answer: "Hi! I'm Trothen's AI assistant, not a person. Ask me about escrow, verification, disputes, payments, pricing, or how matching works — or ask for a real person any time." },
];

const SUPPORT_SUGGESTIONS = ['How does escrow work?', 'How do I get verified?', 'What are the pricing plans?', 'How does matching work?'];

function answerSupportQuestion(text) {
  const lower = text.toLowerCase();
  for (const entry of SUPPORT_FAQ) {
    if (entry.keywords.some(k => lower.includes(k))) return entry.answer;
  }
  return "I don't have a canned answer for that yet — try asking about escrow, verification, disputes, payments, or pricing. Or reach a real person:" + supportContactHTML();
}

// The chat bubble is fully draggable — press and drag it anywhere on
// screen, and it stays there (saved locally, so it's still there next time
// you visit). A plain click still opens the chat as before; the only
// difference is a genuine drag (moved more than a few pixels) is treated
// as repositioning, not a click, so it never accidentally opens the panel
// mid-drag.
let chatBubbleDragState = null;
function initChatBubbleDrag() {
  const bubble = document.getElementById('support-chat-bubble');
  if (!bubble) return;

  // Restore a previously-saved position, if any — clamped again here in
  // case the window is smaller now than when it was saved (e.g. this is a
  // smaller screen than last time), so it can never restore off-screen.
  try {
    const saved = JSON.parse(localStorage.getItem('trothen_chat_bubble_pos') || 'null');
    if (saved && typeof saved.left === 'number' && typeof saved.top === 'number') {
      const size = bubble.offsetWidth || 60;
      const clampedLeft = Math.min(Math.max(0, saved.left), window.innerWidth - size);
      const clampedTop = Math.min(Math.max(0, saved.top), window.innerHeight - size);
      applyBubblePosition(clampedLeft, clampedTop);
    }
  } catch (e) { /* ignore a corrupted saved value, just use the default position */ }

  const startDrag = (clientX, clientY) => {
    const rect = bubble.getBoundingClientRect();
    chatBubbleDragState = { startX: clientX, startY: clientY, originLeft: rect.left, originTop: rect.top, moved: false };
    bubble.classList.add('dragging');
  };
  const moveDrag = (clientX, clientY) => {
    if (!chatBubbleDragState) return;
    const dx = clientX - chatBubbleDragState.startX;
    const dy = clientY - chatBubbleDragState.startY;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) chatBubbleDragState.moved = true;
    const size = bubble.offsetWidth;
    const newLeft = Math.min(Math.max(0, chatBubbleDragState.originLeft + dx), window.innerWidth - size);
    const newTop = Math.min(Math.max(0, chatBubbleDragState.originTop + dy), window.innerHeight - size);
    applyBubblePosition(newLeft, newTop);
  };
  const endDrag = () => {
    if (!chatBubbleDragState) return;
    bubble.classList.remove('dragging');
    if (chatBubbleDragState.moved) {
      const rect = bubble.getBoundingClientRect();
      localStorage.setItem('trothen_chat_bubble_pos', JSON.stringify({ left: rect.left, top: rect.top }));
    }
    // Leave chatBubbleDragState set through the click handler below so it
    // can tell a drag from a click, then clear it right after.
  };

  bubble.addEventListener('mousedown', (e) => { startDrag(e.clientX, e.clientY); });
  document.addEventListener('mousemove', (e) => { if (chatBubbleDragState) moveDrag(e.clientX, e.clientY); });
  document.addEventListener('mouseup', endDrag);

  bubble.addEventListener('touchstart', (e) => { const t = e.touches[0]; startDrag(t.clientX, t.clientY); }, { passive: true });
  document.addEventListener('touchmove', (e) => { if (chatBubbleDragState) { const t = e.touches[0]; moveDrag(t.clientX, t.clientY); } }, { passive: true });
  document.addEventListener('touchend', endDrag);
  // Real bug fix: without this, a touch sequence the browser cancels
  // instead of ending normally — a scroll gesture taking over, a system
  // interruption, anything mobile browsers do fairly often — left
  // chatBubbleDragState permanently set. A normal touchend is always
  // followed by a click event, and it's actually handleChatBubbleClick
  // (not endDrag itself, on purpose — see its comment) that clears the
  // state afterward; a cancelled touch never generates that click, so
  // reusing endDrag alone here wouldn't have been enough. The next
  // unrelated touchmove ANYWHERE on the page (this listener is on
  // document, not just the bubble) would then be read as still dragging
  // the bubble, snapping it to wherever that unrelated touch happened to
  // be. This is almost certainly what "moving anyhow" was.
  document.addEventListener('touchcancel', () => {
    endDrag();
    chatBubbleDragState = null;
  });
}

function applyBubblePosition(left, top) {
  const bubble = document.getElementById('support-chat-bubble');
  if (!bubble) return;
  bubble.style.left = `${left}px`;
  bubble.style.top = `${top}px`;
  bubble.style.right = 'auto';
  bubble.style.bottom = 'auto';
}

// Real bug fix: the chat bubble and its panel sit at a higher z-index
// (400) than every modal in the app (200) — and nothing ever hid the
// bubble while a modal, or a full-screen view like signing in, was
// showing. On a small phone screen, where there's little room to begin
// with, the bubble could end up sitting directly on top of a screen's
// own button or input, silently eating taps meant for the form
// underneath instead of ever reaching it. Rather than touching the
// dozens of existing modal open/close call sites throughout this file
// (a real risk of missing one), a MutationObserver watches every modal
// and the sign-in screen specifically for their own open/active state
// and hides the bubble/panel whenever any of them is showing, bringing
// it back the moment none are.
function initChatBubbleModalGuard() {
  const bubble = document.getElementById('support-chat-bubble');
  const panel = document.getElementById('support-chat-panel');
  if (!bubble) return;
  const overlays = Array.from(document.querySelectorAll('.modal-overlay'));
  // The actual screen this was reported on — signing in — isn't a modal
  // at all, it's a full screen (#screen-auth, shown via showScreen()
  // toggling an "active" class, a completely different mechanism from
  // modal-overlay/open). The bubble sits at a fixed position over
  // whatever's showing regardless of which of the two mechanisms is in
  // play, so it needs to be watched too, specifically because this is
  // the exact screen it was reported as blocking.
  const authScreen = document.getElementById('screen-auth');
  const updateVisibility = () => {
    const anyModalOpen = overlays.some(o => o.classList.contains('open'));
    const onAuthScreen = authScreen && authScreen.classList.contains('active');
    const shouldHide = anyModalOpen || onAuthScreen;
    bubble.style.display = shouldHide ? 'none' : '';
    if (shouldHide && panel) panel.style.display = 'none';
  };
  overlays.forEach(o => {
    new MutationObserver(updateVisibility).observe(o, { attributes: true, attributeFilter: ['class'] });
  });
  if (authScreen) new MutationObserver(updateVisibility).observe(authScreen, { attributes: true, attributeFilter: ['class'] });
  updateVisibility();
}

function handleChatBubbleClick(event) {
  // A real drag just happened — swallow this click rather than also
  // toggling the chat open/closed.
  const wasDrag = chatBubbleDragState && chatBubbleDragState.moved;
  chatBubbleDragState = null;
  if (wasDrag) return;
  toggleSupportChat();
}

function toggleSupportChat() {
  const panel = document.getElementById('support-chat-panel');
  const isOpening = !panel.classList.contains('open');
  if (isOpening) positionChatPanelNearBubble();
  panel.classList.toggle('open');
  if (isOpening && !document.getElementById('support-chat-body').children.length) {
    appendSupportMessage('bot', "Hi — I'm Trothen's AI assistant, not a person. I can answer most questions about escrow, verification, disputes, payments, or how the platform works. If you'd rather talk to a real person, just ask, or use the link below any time.");
    appendSupportSuggestions();
  }
}

// Skips straight past the AI entirely — genuinely one request away, not
// buried behind having to guess the right keyword first.
function requestHumanSupport() {
  appendSupportMessage('user', 'Talk to a real person');
  appendSupportMessage('bot', "Of course — reach a real person any time:" + supportContactHTML() + supportEmailLineHTML());
}

// If the bubble has been dragged somewhere other than its default corner,
// the chat panel needs to open near wherever it actually is now, not silently
// stay anchored to the original bottom-right corner (which could be nowhere
// near the bubble, or partly off-screen, after a drag).
function positionChatPanelNearBubble() {
  const bubble = document.getElementById('support-chat-bubble');
  const panel = document.getElementById('support-chat-panel');
  if (!bubble || !panel) return;
  const rect = bubble.getBoundingClientRect();
  const panelWidth = Math.min(340, window.innerWidth - 32);
  const panelHeight = Math.min(440, window.innerHeight - 120);
  const margin = 12;

  // Prefer opening above the bubble; flip below it if there's not enough
  // room above. Prefer aligning to the bubble's right edge; flip to its
  // left edge if that would run off the right side of the screen.
  let top = rect.top - panelHeight - margin;
  if (top < margin) top = Math.min(rect.bottom + margin, window.innerHeight - panelHeight - margin);
  let left = rect.right - panelWidth;
  if (left < margin) left = rect.left;
  left = Math.min(Math.max(margin, left), window.innerWidth - panelWidth - margin);

  panel.style.top = `${top}px`;
  panel.style.left = `${left}px`;
  panel.style.right = 'auto';
  panel.style.bottom = 'auto';
}

function appendSupportMessage(from, text) {
  const body = document.getElementById('support-chat-body');
  const bubble = document.createElement('div');
  bubble.className = `support-chat-bubble-msg ${from}`;
  // Bot replies come from our own fixed FAQ data (never user input), so it's
  // safe to let them include real formatting/links (e.g. a WhatsApp link).
  // A user's own typed message always stays as plain text — never rendered
  // as HTML — regardless of what they type.
  if (from === 'bot') bubble.innerHTML = text;
  else bubble.textContent = text;
  body.appendChild(bubble);
  body.scrollTop = body.scrollHeight;
}

function appendSupportSuggestions() {
  const body = document.getElementById('support-chat-body');
  const wrap = document.createElement('div');
  wrap.className = 'support-chat-suggestions';
  wrap.innerHTML = SUPPORT_SUGGESTIONS.map(s => `<div class="support-chat-suggestion" onclick="askSupportSuggestion(this)">${s}</div>`).join('');
  body.appendChild(wrap);
  body.scrollTop = body.scrollHeight;
}

function askSupportSuggestion(el) {
  const text = el.textContent;
  el.parentElement.remove();
  appendSupportMessage('user', text);
  setTimeout(() => appendSupportMessage('bot', answerSupportQuestion(text)), 300);
}

let SUPPORT_CHAT_HISTORY = [];

function sendSupportChatMessage() {
  const input = document.getElementById('support-chat-input');
  const text = input.value.trim();
  if (!text) return;
  appendSupportMessage('user', text);
  SUPPORT_CHAT_HISTORY.push({ from: 'user', text });
  input.value = '';

  const lower = text.toLowerCase();
  const keywordMatch = SUPPORT_FAQ.find(entry => entry.keywords.some(k => lower.includes(k)));
  if (keywordMatch) {
    setTimeout(() => {
      appendSupportMessage('bot', keywordMatch.answer);
      SUPPORT_CHAT_HISTORY.push({ from: 'bot', text: keywordMatch.answer });
    }, 350);
    return;
  }

  // No canned answer covers this — try the real assistant instead of
  // immediately giving up with a generic "I don't have an answer"
  // message. Shows a genuine "thinking" indicator since this is a real
  // network call, not an instant local lookup.
  const thinkingId = 'thinking-' + Date.now();
  const body = document.getElementById('support-chat-body');
  const thinkingBubble = document.createElement('div');
  thinkingBubble.className = 'support-chat-bubble-msg bot';
  thinkingBubble.id = thinkingId;
  thinkingBubble.textContent = '···';
  body.appendChild(thinkingBubble);
  body.scrollTop = body.scrollHeight;

  askRealSupportChat(text).then(answer => {
    document.getElementById(thinkingId)?.remove();
    // The AI's response is genuinely generated text, not a pre-written
    // FAQ answer — escaped here, unlike the trusted canned answers above,
    // since this is the same category of content as any other untrusted
    // text in this app.
    appendSupportMessage('bot', escapeHtml(answer));
    SUPPORT_CHAT_HISTORY.push({ from: 'bot', text: answer });
  }).catch(e => {
    document.getElementById(thinkingId)?.remove();
    // Deliberately different messages for two genuinely different
    // situations — previously both looked identical, making it
    // impossible to tell "the smart-answer feature isn't set up yet"
    // apart from "it tried and genuinely couldn't help," which matters a
    // lot if you're the site owner testing whether this is even on.
    const notConfigured = e && e.data && e.data.error === 'not_configured';
    const fallback = notConfigured
      ? "The smart-answer feature isn't turned on yet — it needs a real API key added as an environment variable on the server (not something set through this website). Here's a real person in the meantime:" + supportContactHTML()
      : "I don't have a confident answer for that — let's get you a real person:" + supportContactHTML();
    appendSupportMessage('bot', fallback);
    SUPPORT_CHAT_HISTORY.push({ from: 'bot', text: fallback });
  });
}

async function askRealSupportChat(message) {
  if (!BACKEND_AVAILABLE) throw new Error('offline');
  const { answer } = await apiFetch('POST', '/support-chat/ask', { message, history: SUPPORT_CHAT_HISTORY.slice(-6) });
  return answer;
}

// The notice at the top of every page, built from what the server says is
// actually connected right now (GET /api/system-status) instead of fixed
// wording. The fixed text in the HTML is the safe default shown until this
// loads (and if it can't load): it only states what is true regardless of
// configuration — payments are simulated.
async function loadSystemStatusBanner() {
  const el = document.getElementById('test-mode-banner-text');
  if (!el) return;
  try {
    const st = await apiFetch('GET', '/system-status');
    const parts = [];
    if (st.cardPaymentsLive) {
      // Nothing left to warn about for payments.
    } else if (st.liberiaMoMoLive) {
      parts.push('Card payments aren\'t live yet — card payments and payouts are simulated. Liberia mobile money payments are real.');
    } else {
      parts.push('Payments aren\'t live yet — every payment and payout is simulated and no real money moves.');
    }
    if (!st.emailLive) parts.push('Email sending isn\'t connected, so account codes appear on-screen instead of being emailed.');
    if (!st.smsLive) parts.push('Text-message codes aren\'t connected, so phone codes appear on-screen.');
    if (!parts.length) {
      document.getElementById('test-mode-banner').style.display = 'none';
      return;
    }
    const warn = ''; // v89: the card warning now sits on the payment form itself, where a card is typed, so it isn't mistaken for an ID card
    el.innerHTML = '<strong>Early access</strong> — accounts and ID verification are real. ' + parts.map(escapeHtml).join(' ') + warn;
  } catch (e) { /* keep the safe default wording */ }
}

/* ══════════════════════ v57: DRAWN ICONS, BRAND MARK, HOMEPAGE INTERACTION ══════════════════════ */
// Small line icons drawn for Trothen (24px grid, 1.75 stroke), used in
// place of emoji on the public pages so they read the same on every
// phone and computer.
const UI_ICONS = {
  id: '<path d="M3.5 6.5h17v11h-17z"/><circle cx="9" cy="11" r="2"/><path d="M5.8 15.5c.6-1.5 1.8-2.2 3.2-2.2s2.6.7 3.2 2.2M14 10h4M14 13h3"/>',
  doc: '<path d="M6 3.5h8.5L18 7v13.5H6z"/><path d="M14 3.5V7h4M9 11h6M9 14h6M9 17h3.5"/>',
  lock: '<rect x="5" y="10.5" width="14" height="10" rx="1.5"/><path d="M8 10.5V8a4 4 0 0 1 8 0v2.5M12 14.5v2.5"/>',
  shield: '<path d="M12 3.5l7 2.8v5.2c0 4.4-3 7.7-7 9-4-1.3-7-4.6-7-9V6.3z"/><path d="M8.8 12.2l2.2 2.2 4.2-4.4"/>',
  pin: '<path d="M12 21s-6.5-6-6.5-11a6.5 6.5 0 0 1 13 0c0 5-6.5 11-6.5 11z"/><circle cx="12" cy="10" r="2.3"/>',
  locate: '<circle cx="12" cy="12" r="4.5"/><path d="M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3"/>',
  check: '<path d="M5 12.5l4.2 4.2L19 7"/>',
  jobs: '<rect x="3.5" y="7.5" width="17" height="12" rx="1.5"/><path d="M9 7.5V5.5h6v2M3.5 12.5h17"/>',
  score: '<path d="M12 3.5l7 2.8v5.2c0 4.4-3 7.7-7 9-4-1.3-7-4.6-7-9V6.3z"/>',
  wait: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
};
function uiIcon(name, extraAttrs) {
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extraAttrs || ''}>${UI_ICONS[name] || ''}</svg>`;
}

// The Trothen logo, exactly as supplied (LOGO_IMG_FULL, unmodified),
// at the same sizes the site used before the redesign.
function brandMarkHTML(place) {
  const cls = place === 'footer' ? 'footer-logo-img' : place === 'auth' ? 'auth-logo-img' : 'navbar-logo-img';
  return `<img src="${LOGO_IMG_FULL}" alt="Trothen" class="${cls}"/>`;
}

// The job ticket in the hero: four real steps of a booking. Clicking a
// step (or "Next step", or the arrow keys) fills in the ticket up to that
// point so a visitor can see exactly what they'd get at each stage.
let TICKET_STAGE = 0;
function ticketGo(target, fromAutoplay) {
  const steps = document.querySelectorAll('.ticket-step');
  if (!steps.length) return;
  let next = target === 'next' ? (TICKET_STAGE + 1) % steps.length : Number(target);
  if (!(next >= 0 && next < steps.length)) return;
  const prev = TICKET_STAGE;
  TICKET_STAGE = next;
  steps.forEach((btn, i) => {
    btn.classList.toggle('is-on', i === next);
    btn.classList.toggle('is-done', i < next);
    btn.setAttribute('aria-selected', i === next ? 'true' : 'false');
    btn.tabIndex = i === next ? 0 : -1;
  });
  const bar = document.querySelector('.ticket-steps');
  if (bar) bar.style.setProperty('--progress', (next / (steps.length - 1) * 75) + '%');
  document.querySelectorAll('.ticket-fields .tf').forEach(row => {
    const from = Number(row.dataset.from);
    row.classList.toggle('is-pending', from > next);
    row.classList.toggle('is-new', from === next && next !== prev && from > 0);
  });
  const chip = document.getElementById('ticket-status');
  if (chip) {
    const key = 'ticket_status_' + (next + 1);
    chip.dataset.i18n = key; chip.textContent = t(key); chip.dataset.stage = String(next);
    if (next !== prev) { chip.classList.remove('is-swapping'); void chip.offsetWidth; chip.classList.add('is-swapping'); }
  }
  const ticketEl = document.querySelector('.ticket');
  if (ticketEl) ticketEl.dataset.stage = String(next);
  const note = document.getElementById('ticket-note');
  if (note) {
    note.dataset.i18n = 'ticket_n' + (next + 1); note.textContent = t('ticket_n' + (next + 1));
    if (next !== prev) { note.classList.remove('is-swapping'); void note.offsetWidth; note.classList.add('is-swapping'); }
  }
  const nextBtn = document.getElementById('ticket-next');
  if (nextBtn) { const key = next === steps.length - 1 ? 'ticket_again' : 'ticket_next'; nextBtn.dataset.i18n = key; nextBtn.textContent = t(key); }
}
function setupTicket() {
  const list = document.querySelector('.ticket-steps');
  if (!list) return;
  list.addEventListener('keydown', (e) => {
    const count = document.querySelectorAll('.ticket-step').length;
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
      e.preventDefault();
      const n = (TICKET_STAGE + (e.key === 'ArrowRight' ? 1 : count - 1)) % count;
      ticketGo(n);
      document.querySelectorAll('.ticket-step')[n].focus();
    }
  });
  ticketGo(0);
}

// "I need help with ___" — suggests real categories as you type, matched
// on the category name and on the same everyday words the server's
// search understands (plumber → Plumbing).
const COMPOSER_WORDS = {
  plumbing: ['plumber', 'leak', 'tap', 'faucet', 'toilet', 'pipe', 'drain', 'sink', 'water heater'],
  electrical: ['electrician', 'wiring', 'socket', 'outlet', 'light', 'fuse', 'breaker'],
  cleaning: ['cleaner', 'clean', 'maid', 'housekeeping'],
  'deep cleaning': ['move out clean', 'spring clean'],
  tutoring: ['tutor', 'maths', 'math', 'homework', 'lessons', 'teacher'],
  moving: ['mover', 'removal', 'relocate', 'move house'],
  painting: ['painter', 'paint', 'decorating'],
  landscaping: ['garden', 'yard', 'landscaper'],
  'lawn care': ['mow', 'grass', 'lawn'],
  'hvac & air conditioning': ['ac', 'air con', 'aircon', 'heating', 'furnace'],
  'handyman services': ['handyman', 'odd jobs', 'fix', 'repair'],
  'auto repair': ['mechanic', 'car repair', 'car'],
  'it support & computer repair': ['computer', 'laptop', 'wifi', 'it'],
  'babysitting & nanny services': ['babysitter', 'nanny', 'childcare'],
  'pet sitting': ['cat sitter', 'pet'],
  'dog walking': ['dog walker', 'dog'],
  locksmith: ['locked out', 'lock', 'keys'],
  'junk removal': ['rubbish', 'trash', 'haul'],
  'furniture assembly': ['ikea', 'assemble', 'flat pack'],
  'hair styling': ['hair', 'braids', 'barber', 'hairdresser'],
};
let COMPOSER_ACTIVE = -1;
function composerMatches(q) {
  const query = q.trim().toLowerCase();
  if (!query) return (CATEGORIES || []).slice().sort((a, b) => (b.proCount || 0) - (a.proCount || 0)).slice(0, 6);
  const scored = [];
  (CATEGORIES || []).forEach(c => {
    const name = String(c.name || '');
    const lower = name.toLowerCase();
    const words = COMPOSER_WORDS[lower] || [];
    let score = 0;
    if (lower.startsWith(query)) score = 3;
    else if (lower.split(/[\s&,]+/).some(w => w.startsWith(query))) score = 2;
    else if (words.some(w => w.startsWith(query) || query.startsWith(w))) score = 1.5;
    else if (lower.includes(query)) score = 1;
    if (score) scored.push({ c, score });
  });
  return scored.sort((a, b) => b.score - a.score || (b.c.proCount || 0) - (a.c.proCount || 0)).slice(0, 7).map(x => x.c);
}
function composerSuggest() {
  const input = document.getElementById('search-input');
  const box = document.getElementById('composer-suggest');
  if (!input || !box) return;
  const q = input.value;
  const matches = composerMatches(q);
  COMPOSER_ACTIVE = -1;
  if (!matches.length) { box.hidden = true; input.setAttribute('aria-expanded', 'false'); return; }
  const esc = s => escapeHtml(String(s));
  const hl = (name) => {
    const i = name.toLowerCase().indexOf(q.trim().toLowerCase());
    if (!q.trim() || i < 0) return esc(name);
    return esc(name.slice(0, i)) + '<mark>' + esc(name.slice(i, i + q.trim().length)) + '</mark>' + esc(name.slice(i + q.trim().length));
  };
  box.innerHTML = (q.trim() ? '' : `<li class="cs-hint" aria-hidden="true">${escapeHtml(t('composer_hint'))}</li>`) +
    matches.map((c, i) => `<li role="option" id="cs-opt-${i}" data-name="${esc(c.name)}" onmousedown="event.preventDefault();composerPick(this.dataset.name)">
      <span>${hl(translateCategoryName(c.name))}</span>${typeof c.proCount === 'number' ? `<small>${c.proCount} ${c.proCount === 1 ? t('pro_one') : t('pro_many')}</small>` : ''}</li>`).join('');
  box.hidden = false;
  input.setAttribute('aria-expanded', 'true');
}
function composerClose() {
  const box = document.getElementById('composer-suggest');
  const input = document.getElementById('search-input');
  if (box) box.hidden = true;
  if (input) { input.setAttribute('aria-expanded', 'false'); input.removeAttribute('aria-activedescendant'); }
  COMPOSER_ACTIVE = -1;
}
function composerPick(name) {
  const input = document.getElementById('search-input');
  if (input) input.value = name;
  composerClose();
  const loc = document.getElementById('search-location-input');
  if (loc && !loc.value.trim() && !MY_REAL_LOCATION) { loc.focus(); return; }
  composerSubmit();
}
function composerSubmit() {
  composerClose();
  const q = document.getElementById('search-input').value.trim();
  const loc = document.getElementById('search-location-input').value.trim();
  if (!q && !loc && !MY_REAL_LOCATION) { document.getElementById('search-input').focus(); composerSuggest(); return; }
  handleSearchClick();
}
function composerKeydown(e) {
  const box = document.getElementById('composer-suggest');
  const items = box && !box.hidden ? box.querySelectorAll('li[role="option"]') : [];
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    if (!items.length) { composerSuggest(); return; }
    e.preventDefault();
    COMPOSER_ACTIVE = e.key === 'ArrowDown'
      ? (COMPOSER_ACTIVE + 1) % items.length
      : (COMPOSER_ACTIVE <= 0 ? items.length - 1 : COMPOSER_ACTIVE - 1);
    items.forEach((li, i) => li.classList.toggle('is-active', i === COMPOSER_ACTIVE));
    e.target.setAttribute('aria-activedescendant', items[COMPOSER_ACTIVE].id);
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (COMPOSER_ACTIVE >= 0 && items[COMPOSER_ACTIVE]) composerPick(items[COMPOSER_ACTIVE].dataset.name);
    else composerSubmit();
  } else if (e.key === 'Escape') {
    composerClose();
  }
}
function setupHomepageV57() {
  const locBtn = document.getElementById('use-location-btn');
  if (locBtn && !locBtn.innerHTML.trim()) locBtn.innerHTML = uiIcon('locate');
  document.querySelectorAll('.checks-icon[data-icon], .auth-trust-item .icon[data-icon]').forEach(el => { el.innerHTML = uiIcon(el.dataset.icon); });
  document.querySelectorAll('[data-brand-mark]').forEach(el => { el.innerHTML = brandMarkHTML('auth'); });
  const footerLogo = document.getElementById('footer-logo-home');
  if (footerLogo) footerLogo.innerHTML = brandMarkHTML('footer');
  document.addEventListener('click', (e) => { if (!e.target.closest || !e.target.closest('.composer')) composerClose(); });
  setupTicket();
  setupHomepageMotion();
}

/* ══════════════════════ v57: FRONT PAGE MOTION ══════════════════════ */
const V57_REDUCED_MOTION = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

// Runs fn once, the first time el scrolls into view.
function whenVisible(el, fn, threshold) {
  if (!el) return;
  if (!('IntersectionObserver' in window)) { fn(); return; }
  const io = new IntersectionObserver((entries) => {
    if (entries.some(e => e.isIntersecting)) { io.disconnect(); fn(); }
  }, { threshold: threshold == null ? 0.35 : threshold });
  io.observe(el);
}

// The changing word in the headline: fade the old word up and out, then
// stretch the yellow line to the new word's width and bring it in.
// Pauses while the hero is off screen or the tab is in the background.
let HERO_WORD_INDEX = 0;
let HERO_VISIBLE = true;
function heroSwapWord(word) {
  const el = document.getElementById('hero-rotating-word');
  if (!el) return;
  const blank = el.parentElement;
  if (V57_REDUCED_MOTION || !blank || !blank.classList.contains('hero-blank')) { el.textContent = word; return; }
  el.classList.remove('word-in');
  el.classList.add('word-swap');
  setTimeout(() => {
    const from = blank.getBoundingClientRect().width;
    blank.style.width = 'auto';
    el.textContent = word;
    const to = blank.getBoundingClientRect().width;
    blank.style.width = from + 'px';
    void blank.offsetWidth; // start the width change from the old size
    blank.style.width = to + 'px';
    el.classList.remove('word-swap');
    el.classList.add('word-in');
  }, 230);
}
function startHeroWordRotation() {
  const el = document.getElementById('hero-rotating-word');
  if (!el || HERO_ROTATING_WORDS.length < 2) return; // nothing to rotate through
  if (heroRotationTimer) clearInterval(heroRotationTimer);
  HERO_WORD_INDEX = Math.max(0, HERO_ROTATING_WORDS.indexOf(el.textContent));
  heroRotationTimer = setInterval(() => {
    if (!HERO_VISIBLE || document.hidden) return;
    HERO_WORD_INDEX = (HERO_WORD_INDEX + 1) % HERO_ROTATING_WORDS.length;
    heroSwapWord(HERO_ROTATING_WORDS[HERO_WORD_INDEX]);
  }, 2800);
}

// The ticket plays through a booking on its own, over and over, while
// it's on screen: step 1 → 2 → 3 → 4, a short pause on "Job done", then
// back to the start. Clicking a step or "Next step" takes over; it picks
// up again by itself after a few quiet seconds. It holds still only
// while the pointer is on its buttons, while someone is using it with the
// keyboard, or when nobody can see it. Never plays for reduced-motion
// users.
const TICKET_STEP_MS = 3200;
const TICKET_LAST_HOLD_MS = 4200;
const TICKET_RESUME_AFTER_MS = 9000;
let TICKET_TIMER = null;
let TICKET_RESUME_TIMER = null;
let TICKET_PAUSED = false;
let TICKET_ON_SCREEN = false;
function ticketStepCount() { return document.querySelectorAll('.ticket-step').length || 4; }
function ticketRestartTimerLine(ms) {
  const ticket = document.querySelector('.ticket');
  const line = document.querySelector('.ticket-timer');
  if (!ticket || !line) return;
  ticket.style.setProperty('--ticket-step-ms', ms + 'ms');
  line.classList.remove('run');
  void line.offsetWidth;
  line.classList.add('run');
}
function ticketStopAutoplay() {
  if (TICKET_TIMER) clearTimeout(TICKET_TIMER);
  TICKET_TIMER = null;
  const ticket = document.querySelector('.ticket');
  if (ticket) ticket.classList.remove('autoplaying');
}
function ticketCanPlay() {
  const home = document.getElementById('screen-home');
  return !V57_REDUCED_MOTION && TICKET_ON_SCREEN && !document.hidden && !!home && home.classList.contains('active');
}
function ticketScheduleNext() {
  if (TICKET_TIMER) clearTimeout(TICKET_TIMER);
  const ticket = document.querySelector('.ticket');
  if (!ticket) return;
  const atEnd = TICKET_STAGE >= ticketStepCount() - 1;
  const wait = atEnd ? TICKET_LAST_HOLD_MS : TICKET_STEP_MS;
  ticket.classList.add('autoplaying');
  ticketRestartTimerLine(wait);
  TICKET_TIMER = setTimeout(() => {
    if (TICKET_PAUSED || !ticketCanPlay()) { ticket.classList.remove('autoplaying'); TICKET_TIMER = null; return; }
    if (atEnd) {
      ticket.classList.add('resetting');
      setTimeout(() => { ticket.classList.remove('resetting'); ticketGo(0, true); ticketScheduleNext(); }, 420);
    } else {
      ticketGo(TICKET_STAGE + 1, true);
      ticketScheduleNext();
    }
  }, wait);
}
function ticketResumeSoon(ms) {
  if (TICKET_RESUME_TIMER) clearTimeout(TICKET_RESUME_TIMER);
  TICKET_RESUME_TIMER = setTimeout(() => { if (!TICKET_PAUSED && ticketCanPlay()) ticketScheduleNext(); }, ms);
}
function setupTicketMotion() {
  const ticket = document.querySelector('.ticket');
  if (!ticket) return;
  if (!ticket.querySelector('.ticket-timer')) ticket.insertAdjacentHTML('beforeend', '<div class="ticket-timer" aria-hidden="true"></div>');
  const foot = ticket.querySelector('.ticket-foot');
  if (foot) {
    foot.addEventListener('mouseenter', () => { TICKET_PAUSED = true; ticketStopAutoplay(); });
    foot.addEventListener('mouseleave', () => { TICKET_PAUSED = false; ticketResumeSoon(1500); });
  }
  ticket.addEventListener('focusin', (e) => { if (e.target.matches(':focus-visible')) { TICKET_PAUSED = true; ticketStopAutoplay(); } });
  ticket.addEventListener('focusout', () => { TICKET_PAUSED = false; ticketResumeSoon(TICKET_RESUME_AFTER_MS); });
  ticket.addEventListener('click', (e) => {
    if (!e.target.closest('.ticket-step, .ticket-next')) return;
    ticketStopAutoplay();
    ticketResumeSoon(TICKET_RESUME_AFTER_MS);
  });
  if (V57_REDUCED_MOTION) return;
  const start = () => { if (!TICKET_TIMER && !TICKET_PAUSED && ticketCanPlay()) ticketScheduleNext(); };
  if ('IntersectionObserver' in window) {
    let first = true;
    new IntersectionObserver(entries => {
      TICKET_ON_SCREEN = entries.some(en => en.isIntersecting);
      if (TICKET_ON_SCREEN) setTimeout(start, first ? 1200 : 300);
      first = false;
    }, { threshold: 0.35 }).observe(ticket);
  } else { TICKET_ON_SCREEN = true; setTimeout(start, 1200); }
  document.addEventListener('visibilitychange', () => { if (!document.hidden) setTimeout(start, 400); });
  // Coming back to the home page from another screen
  const home = document.getElementById('screen-home');
  if (home) new MutationObserver(() => { if (home.classList.contains('active')) setTimeout(start, 500); }).observe(home, { attributes: true, attributeFilter: ['class'] });
}

// "What we check" icons draw themselves once, when that section comes
// into view.
function setupChecksDrawing() {
  const section = document.querySelector('.checks');
  if (!section || V57_REDUCED_MOTION) return;
  section.querySelectorAll('.checks-icon svg *').forEach(shape => shape.setAttribute('pathLength', '1'));
  section.classList.add('pre-draw');
  whenVisible(section, () => { section.classList.add('drawing'); section.classList.remove('pre-draw'); }, 0.4);
}

// Search results arriving: cards settle in and the heading is marked.
function markResultsArrived() {
  if (V57_REDUCED_MOTION) return;
  const grid = document.getElementById('providers-grid');
  const title = document.getElementById('providers-title');
  if (grid) { grid.classList.remove('just-arrived'); void grid.offsetWidth; grid.classList.add('just-arrived'); setTimeout(() => grid.classList.remove('just-arrived'), 1200); }
  if (title) { title.classList.remove('is-fresh'); void title.offsetWidth; title.classList.add('is-fresh'); setTimeout(() => title.classList.remove('is-fresh'), 2200); }
}

function setupHomepageMotion() {
  const hero = document.querySelector('.hero');
  if (hero && !V57_REDUCED_MOTION) {
    hero.classList.add('intro');
    setTimeout(() => hero.classList.remove('intro'), 2000); // arrival plays once per visit
  }
  if (hero && 'IntersectionObserver' in window) {
    new IntersectionObserver(entries => { HERO_VISIBLE = entries.some(e => e.isIntersecting); }, { threshold: 0.2 }).observe(hero);
  }
  window.addEventListener('resize', () => { const b = document.querySelector('.hero-blank'); if (b) b.style.width = ''; });
  setupTicketMotion();
  setupChecksDrawing();
  // Count the real numbers up when the band is actually seen, not while
  // it's still below the fold on a phone.
  const band = document.querySelector('.stats-strip');
  if (band && !V57_REDUCED_MOTION) {
    band.dataset.waiting = '1';
    whenVisible(band, () => { delete band.dataset.waiting; if (typeof band._pending === 'function') band._pending(); }, 0.5);
  }
}

/* ══════════════════════ v59: PHONES AND ALL SCREEN SIZES ══════════════════════ */
function toggleNavMenu(e) {
  e.stopPropagation();
  const nav = e.currentTarget.closest('.navbar');
  const open = !nav.classList.contains('menu-open');
  closeNavMenus();
  if (open) { nav.classList.add('menu-open'); e.currentTarget.setAttribute('aria-expanded', 'true'); }
}
function closeNavMenus() {
  document.querySelectorAll('.navbar.menu-open').forEach(n => {
    n.classList.remove('menu-open');
    const b = n.querySelector('.nav-menu-btn'); if (b) b.setAttribute('aria-expanded', 'false');
  });
}
// Keeps the current dashboard section visible in the sideways section bar
// on phones, and drops the edge fade once the end is reached.
function centerActiveDashNav() {
  document.querySelectorAll('.screen.active .dash-nav').forEach(nav => {
    const active = nav.querySelector('.dash-nav-item.active');
    if (active && nav.scrollWidth > nav.clientWidth) {
      nav.scrollLeft = active.offsetLeft - (nav.clientWidth - active.offsetWidth) / 2;
    }
    updateDashNavFade(nav);
  });
}
function updateDashNavFade(nav) {
  nav.classList.toggle('at-end', nav.scrollLeft + nav.clientWidth >= nav.scrollWidth - 4);
}
function syncBannerShortText() {
  const full = document.getElementById('test-mode-banner-text');
  const short = document.getElementById('test-mode-banner-short');
  if (!full || !short) return;
  const cardWarning = /real card/i.test(full.textContent);
  short.innerHTML = cardWarning
    ? "<strong>" + escapeHtml(t('banner_short_title')) + "</strong> " + escapeHtml(t('banner_short_body'))
    : "<strong>" + escapeHtml(t('banner_short_title')) + "</strong> " + escapeHtml(t('banner_short_generic'));
}
function setupAllScreenSizes() {
  document.addEventListener('click', (e) => { if (!e.target.closest || !e.target.closest('.navbar.menu-open .nav-more')) closeNavMenus(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeNavMenus(); });
  document.addEventListener('scroll', (e) => { if (e.target.classList && e.target.classList.contains('dash-nav')) updateDashNavFade(e.target); }, true);
  document.addEventListener('click', (e) => { if (e.target.closest && e.target.closest('.dash-nav-item')) requestAnimationFrame(centerActiveDashNav); });
  ['selectCustomerSection', 'selectProviderSection', 'selectAdminSection'].forEach(name => {
    const original = window[name];
    if (typeof original !== 'function') return;
    window[name] = function () { const r = original.apply(this, arguments); requestAnimationFrame(centerActiveDashNav); if (r && typeof r.then === 'function') r.then(() => requestAnimationFrame(centerActiveDashNav)); return r; };
  });
  window.addEventListener('resize', () => { if (window.innerWidth > 760) closeNavMenus(); centerActiveDashNav(); });
  const banner = document.getElementById('test-mode-banner');
  const full = document.getElementById('test-mode-banner-text');
  if (banner && full) {
    const more = document.createElement('button');
    more.type = 'button'; more.className = 'banner-more'; more.textContent = t('banner_details');
    more.setAttribute('aria-expanded', 'false');
    more.onclick = () => { const x = banner.classList.toggle('expanded'); more.textContent = t(x ? 'banner_less' : 'banner_details'); more.setAttribute('aria-expanded', x ? 'true' : 'false'); };
    full.after(more);
    syncBannerShortText();
    new MutationObserver(syncBannerShortText).observe(full, { childList: true, subtree: true, characterData: true });
  }
}

/* ══════════════════════ v60: MOVING FRONT PAGE ══════════════════════ */
