async function loadContentOverrides() {
  if (!BACKEND_AVAILABLE) return;
  try {
    const { overrides } = await apiFetch('GET', '/content-overrides');
    CONTENT_OVERRIDES = overrides || {};
    refreshAfterWordingChange();
  } catch (e) { /* built-in wording stays */ }
}
function refreshAfterWordingChange() {
  applyTranslations();
  if (typeof ticketGo === 'function' && document.querySelector('.ticket-step')) {
    const note = document.getElementById('ticket-note');
    const chip = document.getElementById('ticket-status');
    if (note) note.textContent = t('ticket_n' + (TICKET_STAGE + 1));
    if (chip) chip.textContent = t('ticket_status_' + (TICKET_STAGE + 1));
  }
  if (typeof OPEN_CHECK !== 'undefined' && OPEN_CHECK >= 0) {
    const panel = document.getElementById('checks-panel');
    if (panel && !panel.hidden) panel.innerHTML = checksPanelHTML(OPEN_CHECK);
  }
  document.querySelectorAll('.check-card').forEach((c, k) => { const m = c.querySelector('.checks-more'); if (m) m.textContent = t(k === OPEN_CHECK ? 'checks_less' : 'checks_more'); });
  if (typeof HERO_LOCALES !== 'undefined' && HERO_LOCALES) renderHeroLocales(HERO_LOCALES);
  if (typeof loadPopularProjects === 'function') loadPopularProjects();
  if (typeof renderHomepageFAQ === 'function') {
    const open = [...document.querySelectorAll('#homepage-faq-list .faq-item.open')].map(el => el.id);
    renderHomepageFAQ();
    open.forEach(id => { const el = document.getElementById(id); if (el) el.classList.add('open'); });
  }
}
function builtInEnglish(key) { return (I18N.en && I18N.en[key]) || ''; }

// Admin: the editor itself. Every box starts with the text visitors see
// now. Only boxes that differ from the built-in wording are saved.
async function loadWordingEditor() {
  const box = document.getElementById('wording-editor');
  if (!box || !BACKEND_AVAILABLE) return;
  let current = {};
  try { current = (await apiFetch('GET', '/admin/settings/content-overrides')).overrides || {}; }
  catch (e) { box.innerHTML = `<div class="ver-note">${escapeHtml(e.message || 'Could not load the wording')}</div>`; return; }
  box.innerHTML = EDITABLE_CONTENT_GROUPS.map((g, gi) => {
    const changed = g.keys.filter(k => current[k.key]).length;
    return `<details class="we-group"${gi === 0 ? ' open' : ''}>
      <summary><span>${escapeHtml(g.title)}</span>${changed ? `<em>${changed} changed</em>` : ''}</summary>
      <div class="we-fields">${g.keys.map(k => {
        const def = builtInEnglish(k.key);
        const val = current[k.key] || def;
        const long = k.long || def.length > 70;
        return `<label class="we-field${current[k.key] ? ' is-changed' : ''}">
          <span class="we-label">${escapeHtml(k.label)}${current[k.key] ? '<b>changed</b>' : ''}</span>
          ${long ? `<textarea class="form-input" rows="3" data-key="${k.key}"${k.hint ? ` placeholder="${escapeHtml(k.hint)}"` : ''} oninput="markWordingChanged(this)">${escapeHtml(val)}</textarea>` : `<input class="form-input" data-key="${k.key}" value="${escapeHtml(val)}" oninput="markWordingChanged(this)"/>`}
          <button type="button" class="we-reset" onclick="resetWordingField('${k.key}')" title="Put back the built-in wording">Reset</button>
        </label>`;
      }).join('')}</div>
    </details>`;
  }).join('');
}
function markWordingChanged(el) {
  const field = el.closest('.we-field');
  if (field) field.classList.toggle('is-changed', el.value.trim() !== builtInEnglish(el.dataset.key));
}
function resetWordingField(key) {
  const el = document.querySelector(`#wording-editor [data-key="${key}"]`);
  if (!el) return;
  el.value = builtInEnglish(key);
  markWordingChanged(el);
}
async function saveWording() {
  const overrides = {};
  for (const el of document.querySelectorAll('#wording-editor [data-key]')) {
    const v = el.value.trim();
    if (/[<>]/.test(v)) return showToast('Please don\'t use < or > in the wording');
    if (v && v !== builtInEnglish(el.dataset.key)) overrides[el.dataset.key] = v;
  }
  try {
    const res = await apiFetch('PATCH', '/admin/settings/content-overrides', { overrides });
    CONTENT_OVERRIDES = res.overrides || {};
    showToast(`Saved. ${Object.keys(CONTENT_OVERRIDES).length} piece${Object.keys(CONTENT_OVERRIDES).length === 1 ? '' : 's'} of text changed from the built-in wording. Live now.`);
    refreshAfterWordingChange();
    loadWordingEditor();
  } catch (e) { showToast(e.message || 'Could not save the wording'); }
}
async function resetAllWording() {
  const ok = await confirmDialog('Put every piece of front-page wording back to the built-in text? This affects the live site straight away.', { confirmLabel: 'Reset everything', danger: true });
  if (!ok) return;
  try {
    await apiFetch('PATCH', '/admin/settings/content-overrides', { overrides: {} });
    CONTENT_OVERRIDES = {};
    showToast('All front-page wording is back to the built-in text');
    refreshAfterWordingChange();
    loadWordingEditor();
  } catch (e) { showToast(e.message || 'Could not reset'); }
}

(async function initApp() {
  document.documentElement.dir = I18N[CURRENT_LANG].rtl ? 'rtl' : 'ltr';
  document.documentElement.lang = CURRENT_LANG;
  const footerLogoImg = document.getElementById('footer-logo-img');
  if (footerLogoImg) footerLogoImg.src = LOGO_IMG_FULL;
  const faviconLink = document.createElement('link');
  faviconLink.rel = 'icon';
  faviconLink.type = 'image/png';
  faviconLink.href = LOGO_IMG_ICON;
  document.head.appendChild(faviconLink);

  renderNavbar('navbar-home', 'home');
  applyTranslations();
  renderProviders(PROVIDERS); // paint immediately with fallback data, then upgrade if backend is live
  renderHomeCategories();
  renderHomepageFAQ();
  startHeroWordRotation(); // works immediately with the default word list, even offline
  setupHomepageV57();
  setupAllScreenSizes();
  setupReveals();
  setupV62();
  setupPublicPages();
  setupInteractiveChecks();
  initChatBubbleDrag();
  initChatBubbleModalGuard();
  await checkBackend();
  if (BACKEND_AVAILABLE) {
    await Promise.all([loadProviders(), loadCategories(), loadGeoData(), loadPlatformStats(), loadSupportContact(), loadFooterInfo(), loadHomepageContent(), loadHomepageImages(), loadPopularProjects()]);
    renderProviders(PROVIDERS);
    renderHomeCategories();
    loadShowcase();
    loadContentOverrides();
    console.log('%cTrothen API connected — live data enabled.', 'color:#1D5FA8;font-weight:bold;');
  } else {
    console.log('%cTrothen API not detected — running on demo data. Start the backend (npm start in /trothen-backend) for live data.', 'color:var(--gold);');
  }
  loadFeaturedCarousel();
  if (BACKEND_AVAILABLE) loadSystemStatusBanner();

  // If the page was opened with ?resetToken=... (what a real password-reset
  // email link would look like), jump straight to the reset-password form —
  // this is the same code path as clicking "Open Reset Link Now" in test mode.
  const urlParams = new URLSearchParams(window.location.search);
  const urlResetToken = urlParams.get('resetToken');
  const urlInviteCode = urlParams.get('invite');
  const urlReferralCode = urlParams.get('ref');
  const urlVerify = urlParams.get('verify') === '1';
  if (urlResetToken) {
    showResetPasswordForm(urlResetToken);
  } else if (urlVerify) {
    // Opened from the verification-invite email. Remove the parameter so a
    // refresh doesn't repeat this, then either restore the saved session
    // (a stored token is only a token — the user object has to be fetched
    // from /auth/me first) or ask them to sign in with a clear reason.
    try { history.replaceState(null, '', window.location.pathname); } catch (e) {}
    OPEN_VERIFICATION_AFTER_AUTH = true;
    const savedToken = BACKEND_AVAILABLE ? getSavedAuthToken() : null;
    let restored = false;
    if (savedToken) {
      try {
        AUTH.token = savedToken;
        const { user } = await fetchMeWithRetry();
        AUTH.user = user;
        restored = true;
        await completeAuthAndResumeIntent(user.role);
      } catch (e) {
        AUTH.token = null;
        AUTH.user = null;
        if (restoreFailureIsFinal(e)) clearAuthSession(); // v105: only when the server refused the session
      }
    }
    if (!restored) {
      showAuth('login');
      showToast('Sign in to finish verifying your identity');
    }
  } else if (urlInviteCode && !getSavedAuthToken()) {
    // An organization invite link — jump straight to a provider signup
    // form with the code pre-filled and already validated, rather than
    // making someone find the field themselves.
    showAuth('signup');
    setAuthRole('provider');
    const codeInput = document.getElementById('auth-invite-code');
    if (codeInput) { codeInput.value = urlInviteCode.toUpperCase(); checkInviteCode(urlInviteCode); }
  } else if (urlReferralCode && !getSavedAuthToken()) {
    // A referral link — carried silently through to /signup/start rather
    // than shown as its own form field (nobody types a referral code by
    // hand; it only ever arrives via a link). Who the code belongs to is
    // never exposed client-side — the server checks it privately at
    // signup and simply won't attach an invalid one.
    pendingReferralCode = urlReferralCode.trim().toUpperCase();
    showAuth('signup');
    showToast("You're signing up through a friend's referral link!");
  } else if (BACKEND_AVAILABLE) {
    // Otherwise, try to restore a real prior session — this is what makes an
    // ordinary browser refresh not silently log someone out. The saved
    // token is always re-validated against the live server (not just
    // trusted as-is), so a suspended account or an expired token correctly
    // falls through to the normal signed-out homepage instead of
    // half-restoring a session that shouldn't work anymore.
    const savedToken = getSavedAuthToken();
    if (savedToken) {
      try {
        AUTH.token = savedToken;
        const { user } = await fetchMeWithRetry();
        AUTH.user = user;
        await completeAuthAndResumeIntent(user.role);
      } catch (e) {
        AUTH.token = null;
        AUTH.user = null;
        // v105: the saved sign-in is only thrown away when the server said
        // it is no longer good. A dropped connection while the page was
        // loading used to sign the person out for good; now the sign-in is
        // kept and works again on the next page load.
        if (restoreFailureIsFinal(e)) clearAuthSession();
        else showToast(tr("Couldn't reach Trothen just now. Check your connection and reload the page."));
      }
    }
  }
})();

// Registers the pass-through service worker (see /sw.js) so the app meets
// Chrome's installability criteria and can be added to a phone's home
// screen like a native app. Never blocks or affects page load either way.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch(() => { /* installability is a bonus, not a requirement — fail silently */ });
  });

  // Item 2's real background notifications: when the OS-level
  // notification is clicked while the app was closed, the service worker
  // (see /sw.js) focuses this tab and posts the original linkTo back to
  // it — this is what actually navigates to the right section, reusing
  // the exact same function an in-app notification click already uses.
  navigator.serviceWorker.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'notification-click') {
      navigateFromNotification(event.data.linkTo);
    }
  });

  // Reflects the REAL current subscription state (not a stored
  // preference) the moment the app loads, so the Settings toggle below
  // never shows "on" when the browser has actually lost or revoked the
  // subscription behind the scenes.
  window.__pushSubscribed = false;
  navigator.serviceWorker.ready.then(reg => reg.pushManager.getSubscription()).then(sub => { window.__pushSubscribed = !!sub; }).catch(() => {});
}

// A VAPID public key arrives from the server as URL-safe base64; the
// browser's Push API needs it as a raw byte array instead — this is the
// standard, unavoidable conversion every Web Push implementation does.
function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = atob(base64);
  return Uint8Array.from([...rawData].map(c => c.charCodeAt(0)));
}

// The actual enable/disable action behind the "Push notifications"
// toggle in Settings. Takes the checkbox element itself (rather than
// just the boolean) so a failure — permission denied, server not
// configured, browser doesn't support it — can visibly revert the
// toggle instead of leaving it showing a state that isn't real.
async function togglePushNotifications(checkbox) {
  const enable = checkbox.checked;
  if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
    checkbox.checked = false;
    return showToast('Push notifications aren\'t supported in this browser');
  }
  try {
    if (enable) {
      const permission = await Notification.requestPermission();
      if (permission !== 'granted') {
        checkbox.checked = false;
        return showToast('Notification permission was not granted');
      }
      const { configured, publicKey } = await apiFetch('GET', '/push/vapid-public-key');
      if (!configured) {
        checkbox.checked = false;
        return showToast('Push notifications aren\'t set up on the server yet');
      }
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(publicKey) });
      await apiFetch('POST', '/push/subscribe', sub.toJSON());
      window.__pushSubscribed = true;
      showToast('Push notifications enabled — you\'ll get alerts even when Trothen is closed');
    } else {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      if (sub) {
        await apiFetch('POST', '/push/unsubscribe', { endpoint: sub.endpoint });
        await sub.unsubscribe();
      }
      window.__pushSubscribed = false;
      showToast('Push notifications turned off');
    }
  } catch (e) {
    checkbox.checked = !enable;
    showToast(e.message || 'Could not update push notification settings');
  }
}

function pushToggleHTML() {
  // Doesn't render at all in a browser that can't do this (older Safari,
  // some in-app browsers) — a toggle for something guaranteed to fail
  // is worse than no toggle.
  if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) return '';
  const isOn = window.__pushSubscribed === true;
  return `<div class="switch-row"><div><div class="switch-label">Push notifications</div><div class="switch-sub">Get alerts even when Trothen isn't open in a tab</div></div><label class="switch"><input type="checkbox" ${isOn ? 'checked' : ''} onchange="togglePushNotifications(this)"><span class="switch-track"></span></label></div>`;
}

/* ══════════════════════ v105: PRO STORE, EXTRA SKILLS, PICK-UP & DROP-OFF ══════════════════════
   A pro can open a store and sell goods to their customers. Outside the
   store only its NAME is shown, under the pro. Goods and prices are shown
   only inside the store. What a customer picks is added to the booking as
   the materials cost and paid for when they book. */
const usd = (n) => '$' + (Math.round(Number(n || 0) * 100) / 100).toFixed(2).replace(/\.00$/, '');
const usd2 = (n) => '$' + (Math.round(Number(n || 0) * 100) / 100).toFixed(2);
const RAW_CONTRACTS = {}; // every booking as the server sent it, by id (goods, pick-up and drop-off records)
function cacheRawContracts(list) { for (const c of (list || [])) RAW_CONTRACTS[c.id] = c; }
function v105Close(id) { const o = document.getElementById(id); if (o) o.remove(); }
function v105Overlay(id, inner, maxWidth) {
  v105Close(id);
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-overlay open" id="${id}" style="z-index:5200;" onclick="if(event.target===this)v105Close('${id}')"><div class="modal" style="max-width:min(${maxWidth || 560}px,96vw);width:96vw;max-height:94vh;display:flex;flex-direction:column;" role="dialog" aria-modal="true">${inner}</div></div>`);
}
async function v105UploadPhoto(path, file) {
  if (!file) return null;
  if (!/^image\//.test(file.type || '') && !/\.hei[cf]$/i.test(file.name || '')) { showToast(tr('Please choose a photo')); return null; }
  const fd = new FormData();
  fd.append('photo', await prepareImageForUpload(file, { maxSide: 1800, quality: 0.86 }));
  const res = await fetch(API_BASE + path, { method: 'POST', headers: { 'Authorization': 'Bearer ' + AUTH.token }, body: fd });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || 'Upload failed');
  return data.url;
}
async function v105Download(path, filename) {
  try {
    const res = await fetch(API_BASE + path, { headers: { 'Authorization': 'Bearer ' + AUTH.token } });
    if (!res.ok) { const d = await res.json().catch(() => ({})); throw new Error(d.error || 'Could not make the file'); }
    const url = URL.createObjectURL(await res.blob());
    const a = document.createElement('a'); a.href = url; a.download = filename; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
  } catch (e) { showToast(e.message || 'Could not download'); }
}
function v105Photo(url, size) {
  return `<img src="${escapeHtml(url)}" alt="" loading="lazy" onclick="v105Zoom(${jsArg(url)})" style="width:${size}px;height:${size}px;object-fit:cover;border-radius:8px;border:1px solid var(--border);cursor:zoom-in;flex-shrink:0;"/>`;
}
function v105Zoom(url) {
  v105Close('v105-zoom');
  document.body.insertAdjacentHTML('beforeend', `<div id="v105-zoom" onclick="this.remove()" style="position:fixed;inset:0;z-index:6000;background:rgba(10,14,22,.9);display:flex;align-items:center;justify-content:center;padding:16px;cursor:zoom-out;"><img src="${escapeHtml(url)}" alt="" style="max-width:100%;max-height:100%;border-radius:8px;"/></div>`);
}

