async function saveTool() {
  const g = (id) => document.getElementById(id).value.trim();
  const body = { name: g('tf-name'), serial: g('tf-serial'), condition: g('tf-condition'), location: g('tf-location'), value: g('tf-value') === '' ? null : Number(g('tf-value')), boughtOn: g('tf-bought') || null, serviceDue: g('tf-service') || null, notes: g('tf-notes') };
  if (body.name.length < 2) return showToast('Give the tool a name');
  try {
    if (window.__toolId) await apiFetch('PATCH', '/business/tools/' + encodeURIComponent(window.__toolId), body); else await apiFetch('POST', '/business/tools', body);
    v105Close('tool-form-overlay'); showToast('Saved'); bizTools();
  } catch (e) { showToast(e.message || 'Could not save'); }
}
async function deleteTool(id) {
  if (!(await confirmDialog('Remove this tool from your list?', { confirmLabel: 'Remove', danger: true }))) return;
  try { await apiFetch('DELETE', '/business/tools/' + encodeURIComponent(id)); showToast('Removed'); bizTools(); } catch (e) { showToast(e.message || 'Could not remove'); }
}

