// Licence proof for an extra skill in a licensed trade.
async function uploadSkillLicence(input) {
  const file = input.files && input.files[0]; input.value = '';
  if (!file) return;
  const category = input.dataset.licFile;
  const exp = document.querySelector(`[data-lic-expiry="${CSS.escape(category)}"]`);
  const expiry = exp ? exp.value : '';
  if (!expiry) return showToast(tr('Enter the date the licence expires first'));
  const fd = new FormData();
  fd.append('category', category); fd.append('expiry', expiry);
  try {
    fd.append('file', file.type === 'application/pdf' ? file : await prepareImageForUpload(file, { maxSide: 2400, quality: 0.9 }));
    showToast(tr('Uploading…'));
    const res = await fetch(API_BASE + '/skills/licence/upload', { method: 'POST', headers: { 'Authorization': 'Bearer ' + AUTH.token }, body: fd });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || 'Upload failed');
    showToast(tr('Licence attached. A manager will check it.'));
    loadExtraSkillsPanel();
  } catch (e) { showToast(e.message || 'Could not upload the licence'); }
}
async function viewSkillLicence(providerId, category) {
  try {
    const res = await fetch(API_BASE + `/admin/skills/${encodeURIComponent(providerId)}/licence?category=${encodeURIComponent(category)}`, { headers: { 'Authorization': 'Bearer ' + AUTH.token } });
    if (!res.ok) { const d = await res.json().catch(() => ({})); throw new Error(d.error || 'Could not open the licence'); }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const isPdf = blob.type === 'application/pdf';
    v105Overlay('licence-view-overlay', `<div class="modal-header"><button class="modal-close" onclick="v105Close('licence-view-overlay')" aria-label="Close">✕</button><h3>Licence for ${escapeHtml(category)}</h3><p>Opening this was recorded in the access log.</p></div>
      <div class="modal-body" style="overflow:auto;flex:1 1 auto;min-height:0;">${isPdf ? `<iframe src="${url}" title="Licence" style="width:100%;height:70vh;border:1px solid var(--border);border-radius:8px;"></iframe>` : `<img src="${url}" alt="Licence" style="max-width:100%;border-radius:8px;"/>`}</div>`, 820);
    setTimeout(() => URL.revokeObjectURL(url), 5 * 60 * 1000);
  } catch (e) { showToast(e.message || 'Could not open the licence'); }
}
// If the privacy policy was edited in Settings, say what it is missing.
async function loadStorePrivacyNote() {
  const box = document.getElementById('store-privacy-note'); if (!box) return;
  let d; try { d = await apiFetch('GET', '/admin/store/privacy-check'); } catch (e) { return; }
  if (!d.edited || !d.missing.length) { box.innerHTML = ''; return; }
  const names = { stores: 'what is collected for stores and business tools', handover: 'location at pick-up and drop-off', 'handover-kept': 'how long pick-up and drop-off locations are kept' };
  box.innerHTML = `<div class="panel" style="border-left:4px solid #C98A2B;"><div class="panel-title">The privacy policy is missing ${d.missing.length} paragraph${d.missing.length === 1 ? '' : 's'}</div>
    <div style="font-size:14px;line-height:1.6;margin-bottom:10px;">The privacy policy was edited and saved in Settings, so it did not pick up the paragraphs that cover the new features: ${d.missing.map(k => escapeHtml(names[k] || k)).join('; ')}. Nothing else in the saved policy is changed.</div>
    ${STORE_REVIEW && STORE_REVIEW.canEditSettings ? `<button class="btn-sm btn-sm-primary" onclick="applyPrivacyAdditions()">Add the missing paragraphs</button>` : '<div class="ver-note">A super admin can add them here.</div>'}</div>`;
}
async function applyPrivacyAdditions() {
  try { const r = await apiFetch('POST', '/admin/store/privacy-check/apply'); showToast(r.added.length ? `Added ${r.added.length} paragraph${r.added.length === 1 ? '' : 's'} to the privacy policy` : 'Nothing was missing'); loadStorePrivacyNote(); }
  catch (e) { showToast(e.message || 'Could not update the privacy policy'); }
}
{ const _loadAdminStores = loadAdminStores; loadAdminStores = async function () { await _loadAdminStores(); loadStorePrivacyNote(); }; }

// PRO: send a quote, estimate or invoice to a customer on Trothen.
