    v105Close('store-checkout-overlay'); v105Close('pro-store-overlay');
    if (typeof closeProQuickView === 'function') { try { closeProQuickView(); } catch (e) {} }
    showToast(`${tr('Paid. Order')} #${r.order.number}`);
