// ── HEIC PHOTOS ────────────────────────────────────────────────────────
// Some phones save photos as HEIC, which most browsers can't open. These
// were refused. Now the page converts them to JPEG itself before sending:
// first by asking the browser (Safari can), then with a decoder that runs
// in the background on this device. Nothing is sent anywhere to convert.
const HEIC_MAX_BYTES = 40 * 1024 * 1024;
function looksLikeHeic(file) { return !!file && (/heic|heif/i.test(file.type || '') || /\.hei[cf]$/i.test(file.name || '')); }
function heicToJpeg(file, maxSide, quality) {
  return new Promise((resolve, reject) => {
    if (typeof Worker === 'undefined' || typeof WebAssembly === 'undefined') return reject(new Error('unsupported'));
    if (file.size > HEIC_MAX_BYTES) return reject(new Error('too big'));
    let worker;
    try { worker = new Worker('/vendor/libheif/heic-worker.js'); } catch (e) { return reject(e); }
    const stop = (fn, v) => { clearTimeout(timer); try { worker.terminate(); } catch (e) {} fn(v); };
    const timer = setTimeout(() => stop(reject, new Error('timeout')), 90000);
    worker.onerror = (e) => stop(reject, new Error((e && e.message) || 'worker failed'));
    worker.onmessage = (ev) => {
      const d = ev.data || {};
      if (d.error || !d.buffer) return stop(reject, new Error(d.error || 'failed'));
      clearTimeout(timer); try { worker.terminate(); } catch (e) {}
      try {
        const full = document.createElement('canvas'); full.width = d.width; full.height = d.height;
        full.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(d.buffer), d.width, d.height), 0, 0);
        const scale = Math.min(1, (maxSide || 2400) / Math.max(d.width, d.height));
        let out = full;
        if (scale < 1) { out = document.createElement('canvas'); out.width = Math.max(1, Math.round(d.width * scale)); out.height = Math.max(1, Math.round(d.height * scale)); const c = out.getContext('2d'); c.imageSmoothingQuality = 'high'; c.drawImage(full, 0, 0, out.width, out.height); full.width = full.height = 1; }
        out.toBlob((blob) => { out.width = out.height = 1; blob ? resolve(new File([blob], String(file.name || 'photo').replace(/\.[^.]+$/, '') + '.jpg', { type: 'image/jpeg' })) : reject(new Error('could not save')); }, 'image/jpeg', quality || 0.9);
      } catch (e) { reject(e); }
    };
    file.arrayBuffer().then((buf) => worker.postMessage({ buffer: buf }, [buf])).catch((e) => stop(reject, e));
  });
}
{ const _prepareImageForUpload = prepareImageForUpload; prepareImageForUpload = async function (file, opts) {
  if (!looksLikeHeic(file)) return _prepareImageForUpload.apply(this, arguments);
  try { return await _prepareImageForUpload.apply(this, arguments); } catch (e) { /* this browser can't open it by itself */ }
  showToast(tr('Converting your photo. This can take a few seconds…'));
  try { return await heicToJpeg(file, (opts && opts.maxSide) || 2400, (opts && opts.quality) || 0.9); }
  catch (e) { console.warn('HEIC conversion failed:', e && e.message); throw new Error(tr('That photo is in HEIC format and this device could not convert it. Take the photo again from this page, or save it as JPEG first.')); }
}; }
// On a computer the file chooser hides .heic files when it is asked for "images". Add them, except on iPhones
// and iPads, which already hand over a JPEG when asked for an image.
document.addEventListener('click', (ev) => {
  const el = ev.target;
  if (!el || el.tagName !== 'INPUT' || el.type !== 'file') return;
  const acc = el.getAttribute('accept') || '';
  const apple = /iP(hone|ad|od)/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  if (!apple && /image\//.test(acc) && !/heic/i.test(acc)) el.setAttribute('accept', acc + ',.heic,.heif');
}, true);

// The booking form no longer has its own "goods only" tick box. Buying goods
// with no job is the store checkout now (paid and confirmed at once, with a
// choice of how to get them), so the form points there instead.
function drawBookingGoods() {
  const slot = document.getElementById('booking-goods-slot'); const p = BOOKING_BASKET_PRICED;
  if (!slot || !p || !currentPro) return;
  BOOKING_GOODS_ONLY = false;
  const job = bookingJobAmount();
  const jobFee = job > 0 ? Math.round(Math.min(Math.max(job * 0.09, 2.99), 25) * 100) / 100 : 0;
  const total = job + jobFee + p.goodsTotal + p.purchaseFee;
  slot.innerHTML = `
    <div class="booking-summary" style="margin-top:10px;">
      <div class="summary-row" style="font-weight:700;color:var(--navy);"><span>🛍️ ${escapeHtml(tr('Goods from the store'))}</span><span><a onclick="closeModal();openProStore(${jsArg(currentPro.id)})" style="color:var(--teal);cursor:pointer;font-weight:600;">${escapeHtml(tr('Change'))}</a></span></div>
      ${p.items.map(i => `<div class="summary-row"><span>${i.qty} × ${escapeHtml(i.name)}</span><span>${i.priceCurrency ? escapeHtml(localMoney(i.priceSymbol, i.lineTotalLocal)) + ' ≈ ' : ''}${usd2(i.lineTotal)}</span></div>`).join('')}
      <div class="summary-row"><span>${escapeHtml(tr('Materials cost (goods)'))}</span><span>${usd2(p.goodsTotal)}</span></div>
      ${p.purchaseFee > 0 ? `<div class="summary-row"><span>${escapeHtml(tr('Store purchase fee'))}</span><span>${usd2(p.purchaseFee)}</span></div>` : ''}
      <div class="summary-row total"><span>${escapeHtml(tr('Total to pay now, job and goods'))}</span><span>${job > 0 ? usd2(total) : escapeHtml(tr('Enter your offer above'))}</span></div>
    </div>
    <div style="font-size:13.5px;margin:8px 0 4px;">${escapeHtml(tr('Only want the goods?'))} <a onclick="closeModal();openProStore(${jsArg(currentPro.id)}).then(()=>openStoreCheckout())" style="color:var(--teal);font-weight:600;cursor:pointer;">${escapeHtml(tr('Buy them without a booking'))}</a></div>
    <div class="ver-note">${escapeHtml(tr('The pro brings these goods to the job. Your money is held until you mark the job complete. The goods are sold by the pro, not by Trothen.'))}</div>`;
  applyGoodsOnlyToForm();
}

